      { t = "text", s = "¡Ahora estamos ocupados!" },
      { t = "scroll" },
      { t = "text", s = "¡Fuera de aquí!" },
      { t = "eos" },
    },
  ["g3:08173429"] = {
      { t = "text", s = "He visto una BAYA muy rara en la" },
      { t = "nl" },
      { t = "text", s = "basura. No sé de qué tipo será..." },
      { t = "eos" },
    },
  ["g3:08173462"] = {
      { t = "text", s = "¡Estoy tan ocupado que me estoy" },
      { t = "nl" },
      { t = "text", s = "mareando!" },
      { t = "eos" },
    },
  ["g3:081734a0"] = {
      { t = "text", s = "¿Por qué? ¿Por qué yo?" },
      { t = "para" },
      { t = "text", s = "¡Me paso todo el día pelando" },
      { t = "nl" },
      { t = "text", s = "patatas!" },
      { t = "eos" },
    },
  ["g3:081734d3"] = {
      { t = "text", s = "¿Has oído hablar de SNORLAX?" },
      { t = "para" },
      { t = "text", s = "¡Se pasa todo el día comiendo" },
      { t = "nl" },
      { t = "text", s = "y durmiendo!" },
      { t = "eos" },
    },
  ["g3:0817353e"] = {
      { t = "text", s = "Sniff...sniff..." },
      { t = "para" },
      { t = "text", s = "Yo sólo pelo cebollas..." },
      { t = "nl" },
      { t = "text", s = "Sniff..." },
      { t = "eos" },
    },
  ["g3:08173570"] = {
      { t = "text", s = "¡Ejem!" },
      { t = "nl" },
      { t = "text", s = "¡Por algo soy el CHEF!" },
      { t = "para" },
      { t = "text", s = "El menú es:" },
      { t = "eos" },
    },
  ["g3:0817359f"] = {
      { t = "text", s = "¡Ensalada de salmón!" },
      { t = "para" },
      { t = "text", s = "¡Pero puede que los clientes se" },
      { t = "nl" },
      { t = "text", s = "quejen de tanto repetir pescado!" },
      { t = "eos" },
    },
  ["g3:081735df"] = {
      { t = "text", s = "¡Anguilas a la barbacoa!" },
      { t = "para" },
      { t = "text", s = "¡Me temo que los clientes se van" },
      { t = "nl" },
      { t = "text", s = "a amotinar!" },
      { t = "eos" },
    },
  ["g3:08173611"] = {
      { t = "text", s = "¡Filetes de ternera!" },
      { t = "para" },
      { t = "text", s = "Pero ¡¿tengo bastantes filetes" },
      { t = "nl" },
      { t = "text", s = "para todos?!" },
      { t = "eos" },
    },
  ["g3:08173646"] = {
      { t = "text", s = "CAPITÁN: ¡Puajj!" },
      { t = "nl" },
      { t = "text", s = "Me siento fatal." },
      { t = "scroll" },
      { t = "text", s = "Me he mareado..." },
      { t = "eos" },
    },
  ["g3:08173676"] = {
      { t = "text", s = "¡" },
      { t = "player" },
      { t = "text", s = " le dio un masaje" },
      { t = "nl" },
      { t = "text", s = "al CAPITÁN!" },
      { t = "para" },
      { t = "text", s = "(Scratch)..." },
      { t = "nl" },
      { t = "text", s = "(Scratch)..." },
      { t = "eos" },
    },
  ["g3:081736a6"] = {
      { t = "text", s = "CAPITÁN: ¡Uff! ¡Gracias!" },
      { t = "nl" },
      { t = "text", s = "Ya me siento mucho mejor..." },
      { t = "para" },
      { t = "text", s = "¿Quieres ver mi técnica de CORTAR?" },
      { t = "para" },
      { t = "text", s = "Te la mostraría si no estuviera" },
      { t = "nl" },
      { t = "text", s = "tan mareado." },
      { t = "para" },
      { t = "text", s = "¡Ya sé!" },
      { t = "nl" },
      { t = "text", s = "¡Toma esto!" },
      { t = "para" },
      { t = "text", s = "¡Enséñasela a tu POKéMON" },
      { t = "nl" },
      { t = "text", s = "y en breve estará CORTANDO!" },
      { t = "eos" },
    },
  ["g3:081737af"] = {
      { t = "text", s = "¡" },
      { t = "player" },
      { t = "text", s = " obtuvo la MO01" },
      { t = "nl" },
      { t = "text", s = "de manos del CAPITÁN!" },
      { t = "eos" },
    },
  ["g3:081737d2"] = {
      { t = "text", s = "Al usar CORTE, se pueden talar" },
      { t = "nl" },
      { t = "text", s = "árboles pequeños." },
      { t = "para" },
      { t = "text", s = "A lo mejor deberías probarlo con" },
      { t = "nl" },
      { t = "text", s = "los árboles de CIUDAD CARMÍN." },
      { t = "eos" },
    },
  ["g3:08173831"] = {
      { t = "text", s = "CAPITÁN: ¡Bien!" },
      { t = "para" },
      { t = "text", s = "¡Ahora que ya no estoy mareado," },
      { t = "nl" },
      { t = "text", s = "creo que deberíamos irnos!" },
      { t = "para" },
      { t = "text", s = "¡El S.S. ANNE zarpará pronto!" },
      { t = "para" },
      { t = "text", s = "¡Adiós, hasta que volvamos" },
      { t = "nl" },
      { t = "text", s = "a CIUDAD CARMÍN!" },
      { t = "eos" },
    },
  ["g3:081738e6"] = {
      { t = "text", s = "¡Puaj!" },
      { t = "nl" },
      { t = "text", s = "¡No debería haber mirado!" },
      { t = "eos" },
    },
  ["g3:08173903"] = {
      { t = "text", s = "Cómo combatir el mareo..." },
      { t = "nl" },
      { t = "text", s = "¡El CAPITÁN está leyendo esto!" },
      { t = "eos" },
    },
  ["g3:0817393b"] = {
      { t = "text", s = "¡Ssh! ¡Soy agente de POLICÍA!" },
      { t = "para" },
      { t = "text", s = "¡Estoy siguiendo la pista del" },
      { t = "nl" },
      { t = "text", s = "TEAM ROCKET!" },
      { t = "eos" },
    },
  ["g3:08173999"] = {
      { t = "text", s = "¡Me gustan los POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¿Y a ti?" },
      { t = "eos" },
    },
  ["g3:081739b1"] = {
      { t = "text", s = "¡Guauu!" },
      { t = "nl" },
      { t = "text", s = "¡Eres genial!" },
      { t = "eos" },
    },
  ["g3:081739c5"] = {
      { t = "text", s = "Seamos amigos, ¿vale?" },
      { t = "para" },
      { t = "text", s = "¡Y así podremos intercambiar" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:08173a1a"] = {
      { t = "text", s = "¡He atrapado POKéMON por todo" },
      { t = "nl" },
      { t = "text", s = "el mundo!" },
      { t = "eos" },
    },
  ["g3:08173a4f"] = {
      { t = "text", s = "¡Vaya!" },
      { t = "nl" },
      { t = "text", s = "¡Con lo que he viajado por ellos!" },
      { t = "eos" },
    },
  ["g3:08173a7a"] = {
      { t = "text", s = "¡Les has hecho daño a mis pobres" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "para" },
      { t = "text", s = "¡¡¡Y exijo que los cures en un" },
      { t = "nl" },
      { t = "text", s = "CENTRO POKéMON!!!" },
      { t = "eos" },
    },
  ["g3:08173ac5"] = {
      { t = "text", s = "¡Viajamos en crucero por todo" },
      { t = "nl" },
      { t = "text", s = "el mundo!" },
      { t = "eos" },
    },
  ["g3:08173afa"] = {
      { t = "text", s = "¡Los cruceros son tan elegantes" },
      { t = "nl" },
      { t = "text", s = "y acogedores!" },
      { t = "eos" },
    },
  ["g3:08173b21"] = {
      { t = "text", s = "¡Siempre viajo con WIGGLYTUFF!" },
      { t = "eos" },
    },
  ["g3:08173b61"] = {
      { t = "text", s = "WIGGLYTUFF: ¡Wig, tuuuf, tuuuf!" },
      { t = "eos" },
    },
  ["g3:08173b79"] = {
      { t = "text", s = "¡Camarero, me gustaría tomar" },
      { t = "nl" },
      { t = "text", s = "un trozo de tarta de cereza!" },
      { t = "eos" },
    },
  ["g3:08173ba4"] = {
      { t = "text", s = "¡Camarera, me gustaría tomar" },
      { t = "nl" },
      { t = "text", s = "un trozo de tarta de cereza!" },
      { t = "eos" },
    },
  ["g3:08173bd1"] = {
      { t = "text", s = "¡Oye, tú, impertinente!" },
      { t = "nl" },
      { t = "text", s = "¿Cómo te atreves a entrar aquí?" },
      { t = "eos" },
    },
  ["g3:08173bfa"] = {
      { t = "text", s = "¡Oye!" },
      { t = "nl" },
      { t = "text", s = "¡¡No tienes educación!!" },
      { t = "eos" },
    },
  ["g3:08173c30"] = {
      { t = "text", s = "¡Me gustaría que me dejaras solo!" },
      { t = "nl" },
      { t = "text", s = "¡¡Fuera de aquí!!" },
      { t = "eos" },
    },
  ["g3:08173c52"] = {
      { t = "text", s = "¡Viajo solo!" },
      { t = "para" },
      { t = "text", s = "¡Mis POKéMON son mis únicos amigos!" },
      { t = "eos" },
    },
  ["g3:08173cb4"] = {
      { t = "text", s = "¡Oh! ¡Mis amigos!" },
      { t = "eos" },
    },
  ["g3:08173cc4"] = {
      { t = "text", s = "¡Deberías portarte bien con" },
      { t = "nl" },
      { t = "text", s = "los amigos!" },
      { t = "eos" },
    },
  ["g3:08173ce3"] = {
      { t = "text", s = "¡Durante todos mis viajes jamás" },
      { t = "nl" },
      { t = "text", s = "había visto a un POKéMON que" },
      { t = "scroll" },
      { t = "text", s = "durmiera tanto!" },
      { t = "para" },
      { t = "text", s = "¡Era algo así!..." },
      { t = "eos" },
    },
  ["g3:08173d63"] = {
      { t = "text", s = "¡Competir contra los jóvenes" },
      { t = "nl" },
      { t = "text", s = "me mantiene como un chaval!" },
      { t = "eos" },
    },
  ["g3:08173d92"] = {
      { t = "text", s = "¡Buena pelea!" },
      { t = "nl" },
      { t = "text", s = "¡Vuelvo a sentirme joven!" },
      { t = "eos" },
    },
  ["g3:08173db6"] = {
      { t = "text", s = "¡Hace 15 años, yo habría ganado!" },
      { t = "eos" },
    },
  ["g3:08173ddb"] = {
      { t = "text", s = "¡Mira lo que he pescado!" },
      { t = "eos" },
    },
  ["g3:08173df7"] = {
      { t = "text", s = "¡Estoy acabado!" },
      { t = "eos" },
    },
  ["g3:08173e04"] = {
      { t = "text", s = "¿Una fiesta?" },
      { t = "para" },
      { t = "text", s = "La fiesta del crucero debe de" },
      { t = "nl" },
      { t = "text", s = "haber terminado." },
      { t = "eos" },
    },
  ["g3:08173e3a"] = {
      { t = "text", s = "¡Ah, sí! ¡Vi a unos POKéMON" },
      { t = "nl" },
      { t = "text", s = "transportando a gente por el agua!" },
      { t = "eos" },
    },
  ["g3:08173e7b"] = {
      { t = "text", s = "Los POKéMON pueden CORTAR" },
      { t = "nl" },
      { t = "text", s = "pequeños arbustos." },
      { t = "para" },
      { t = "text", s = "Pero ten en cuenta que CORTE" },
      { t = "nl" },
      { t = "text", s = "es una técnica de MO." },
      { t = "para" },
      { t = "text", s = "Una vez aprendida, cuesta mucho" },
      { t = "nl" },
      { t = "text", s = "olvidarla." },
      { t = "eos" },
    },
  ["g3:08173f07"] = {
      { t = "text", s = "¿Qué prefieres, un POKéMON fuerte" },
      { t = "nl" },
      { t = "text", s = "o uno raro?" },
      { t = "eos" },
    },
  ["g3:08173f42"] = {
      { t = "text", s = "¡Debo felicitarte!" },
      { t = "eos" },
    },
  ["g3:08173f55"] = {
      { t = "text", s = "¡Prefiero los POKéMON fuertes" },
      { t = "nl" },
      { t = "text", s = "y raros!" },
      { t = "eos" },
    },
  ["g3:08173f83"] = {
      { t = "text", s = "No te he visto en la fiesta." },
      { t = "eos" },
    },
  ["g3:08173fab"] = {
      { t = "text", s = "¡Oye!" },
      { t = "nl" },
      { t = "text", s = "¡¡¡No había que ponerse así!!!" },
      { t = "eos" },
    },
  ["g3:08173fb9"] = {
      { t = "text", s = "¡Oh!" },
      { t = "nl" },
      { t = "text", s = "¡Adoro a tus fuertes POKéMON!" },
      { t = "eos" },
    },
  ["g3:08173ff7"] = {
      { t = "text", s = "¿Has ido a la ZONA del SAFARI" },
      { t = "nl" },
      { t = "text", s = "en CIUDAD FUCSIA?" },
      { t = "para" },
      { t = "text", s = "¡Había muchos tipos raros" },
      { t = "nl" },
      { t = "text", s = "de POKéMON!" },
      { t = "eos" },
    },
  ["g3:0817404f"] = {
      { t = "text", s = "¡Mi padre y yo pensamos que" },
      { t = "nl" },
      { t = "text", s = "la ZONA del SAFARI es genial!" },
      { t = "eos" },
    },
  ["g3:081740a1"] = {
      { t = "text", s = "¡El CAPITÁN parecía muy mareado" },
      { t = "nl" },
      { t = "text", s = "y pálido!" },
      { t = "eos" },
    },
  ["g3:081740d6"] = {
      { t = "text", s = "¡Dicen que hay mucha gente que" },
