      { t = "text", s = "se marea!" },
      { t = "eos" },
    },
  ["g3:081740f6"] = {
      { t = "text", s = "¡Como pierdas, caminarás" },
      { t = "nl" },
      { t = "text", s = "por el tablón!" },
      { t = "eos" },
    },
  ["g3:08174123"] = {
      { t = "text", s = "¡Argh! ¡Derrotado por alguien" },
      { t = "nl" },
      { t = "text", s = "más joven que yo!" },
      { t = "eos" },
    },
  ["g3:0817413a"] = {
      { t = "text", s = "A veces, algunas medusas caen" },
      { t = "nl" },
      { t = "text", s = "dentro del barco." },
      { t = "eos" },
    },
  ["g3:08174177"] = {
      { t = "text", s = "¡Eh, tú!" },
      { t = "para" },
      { t = "text", s = "¡No sé si eres de tierra o mar, " },
      { t = "nl" },
      { t = "text", s = "pero para y habla conmigo!" },
      { t = "para" },
      { t = "text", s = "¡Todos mis POKéMON vienen del mar!" },
      { t = "eos" },
    },
  ["g3:081741ef"] = {
      { t = "text", s = "¡Vaya!" },
      { t = "nl" },
      { t = "text", s = "¡He dejado que te escaparas!" },
      { t = "eos" },
    },
  ["g3:0817420e"] = {
      { t = "text", s = "¡Yo también te iba a hacer" },
      { t = "nl" },
      { t = "text", s = "mi ayudante!" },
      { t = "eos" },
    },
  ["g3:08174239"] = {
      { t = "text", s = "¡Los marineros también tenemos" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:0817425c"] = {
      { t = "text", s = "¡Eres bastante fuerte!" },
      { t = "eos" },
    },
  ["g3:08174272"] = {
      { t = "text", s = "¡Pescamos a todos nuestros POKéMON" },
      { t = "nl" },
      { t = "text", s = "en alta mar!" },
      { t = "eos" },
    },
  ["g3:081742a6"] = {
      { t = "text", s = "¡Me gusta la gente activa como tú!" },
      { t = "eos" },
    },
  ["g3:081742c3"] = {
      { t = "text", s = "¡Argh!" },
      { t = "nl" },
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:081742d2"] = {
      { t = "text", s = "Los POKéMON del mar viven en las" },
      { t = "nl" },
      { t = "text", s = "profundidades." },
      { t = "scroll" },
      { t = "text", s = "¡Necesitarás una CAÑA!" },
      { t = "eos" },
    },
  ["g3:08174315"] = {
      { t = "text", s = "¡Ya sabes lo que dicen sobre" },
      { t = "nl" },
      { t = "text", s = "los marineros y las peleas!" },
      { t = "eos" },
    },
  ["g3:08174348"] = {
      { t = "text", s = "¡Has peleado muy bien, sí, sí!" },
      { t = "eos" },
    },
  ["g3:08174362"] = {
      { t = "text", s = "¡Ajá!" },
      { t = "nl" },
      { t = "text", s = "¿Quieres unirte a los marineros?" },
      { t = "eos" },
    },
  ["g3:08174385"] = {
      { t = "text", s = "¡Está en juego mi fama de" },
