      { t = "text", s = "marinero!" },
      { t = "eos" },
    },
  ["g3:081743b3"] = {
      { t = "text", s = "¡Menuda paliza!" },
      { t = "eos" },
    },
  ["g3:081743c8"] = {
      { t = "text", s = "¿Viste al GURÚ de los PESCADORES" },
      { t = "nl" },
      { t = "text", s = "en CIUDAD CARMÍN?" },
      { t = "eos" },
    },
  ["g3:081743f8"] = {
      { t = "text", s = "¡Mi amigo, MACHOKE," },
      { t = "nl" },
      { t = "text", s = "es superfuerte!" },
      { t = "para" },
      { t = "text", s = "¡Tiene tanta FUERZA que puede" },
      { t = "nl" },
      { t = "text", s = "mover hasta grandes rocas!" },
      { t = "eos" },
    },
  ["g3:08174444"] = {
      { t = "text", s = "MACHOKE: ¡Cho! ¡Chokecho!" },
      { t = "eos" },
    },
  ["g3:0817445b"] = {
      { t = "text", s = "¡Tienes una cara de agotamiento!" },
      { t = "nl" },
      { t = "text", s = "¿Quieres descansar un ratito?" },
      { t = "eos" },
    },
  ["g3:08174490"] = {
      { t = "text", s = "¡Eso ya es otra cosa! ¡Me encanta" },
      { t = "nl" },
      { t = "text", s = "ver a todo el mundo descansado!" },
      { t = "eos" },
    },
  ["g3:081744d0"] = {
      { t = "text", s = "Bueno, yo lo decía por tu bien." },
      { t = "nl" },
      { t = "text", s = "Es que me recuerdas a mi hermano" },
      { t = "scroll" },
      { t = "text", s = "pequeño..." },
      { t = "eos" },
    },
  ["g3:08174515"] = {
      { t = "text", s = "Bueno, yo lo decía por tu bien." },
      { t = "nl" },
      { t = "text", s = "Es que me recuerdas a mi hermana" },
      { t = "scroll" },
      { t = "text", s = "pequeña..." },
      { t = "eos" },
    },
  ["g3:08174559"] = {
      { t = "text", s = "La gente suele perder cosas" },
      { t = "nl" },
      { t = "text", s = "en esta VÍA SUBTERRÁNEA." },
      { t = "eos" },
    },
  ["g3:0817459b"] = {
      { t = "text", s = "Dicen que hay un POKéMON durmiendo" },
      { t = "nl" },
      { t = "text", s = "cerca de CIUDAD AZULONA." },
      { t = "eos" },
    },
  ["g3:081745d9"] = {
      { t = "text", s = "¡El CENTRO COMERCIAL de AZULONA" },
      { t = "nl" },
      { t = "text", s = "tiene muchas cosas!" },
      { t = "eos" },
    },
  ["g3:0817462c"] = {
      { t = "text", s = "Fui al TÚNEL ROCA, pero" },
      { t = "nl" },
      { t = "text", s = "está oscuro y me da miedo." },
      { t = "para" },
      { t = "text", s = "¡Si el DESTELLO de un POKéMON" },
      { t = "nl" },
      { t = "text", s = "pudiera alumbrarlo...!" },
      { t = "eos" },
    },
  ["g3:081746a7"] = {
      { t = "text", s = "¡Vaya sorpresa! ¡Los DIGLETT" },
      { t = "nl" },
      { t = "text", s = "cavaron este largo túnel!" },
      { t = "para" },
      { t = "text", s = "¡Va a CIUDAD VERDE!" },
      { t = "eos" },
    },
  ["g3:08174710"] = {
      { t = "text", s = "¡Me pregunto si eres lo bastante" },
      { t = "nl" },
      { t = "text", s = "fuerte para mí!" },
      { t = "eos" },
    },
  ["g3:08174738"] = {
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:08174744"] = {
      { t = "text", s = "¡A mí no me gusta perder, y mucho" },
      { t = "nl" },
      { t = "text", s = "menos contra alguien tan joven!" },
      { t = "eos" },
    },
  ["g3:08174784"] = {
      { t = "text", s = "¡Ya veo que eres fuerte!" },
      { t = "nl" },
      { t = "text", s = "¡Veamos exactamente cuánto!" },
      { t = "eos" },
    },
  ["g3:081747b8"] = {
      { t = "text", s = "He perdido la oportunidad..." },
      { t = "eos" },
    },
  ["g3:081747c8"] = {
      { t = "text", s = "¡Lo admito, eres mejor que yo!" },
      { t = "eos" },
    },
  ["g3:081747ef"] = {
      { t = "text", s = "¡Si puedes pasar por aquí, podrás" },
      { t = "nl" },
      { t = "text", s = "enfrentarte al ALTO MANDO!" },
      { t = "eos" },
    },
  ["g3:0817482c"] = {
      { t = "text", s = "¡No!" },
      { t = "nl" },
      { t = "text", s = "¡Increíble!" },
      { t = "eos" },
    },
  ["g3:0817483e"] = {
      { t = "text", s = "¡Puedo vencerte en cuanto a" },
      { t = "nl" },
      { t = "text", s = "conocimientos sobre los POKéMON!" },
      { t = "eos" },
    },
  ["g3:08174877"] = {
      { t = "text", s = "¡La CALLE VICTORIA es la prueba" },
      { t = "nl" },
      { t = "text", s = "final de todo ENTRENADOR!" },
      { t = "eos" },
    },
  ["g3:081748b4"] = {
      { t = "text", s = "¡Ayyyy!" },
      { t = "eos" },
    },
  ["g3:081748bb"] = {
      { t = "text", s = "¡Prueba a mover las rocas" },
      { t = "nl" },
      { t = "text", s = "si tienes el paso cortado!" },
      { t = "eos" },
    },
  ["g3:081748ee"] = {
      { t = "text", s = "¡Ah!" },
      { t = "nl" },
      { t = "text", s = "¿Quieres desafiar al ALTO MANDO?" },
      { t = "eos" },
    },
  ["g3:0817491b"] = {
      { t = "text", s = "¡Me has ganado!" },
      { t = "eos" },
    },
  ["g3:08174927"] = {
      { t = "text", s = "¡" },
      { t = "rival" },
      { t = "text", s = " también vino por aquí!" },
      { t = "eos" },
    },
  ["g3:08174942"] = {
      { t = "text", s = "¡Adelante!" },
      { t = "nl" },
      { t = "text", s = "¡Te daré una paliza!" },
      { t = "eos" },
    },
  ["g3:0817495a"] = {
      { t = "text", s = "¡Me has machacado!" },
      { t = "eos" },
    },
  ["g3:08174969"] = {
      { t = "text", s = "¡Ahora puedes recorrer la CALLE" },
      { t = "nl" },
      { t = "text", s = "VICTORIA!" },
      { t = "eos" },
    },
  ["g3:08174995"] = {
      { t = "text", s = "¿Es muy dura la CALLE VICTORIA?" },
      { t = "eos" },
    },
  ["g3:081749b0"] = {
      { t = "text", s = "¡Bien hecho!" },
      { t = "eos" },
    },
  ["g3:081749bb"] = {
      { t = "text", s = "¡Muchos de los ENTRENADORES" },
      { t = "nl" },
      { t = "text", s = "se rinden aquí!" },
      { t = "eos" },
    },
  ["g3:081749f9"] = {
      { t = "text", s = "Has conseguido abrirte paso por" },
      { t = "nl" },
      { t = "text", s = "la CALLE VICTORIA con mucho" },
      { t = "scroll" },
      { t = "text", s = "valor; es para alegrarse." },
      { t = "para" },
      { t = "text", s = "Como reconocimiento a tu hazaña," },
      { t = "nl" },
      { t = "text", s = "te enseñaré DOBLE FILO." },
      { t = "para" },
      { t = "text", s = "¿Quieres?" },
      { t = "eos" },
    },
  ["g3:08174abc"] = {
      { t = "text", s = "Bueno, otra vez será." },
      { t = "eos" },
    },
  ["g3:08174ae2"] = {
      { t = "text", s = "¿A qué POKéMON quieres que" },
      { t = "nl" },
      { t = "text", s = "le enseñe DOBLE FILO?" },
      { t = "eos" },
    },
  ["g3:08174b0c"] = {
      { t = "text", s = "¡No bajes la guardia para la LIGA" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "para" },
      { t = "text", s = "¡A por ella, acaba con todos!" },
      { t = "eos" },
    },
  ["g3:08174b60"] = {
      { t = "text", s = "¡Los rumores hablan de un" },
      { t = "nl" },
      { t = "text", s = "ENTRENADOR espectacular!" },
      { t = "eos" },
    },
  ["g3:08174b83"] = {
      { t = "text", s = "¡Los rumores eran ciertos!" },
      { t = "eos" },
    },
  ["g3:08174b99"] = {
      { t = "text", s = "¿Derrotaste a GIOVANNI" },
      { t = "nl" },
      { t = "text", s = "del TEAM ROCKET?" },
      { t = "eos" },
    },
  ["g3:08174bca"] = {
      { t = "text", s = "¡Los ENTRENADORES sólo viven para" },
      { t = "nl" },
      { t = "text", s = "buscar enemigos más fuertes!" },
      { t = "eos" },
    },
  ["g3:08174bf4"] = {
      { t = "text", s = "¡Oooooh!" },
      { t = "nl" },
      { t = "text", s = "¡Eres tan fuerte!" },
      { t = "eos" },
    },
  ["g3:08174c03"] = {
      { t = "text", s = "¡Librar duros combates te hará" },
      { t = "nl" },
      { t = "text", s = "más fuerte!" },
      { t = "eos" },
    },
  ["g3:08174c30"] = {
      { t = "text", s = "¡Te demostraré lo fuerte que eres" },
      { t = "nl" },
      { t = "text", s = "de verdad!" },
      { t = "eos" },
    },
  ["g3:08174c5a"] = {
      { t = "text", s = "¡Argh! ¡Eres increíble!" },
      { t = "eos" },
    },
  ["g3:08174c67"] = {
      { t = "text", s = "¡Yo soy la que ha aprendido" },
      { t = "nl" },
      { t = "text", s = "la lección!" },
      { t = "eos" },
    },
  ["g3:08174c8a"] = {
      { t = "text", s = "¡Aquí sólo pueden pasar" },
      { t = "nl" },
      { t = "text", s = "los elegidos!" },
      { t = "eos" },
    },
  ["g3:08174ca9"] = {
      { t = "text", s = "¡No me lo puedo creer!" },
      { t = "eos" },
    },
  ["g3:08174cbd"] = {
      { t = "text", s = "¡Todos estos ENTRENADORES van a" },
      { t = "nl" },
      { t = "text", s = "participar en la LIGA POKéMON!" },
      { t = "para" },
      { t = "text", s = "¡Ten cuidado!" },
      { t = "eos" },
    },
  ["g3:08174d0c"] = {
      { t = "text", s = "DESI: ¡Juntos lucharemos contra" },
      { t = "nl" },
      { t = "text", s = "quien sea!" },
      { t = "eos" },
    },
  ["g3:08174d45"] = {
      { t = "text", s = "DESI: ¡No me lo puedo creer!" },
      { t = "eos" },
    },
  ["g3:08174d64"] = {
      { t = "text", s = "DESI: ¡Has acabado con nosotros!" },
      { t = "eos" },
    },
  ["g3:08174d96"] = {
      { t = "text", s = "DESI: Acabaríamos contigo" },
      { t = "nl" },
      { t = "text", s = "en un abrir y cerrar de ojos." },
      { t = "para" },
      { t = "text", s = "Para luchar con nosotros, hay" },
      { t = "nl" },
      { t = "text", s = "que tener dos POKéMON." },
      { t = "eos" },
    },
  ["g3:08174e08"] = {
      { t = "text", s = "TULA: ¡Tenemos intención de" },
      { t = "nl" },
      { t = "text", s = "convertirnos en campeones!" },
      { t = "eos" },
    },
  ["g3:08174e39"] = {
      { t = "text", s = "TULA: Eh..., en fin..." },
      { t = "eos" },
    },
  ["g3:08174e48"] = {
      { t = "text", s = "TULA: De ti he aprendido la" },
      { t = "nl" },
      { t = "text", s = "verdadera dimensión de la fuerza." },
      { t = "eos" },
    },
  ["g3:08174e8d"] = {
      { t = "text", s = "TULA: No podrás con nosotros" },
      { t = "nl" },
      { t = "text", s = "si no tienes dos POKéMON." },
      { t = "eos" },
    },
  ["g3:08174eca"] = {
      { t = "text", s = "¿Quién eres tú?" },
      { t = "nl" },
      { t = "text", s = "¿Y cómo has llegado aquí?" },
      { t = "eos" },
    },
  ["g3:08174eed"] = {
      { t = "text", s = "¡Auuu!" },
      { t = "nl" },
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:08174efa"] = {
      { t = "text", s = "¿Vas a luchar contra el TEAM" },
      { t = "nl" },
      { t = "text", s = "ROCKET?" },
      { t = "eos" },
    },
  ["g3:08174f2c"] = {
      { t = "text", s = "¡Has destrozado nuestros planes!" },
      { t = "eos" },
    },
  ["g3:08174f60"] = {
      { t = "text", s = "¡Chamuscado!" },
      { t = "eos" },
    },
  ["g3:08174f66"] = {
      { t = "text", s = "¡No te vas a salir con la tuya," },
      { t = "nl" },
      { t = "text", s = "impresentable!" },
      { t = "eos" },
    },
  ["g3:08174f94"] = {
      { t = "text", s = "¡Alerta! ¡Nos invaden!" },
      { t = "eos" },
    },
  ["g3:08174fa4"] = {
      { t = "text", s = "¡¡¡No lo he conseguido!!!" },
      { t = "eos" },
    },
  ["g3:08174fb3"] = {
      { t = "text", s = "¿El SCOPE SILPH?" },
      { t = "nl" },
      { t = "text", s = "¡No sé dónde está!" },
      { t = "eos" },
    },
  ["g3:08174fe1"] = {
      { t = "text", s = "¿Por qué has venido aquí?" },
      { t = "eos" },
    },
  ["g3:08174ff8"] = {
      { t = "text", s = "¡Esto no funcionará!" },
      { t = "eos" },
    },
  ["g3:08175007"] = {
      { t = "text", s = "¡Vale, hablaré! ¡Toma el ascensor" },
      { t = "nl" },
      { t = "text", s = "para ver a mi JEFE!" },
      { t = "eos" },
    },
  ["g3:0817503a"] = {
      { t = "text", s = "¿Te has perdido? Pobre..." },
      { t = "eos" },
    },
  ["g3:0817505a"] = {
      { t = "text", s = "¿Por qué...?" },
      { t = "eos" },
    },
  ["g3:08175060"] = {
      { t = "text", s = "¡Con tanto lío se ha abierto" },
      { t = "nl" },
      { t = "text", s = "la puerta!" },
      { t = "eos" },
    },
  ["g3:0817508c"] = {
      { t = "text", s = "¡El JEFE dijo que se pueden ver" },
      { t = "nl" },
      { t = "text", s = "fantasmas con el SCOPE SILPH!" },
      { t = "eos" },
    },
  ["g3:081750bf"] = {
      { t = "text", s = "¡Me rindo!" },
      { t = "eos" },
    },
  ["g3:081750cc"] = {
      { t = "text", s = "El CG del TEAM ROCKET tiene" },
      { t = "nl" },
      { t = "text", s = "4 sótanos." },
      { t = "para" },
      { t = "text", s = "¿Podrás llegar al JEFE?" },
      { t = "eos" },
    },
  ["g3:0817511a"] = {
      { t = "text", s = "¡Deja de meterte en los asuntos" },
      { t = "nl" },
      { t = "text", s = "del TEAM ROCKET!" },
      { t = "eos" },
    },
  ["g3:0817514a"] = {
      { t = "text", s = "¡Uff!" },
      { t = "nl" },
      { t = "text", s = "¡Me ha machacado!" },
      { t = "eos" },
    },
  ["g3:0817515b"] = {
      { t = "text", s = "¿El SCOPE SILPH?" },
      { t = "nl" },
      { t = "text", s = "Ah, la máquina que robó el JEFE." },
      { t = "para" },
      { t = "text", s = "Debe de estar por aquí." },
      { t = "eos" },
    },
  ["g3:0817519e"] = {
      { t = "text", s = "¡Nos dijeron desde arriba que" },
      { t = "nl" },
      { t = "text", s = "venías!" },
      { t = "eos" },
    },
  ["g3:081751ce"] = {
      { t = "text", s = "¿Qué?" },
      { t = "nl" },
      { t = "text", s = "¿He perdido? ¡NO!" },
      { t = "eos" },
    },
  ["g3:081751e0"] = {
      { t = "text", s = "¡Venga, adelante!" },
      { t = "para" },
      { t = "text", s = "¡Pero necesitarás la LLAVE" },
      { t = "nl" },
      { t = "text", s = "del ASCENSOR!" },
      { t = "eos" },
    },
  ["g3:08175226"] = {
      { t = "text", s = "¡Mmm! ¡Estoy muy impresionado" },
      { t = "nl" },
      { t = "text", s = "de que hayas llegado hasta aquí!" },
      { t = "para" },
      { t = "text", s = "¡El TEAM ROCKET necesita los" },
      { t = "nl" },
      { t = "text", s = "POKéMON para financiar sus" },
      { t = "scroll" },
      { t = "text", s = "malvados planes!" },
      { t = "para" },
      { t = "text", s = "¡Yo soy GIOVANNI, su líder!" },
      { t = "para" },
      { t = "text", s = "¡Y te las vas a tener que ver" },
      { t = "nl" },
      { t = "text", s = "conmigo, metomentodo!" },
      { t = "eos" },
    },
  ["g3:08175318"] = {
      { t = "text", s = "¿QUÉ?" },
      { t = "nl" },
      { t = "text", s = "¡Esto es imposible!" },
      { t = "eos" },
    },
  ["g3:0817532d"] = {
      { t = "text", s = "Ya veo que has entrenado a tus" },
      { t = "nl" },
      { t = "text", s = "POKéMON con mucho cuidado." },
      { t = "para" },
      { t = "text", s = "¡Pero jamás entenderías" },
      { t = "nl" },
      { t = "text", s = "cuáles son mis planes!" },
      { t = "para" },
      { t = "text", s = "¡En esta ocasión te dejaré pasar!" },
      { t = "para" },
      { t = "text", s = "Espero que nos volvamos a ver." },
      { t = "eos" },
    },
  ["g3:081753d0"] = {
      { t = "text", s = "¡Te conozco! ¡Tú arruinaste" },
      { t = "nl" },
      { t = "text", s = "nuestros planes en MT. MOON!" },
      { t = "eos" },
    },
  ["g3:081753fe"] = {
      { t = "text", s = "¡Me han vuelto a machacar!" },
      { t = "eos" },
    },
  ["g3:0817540c"] = {
      { t = "text", s = "¿Tienes algo en contra del TEAM" },
      { t = "nl" },
      { t = "text", s = "ROCKET?" },
      { t = "eos" },
    },
  ["g3:08175437"] = {
      { t = "text", s = "¿Acaso no ves la belleza de" },
      { t = "nl" },
      { t = "text", s = "nuestros actos malvados?" },
      { t = "eos" },
    },
  ["g3:08175463"] = {
      { t = "text", s = "¡Ayayay!" },
      { t = "eos" },
    },
  ["g3:0817546a"] = {
      { t = "text", s = "¡JEFE!" },
      { t = "nl" },
      { t = "text", s = "¡Siento haberle fallado!" },
      { t = "eos" },
    },
  ["g3:08175488"] = {
      { t = "text", s = "¿No funciona el ascensor? ¿Quién" },
      { t = "nl" },
      { t = "text", s = "tiene la LLAVE del ASCENSOR?" },
      { t = "eos" },
    },
  ["g3:081754b9"] = {
      { t = "text", s = "¡No!" },
      { t = "eos" },
    },
  ["g3:081754bd"] = {
      { t = "text", s = "¡Oh, no! ¡He perdido la LLAVE" },
      { t = "nl" },
      { t = "text", s = "del ASCENSOR!" },
      { t = "eos" },
    },
  ["g3:081754dd"] = {
      { t = "text", s = "Parece que hace falta una llave." },
      { t = "eos" },
    },
  ["g3:081754f7"] = {
      { t = "text", s = "¡Hola!" },
      { t = "para" },
      { t = "text", s = "¡El PRESIDENTE está en la sala" },
      { t = "nl" },
      { t = "text", s = "de reuniones del P10!" },
      { t = "eos" },
    },
  ["g3:08175549"] = {
      { t = "text", s = "OFICINA CENTRAL DE SILPH S.A." },
      { t = "nl" },
      { t = "text", s = "PB" },
      { t = "eos" },
    },
  ["g3:08175562"] = {
      { t = "text", s = "¡Socorro!" },
      { t = "nl" },
      { t = "text", s = "¡Soy un empleado de SILPH S.A.!" },
      { t = "eos" },
    },
  ["g3:0817557e"] = {
      { t = "text", s = "¿Cómo sabías que yo era un" },
      { t = "nl" },
      { t = "text", s = "ROCKET?" },
      { t = "eos" },
    },
  ["g3:0817559f"] = {
      { t = "text", s = "¡Trabajo para SILPH S.A. y para" },
      { t = "nl" },
      { t = "text", s = "el TEAM ROCKET!" },
      { t = "eos" },
    },
  ["g3:081755c6"] = {
      { t = "text", s = "¡Estás en zona prohibida!" },
      { t = "nl" },
      { t = "text", s = "¡Vuelve a casa!" },
      { t = "eos" },
    },
  ["g3:081755e5"] = {
      { t = "text", s = "¡Eres genial!" },
      { t = "eos" },
    },
  ["g3:081755f2"] = {
      { t = "text", s = "¿Puedes resolver este laberinto?" },
      { t = "eos" },
    },
  ["g3:0817562d"] = {
      { t = "text", s = "¡Aquí no pueden entrar los niños!" },
      { t = "eos" },
    },
  ["g3:0817564a"] = {
      { t = "text", s = "¡Muy fuerte!" },
      { t = "eos" },
    },
  ["g3:08175651"] = {
      { t = "text", s = "¡Las baldosas con forma" },
      { t = "nl" },
      { t = "text", s = "de diamante son puntos" },
      { t = "scroll" },
      { t = "text", s = "de teletransporte!" },
      { t = "para" },
      { t = "text", s = "¡Son medios de transporte" },
      { t = "nl" },
      { t = "text", s = "de alta tecnología!" },
      { t = "eos" },
    },
  ["g3:081756ad"] = {
      { t = "text", s = "¡Oye, tú!" },
      { t = "nl" },
      { t = "text", s = "¿Qué haces aquí?" },
      { t = "eos" },
    },
  ["g3:081756d8"] = {
      { t = "text", s = "¡He metido la pata!" },
      { t = "eos" },
    },
  ["g3:081756e2"] = {
      { t = "text", s = "¡SILPH S.A. va a fusionarse" },
      { t = "nl" },
      { t = "text", s = "con el TEAM ROCKET!" },
      { t = "eos" },
    },
  ["g3:08175711"] = {
      { t = "text", s = "¡Socorro!" },
      { t = "nl" },
      { t = "text", s = "¡No! ¡Alto!" },
      { t = "para" },
      { t = "text", s = "¿No perteneces al TEAM ROCKET?" },
      { t = "nl" },
      { t = "text", s = "Yo pensaba..." },
      { t = "para" },
      { t = "text", s = "Lo siento..." },
      { t = "nl" },
      { t = "text", s = "Eh... ¿te enseño ONDA TRUENO?" },
      { t = "eos" },
    },
  ["g3:0817579d"] = {
      { t = "text", s = "Eh..." },
      { t = "nl" },
      { t = "text", s = "ONDA TRUENO es muy útil..." },
      { t = "eos" },
    },
  ["g3:081757c1"] = {
      { t = "text", s = "¿A qué POKéMON quieres que" },
      { t = "nl" },
      { t = "text", s = "le enseñe ONDA TRUENO?" },
      { t = "eos" },
    },
  ["g3:081757ec"] = {
