      { t = "eos" },
    },
  ["g3:081794ac"] = {
      { t = "text", s = "¡Me rindo!" },
      { t = "eos" },
    },
  ["g3:081794b4"] = {
      { t = "text", s = "¡Tienes madera para escalar!" },
      { t = "eos" },
    },
  ["g3:081794d4"] = {
