    },
  ["g3:08179577"] = {
      { t = "text", s = "¡Vine hasta aquí por los POKéMON!" },
      { t = "eos" },
    },
  ["g3:081795a1"] = {
      { t = "text", s = "¡Me he quedado sin POKéMON!" },
