      { t = "para" },
      { t = "text", s = "Es la mejor forma de no perderse." },
      { t = "eos" },
    },
  ["g3:081796b9"] = {
      { t = "text", s = "¡Ohhh!" },
      { t = "nl" },
      { t = "text", s = "¡He hecho todo lo posible!" },
