    },
  ["g3:0817a380"] = {
      { t = "text", s = "¿Qué quieres?" },
      { t = "nl" },
      { t = "text", s = "¿Qué haces aquí?" },
      { t = "eos" },
    },
  ["g3:0817a3a4"] = {
      { t = "text", s = "¡Me rindo!" },
      { t = "eos" },
    },
  ["g3:0817a3af"] = {
      { t = "text", s = "¡Voy a olvidar todo esto!" },
      { t = "eos" },
    },
  ["g3:0817a3cd"] = {
      { t = "text", s = "El tipo, que ya tiene unos años," },
      { t = "nl" },
      { t = "text", s = "se plantó en nuestra GUARIDA." },
      { t = "para" },
      { t = "text", s = "Y empezó a decir que estábamos" },
      { t = "nl" },
      { t = "text", s = "haciendo daño a los POKéMON." },
      { t = "para" },
      { t = "text", s = "¡La cosa es más que seria!" },
      { t = "eos" },
    },
  ["g3:0817a466"] = {
      { t = "text", s = "¡Por favor!" },
      { t = "nl" },
      { t = "text", s = "¡Basta!" },
      { t = "eos" },
    },
  ["g3:0817a477"] = {
      { t = "text", s = "¡Los POKéMON sólo sirven para" },
      { t = "nl" },
      { t = "text", s = "ganar dinero!" },
      { t = "para" },
      { t = "text", s = "¡No te metas en nuestros asuntos!" },
      { t = "eos" },
    },
  ["g3:0817a4cf"] = {
      { t = "text", s = "¡No vas a salvar a nadie!" },
      { t = "eos" },
    },
  ["g3:0817a4ee"] = {
      { t = "text", s = "¡No luches contra nosotros," },
      { t = "nl" },
      { t = "text", s = "el TEAM ROCKET!" },
      { t = "eos" },
    },
  ["g3:0817a506"] = {
      { t = "text", s = "¡No te saldrás con la tuya así" },
      { t = "nl" },
      { t = "text", s = "como así!" },
      { t = "eos" },
    },
  ["g3:0817a529"] = {
      { t = "text", s = "SR. FUJI: ¿Qué?" },
      { t = "nl" },
      { t = "text", s = "¿Has venido a salvarme?" },
      { t = "para" },
      { t = "text", s = "¡Gracias! Pero estoy aquí por mi" },
      { t = "nl" },
      { t = "text", s = "propia voluntad." },
      { t = "para" },
      { t = "text", s = "Vine a calmar el espíritu de la" },
      { t = "nl" },
      { t = "text", s = "madre de CUBONE." },
      { t = "para" },
      { t = "text", s = "Creo que el espíritu de MAROWAK" },
      { t = "nl" },
      { t = "text", s = "ya está tranquilo." },
      { t = "para" },
      { t = "text", s = "¡Agradezco tu interés!" },
      { t = "para" },
      { t = "text", s = "Acompáñame a mi casa, a la CASA" },
      { t = "nl" },
      { t = "text", s = "POKéMON, que hay al pie de esta" },
      { t = "scroll" },
      { t = "text", s = "torre." },
      { t = "eos" },
    },
  ["g3:0817a642"] = {
      { t = "text", s = "¿Te imaginas que este volcán" },
      { t = "nl" },
      { t = "text", s = "entrara en erupción?" },
      { t = "para" },
      { t = "text", s = "Sería nuestro fin. ¡Qué horror!" },
      { t = "para" },
      { t = "text", s = "A todo esto, ¿quieres aprender" },
      { t = "nl" },
      { t = "text", s = "EXPLOSIÓN?" },
      { t = "eos" },
    },
  ["g3:0817a6ed"] = {
      { t = "text", s = "Te entiendo, sólo oír el nombre" },
      { t = "nl" },
      { t = "text", s = "pone los pelos de punta." },
      { t = "eos" },
    },
  ["g3:0817a717"] = {
      { t = "text", s = "¡Sí, señor!" },
      { t = "para" },
      { t = "text", s = "¿A qué POKéMON quieres que" },
      { t = "nl" },
      { t = "text", s = "le enseñe EXPLOSIÓN?" },
      { t = "eos" },
    },
  ["g3:0817a756"] = {
      { t = "text", s = "Imagínate lo que tiene que ser" },
      { t = "nl" },
      { t = "text", s = "usar EXPLOSIÓN en este volcán..." },
      { t = "para" },
      { t = "text", s = "¡Lo pienso y no sé lo que me" },
      { t = "nl" },
      { t = "text", s = "entra!" },
      { t = "eos" },
    },
  ["g3:0817a82a"] = {
      { t = "text", s = "Aquí, aquí." },
      { t = "nl" },
      { t = "text", s = "Vamos a intentar cavar aquí." },
      { t = "para" },
      { t = "text", s = "Yo creo que el tesoro del que" },
      { t = "nl" },
      { t = "text", s = "hablaban los ADMINISTRADORES" },
      { t = "scroll" },
      { t = "text", s = "está aquí." },
      { t = "eos" },
    },
  ["g3:0817a88c"] = {
      { t = "text", s = "Pero..." },
      { t = "nl" },
      { t = "text", s = "¿Te quieres quitar de aquí?" },
      { t = "eos" },
    },
  ["g3:0817a8b4"] = {
      { t = "text", s = "¡Por fin lo hemos conseguido!" },
      { t = "nl" },
      { t = "text", s = "¡A por el tesoro!" },
      { t = "eos" },
    },
  ["g3:0817a8ee"] = {
      { t = "text", s = "Cosa que encontremos, cosa que" },
      { t = "nl" },
      { t = "text", s = "llevamos al ALMACÉN, ¿eh?" },
      { t = "para" },
      { t = "text", s = "Eh... ¿y cuáles eran las" },
      { t = "nl" },
      { t = "text", s = "contraseñas?" },
      { t = "scroll" },
      { t = "text", s = "Me refiero a las del ALMACÉN..." },
      { t = "eos" },
    },
  ["g3:0817a970"] = {
      { t = "text", s = "¿No te acuerdas de la contraseña?" },
      { t = "nl" },
      { t = "text", s = "Bueno, en realidad son dos." },
      { t = "para" },
      { t = "text", s = "La primera es “ARON ama" },
      { t = "nl" },
      { t = "text", s = "a NORA”." },
      { t = "para" },
      { t = "text", s = "Y la segunda..." },
      { t = "eos" },
    },
  ["g3:0817a9e1"] = {
      { t = "text", s = "¡Eh, que por aquí se están" },
      { t = "nl" },
      { t = "text", s = "quedando con la copla! ¡Cotilla!" },
      { t = "eos" },
    },
  ["g3:0817aa06"] = {
      { t = "text", s = "Has estado espiándonos, ¿eh?" },
      { t = "eos" },
    },
  ["g3:0817aa34"] = {
      { t = "text", s = "¿Qué ha pasado?" },
      { t = "eos" },
    },
  ["g3:0817aa3f"] = {
      { t = "text", s = "¿Por qué me has ganado?" },
      { t = "eos" },
    },
  ["g3:0817aa56"] = {
      { t = "text", s = "¿Te crees que vas a pillar cacho" },
      { t = "nl" },
      { t = "text", s = "de nuestro tesoro? ¡Ni lo sueñes!" },
      { t = "eos" },
    },
  ["g3:0817aa8a"] = {
      { t = "text", s = "¡Ahora quien está soñando soy yo!" },
      { t = "eos" },
    },
  ["g3:0817aa99"] = {
      { t = "text", s = "Hazme un favorcito, olvídate de lo" },
      { t = "nl" },
      { t = "text", s = "que has oído, anda." },
      { t = "eos" },
    },
  ["g3:0817aad7"] = {
      { t = "text", s = "¡Menudo revés!..." },
      { t = "nl" },
      { t = "text", s = "¡Vámonos con el resto!" },
      { t = "para" },
      { t = "text", s = "¡Tú, no te atrevas a entrar!" },
      { t = "para" },
      { t = "text", s = "¡Te lo digo por tu bien!" },
      { t = "nl" },
      { t = "text", s = "¡Ni te lo plantees!" },
      { t = "eos" },
    },
  ["g3:0817ab73"] = {
      { t = "text", s = "Se dice que un volcán está activo," },
      { t = "nl" },
      { t = "text", s = "cuando entra en erupción o está" },
      { t = "scroll" },
      { t = "text", s = "a punto." },
      { t = "eos" },
    },
  ["g3:0817abaa"] = {
      { t = "text", s = "Guau... ¡qué pasada!" },
      { t = "nl" },
      { t = "text", s = "¡Me ha entrado un calor!" },
      { t = "eos" },
    },
  ["g3:0817abd8"] = {
      { t = "text", s = "Dicen que hay unos 1.500 volcanes" },
      { t = "nl" },
      { t = "text", s = "activos en todo el mundo." },
      { t = "para" },
      { t = "text", s = "Cada vez que lo pienso, ¡me entra" },
      { t = "nl" },
      { t = "text", s = "una cosa!" },
      { t = "eos" },
    },
  ["g3:0817ac55"] = {
      { t = "text", s = "¿Sabes cómo se forman las cuevas" },
      { t = "nl" },
      { t = "text", s = "en el interior de los volcanes?" },
      { t = "eos" },
    },
  ["g3:0817ac82"] = {
      { t = "text", s = "¡Aaaah!" },
      { t = "nl" },
      { t = "text", s = "¡Eres increíble!" },
      { t = "eos" },
    },
  ["g3:0817aca2"] = {
      { t = "text", s = "Cuando la lava de la superficie se" },
      { t = "nl" },
      { t = "text", s = "solidifica, aún puede quedar magma" },
      { t = "scroll" },
      { t = "text", s = "por salir." },
      { t = "para" },
      { t = "text", s = "Y son los conductos que abre" },
      { t = "nl" },
      { t = "text", s = "en su camino al exterior, los que" },
      { t = "scroll" },
      { t = "text", s = "pasan a ser las cuevas." },
      { t = "eos" },
    },
  ["g3:0817ad06"] = {
      { t = "text", s = "He estado entrenándome para" },
      { t = "nl" },
      { t = "text", s = "recuperar mi fuerza interior..." },
      { t = "para" },
      { t = "text", s = "¡Y lo que sin duda he conseguido" },
      { t = "nl" },
      { t = "text", s = "ha sido ponerme en forma!" },
      { t = "eos" },
    },
  ["g3:0817ad6b"] = {
      { t = "text", s = "Creo que he exagerado..." },
      { t = "eos" },
    },
  ["g3:0817ad89"] = {
      { t = "text", s = "Luchando me recuerdas a mi antiguo" },
      { t = "nl" },
      { t = "text", s = "noviete..." },
      { t = "eos" },
    },
  ["g3:0817adc5"] = {
      { t = "text", s = "¡" },
      { t = "player" },
      { t = "text", s = " encontró un RUBÍ!" },
      { t = "eos" },
    },
  ["g3:0817add6"] = {
