      { t = "nl" },
      { t = "text", s = "¡Ayúdame, ayúdame!" },
      { t = "para" },
      { t = "text", s = "POKéMON ho-horrible..." },
      { t = "nl" },
      { t = "text", s = "Mmme he sustado ucho..." },
      { t = "para" },
      { t = "text", s = "Buaaaaa... Sustado a PEDRITA..." },
      { t = "para" },
      { t = "text", s = "Teno miedo..." },
      { t = "nl" },
      { t = "text", s = "Quiedo id a casa..." },
      { t = "eos" },
    },
  ["g3:0817ae8e"] = {
      { t = "text", s = "¡Ta ahí, ta ahí!" },
      { t = "nl" },
      { t = "text", s = "¡Fuela, fuela! ¡Teno miedo!" },
      { t = "para" },
      { t = "text", s = "¡Buaaaaaaaaa!" },
      { t = "nl" },
      { t = "text", s = "¡Papiiiiiiiiii!" },
      { t = "eos" },
    },
  ["g3:0817aee1"] = {
