      { t = "nl" },
      { t = "text", s = "¡Acias!" },
      { t = "para" },
      { t = "text", s = "PEDRITA quedía BAYAS." },
      { t = "para" },
      { t = "text", s = "Toma, cara ti." },
      { t = "eos" },
    },
  ["g3:0817af3b"] = {
      { t = "text", s = "¿Quién ede?" },
      { t = "para" },
      { t = "text", s = "PEDRITA sustada, lleva a casa" },
      { t = "nl" },
      { t = "text", s = "con papi a PEDRITA." },
      { t = "para" },
      { t = "text", s = "¡A casa con papi!" },
      { t = "nl" },
      { t = "text", s = "¡Con papi!" },
      { t = "eos" },
    },
  ["g3:0817af9f"] = {
      { t = "text", s = "El SACO de las BAYAS está lleno." },
      { t = "eos" },
    },
  ["g3:0817afd6"] = {
