      { t = "nl" },
      { t = "text", s = "Presencia de POKéMON salvajes" },
      { t = "scroll" },
      { t = "text", s = "devoradores de BAYAS." },
      { t = "eos" },
    },
  ["g3:0817b04f"] = {
      { t = "text", s = "LORELEI: ¡Ni te acerques a los" },
