      { t = "text", s = "POKéMON que hay en la cueva!" },
      { t = "para" },
      { t = "text", s = "Si no, te las tendrás que ver" },
      { t = "nl" },
      { t = "text", s = "conmigo." },
      { t = "eos" },
    },
  ["g3:0817b0b9"] = {
      { t = "text", s = "Venga ya, señora, no incordie." },
      { t = "para" },
      { t = "text", s = "¡Chicos, sigamos a lo nuestro!" },
      { t = "eos" },
    },
  ["g3:0817b109"] = {
      { t = "text", s = "LORELEI: ¡¿" },
      { t = "player" },
      { t = "text", s = "?!" },
      { t = "nl" },
      { t = "text", s = "¿Qué haces aquí?" },
      { t = "para" },
      { t = "text", s = "Bueno, ya charlaremos después." },
      { t = "nl" },
      { t = "text", s = "Ayúdame con estos elementos." },
      { t = "para" },
      { t = "text", s = "Necesito que me eches una mano" },
      { t = "nl" },
      { t = "text", s = "para frenar a esta gentuza." },
      { t = "para" },
      { t = "text", s = "Han estado atrapando POKéMON" },
      { t = "nl" },
      { t = "text", s = "aquí, y vendiéndolos por ahí." },
      { t = "para" },
      { t = "text", s = "¿Vas a ayudarme?" },
      { t = "nl" },
      { t = "text", s = "¡Pues adelante!" },
      { t = "eos" },
    },
  ["g3:0817b20b"] = {
      { t = "text", s = "¿Perdón?" },
      { t = "para" },
      { t = "text", s = "¿Quién dice aquí lo que podemos" },
      { t = "nl" },
      { t = "text", s = "o no podemos hacer con los" },
      { t = "scroll" },
      { t = "text", s = "POKéMON que atrapamos?" },
      { t = "eos" },
    },
  ["g3:0817b251"] = {
      { t = "text", s = "¡No me esperaba yo esto!" },
      { t = "eos" },
    },
  ["g3:0817b269"] = {
      { t = "text", s = "LORELEI: Ja." },
      { t = "nl" },
      { t = "text", s = "Qué cosa más endeble..." },
      { t = "para" },
      { t = "text", s = "A ver, tú." },
      { t = "nl" },
      { t = "text", s = "Dime." },
      { t = "para" },
      { t = "text", s = "¿Dónde tenéis a los POKéMON" },
      { t = "nl" },
      { t = "text", s = "que habéis capturado?" },
      { t = "para" },
      { t = "text", s = "Dímelo ahora mismo si no quieres" },
      { t = "nl" },
      { t = "text", s = "que te dé una zurra." },
      { t = "eos" },
    },
  ["g3:0817b2ef"] = {
      { t = "text", s = "¡Ni en broma!" },
      { t = "nl" },
      { t = "text", s = "¡No pienso decírtelo!" },
      { t = "eos" },
    },
  ["g3:0817b313"] = {
      { t = "text", s = "LORELEI: Como no me lo digas," },
      { t = "nl" },
      { t = "text", s = "¡acabarás congelado!" },
      { t = "para" },
      { t = "text", s = "Mi LAPRAS está que trina por lo" },
      { t = "nl" },
      { t = "text", s = "que les habéis hecho a sus amigos." },
      { t = "para" },
      { t = "text", s = "¡Venga, LAPRAS!" },
      { t = "nl" },
      { t = "text", s = "¡RAYO HIELO!..." },
      { t = "eos" },
    },
  ["g3:0817b399"] = {
      { t = "text", s = "¡Aaaaah!" },
      { t = "nl" },
      { t = "text", s = "¡Para, para, que te lo digo!" },
      { t = "para" },
      { t = "text", s = "Los POKéMON están en el ALMACÉN" },
      { t = "nl" },
      { t = "text", s = "ROCKET de ISLA INTA." },
      { t = "para" },
      { t = "text", s = "¡Hala, ya lo he dicho!" },
      { t = "nl" },
      { t = "text", s = "¡Vámonos ya de aquí!" },
      { t = "para" },
      { t = "text", s = "¡Pero que sepas que dudo mucho" },
      { t = "nl" },
      { t = "text", s = "que puedas entrar en el ALMACÉN" },
      { t = "scroll" },
      { t = "text", s = "ROCKET!" },
      { t = "para" },
      { t = "text", s = "¡Ja, ja, ja!" },
      { t = "eos" },
    },
  ["g3:0817b457"] = {
      { t = "player" },
      { t = "text", s = ", gracias." },
      { t = "nl" },
      { t = "text", s = "Ha sido horrible..." },
      { t = "para" },
      { t = "text", s = "Yo he nacido aquí y he pasado" },
      { t = "nl" },
      { t = "text", s = "toda mi vida en estas islas." },
      { t = "para" },
      { t = "text", s = "No sabía que esos golfos" },
      { t = "nl" },
      { t = "text", s = "estuvieran por aquí sueltos..." },
      { t = "eos" },
    },
  ["g3:0817b4e3"] = {
