      { t = "text", s = "encerrados en el cobertizo..." },
      { t = "eos" },
    },
  ["g3:0817b512"] = {
      { t = "text", s = "La puerta está abierta." },
      { t = "nl" },
      { t = "text", s = "Se ve que los POKéMON han huido." },
      { t = "eos" },
    },
  ["g3:0817b54d"] = {
      { t = "text", s = "¿Has venido hasta aquí sabiendo" },
      { t = "nl" },
      { t = "text", s = "que era el ALMACÉN ROCKET?" },
      { t = "eos" },
    },
  ["g3:0817b585"] = {
      { t = "text", s = "Pero bueno, ¿tú qué te crees?" },
      { t = "eos" },
    },
  ["g3:0817b5a6"] = {
      { t = "text", s = "¿Que si el TEAM ROCKET se ha" },
      { t = "nl" },
      { t = "text", s = "separado?" },
      { t = "scroll" },
      { t = "text", s = "Pero ¿tú de qué planeta vienes?" },
      { t = "eos" },
    },
  ["g3:0817b5d6"] = {
      { t = "text", s = "Tus POKéMON parecen muy fuertes." },
