      { t = "text", s = "¿No te gustaría venderlos?" },
      { t = "para" },
      { t = "text", s = "¡Ah, que quieres luchar!" },
      { t = "eos" },
    },
  ["g3:0817b62f"] = {
      { t = "text", s = "Ufff..." },
      { t = "nl" },
      { t = "text", s = "Ha sido mucha paliza..." },
      { t = "eos" },
    },
  ["g3:0817b642"] = {
      { t = "text", s = "¡Oye, te podemos pagar mucho" },
      { t = "nl" },
      { t = "text", s = "por tus POKéMON!" },
      { t = "eos" },
    },
  ["g3:0817b677"] = {
      { t = "text", s = "Me han hablado mucho de ti." },
      { t = "para" },
      { t = "text", s = "¡Ante nuestro JEFE GIOVANNI" },
      { t = "nl" },
      { t = "text", s = "no vas a poder hacer nada!" },
      { t = "eos" },
    },
  ["g3:0817b6d9"] = {
      { t = "text", s = "No... te... rías... Grrr..." },
      { t = "eos" },
    },
  ["g3:0817b6ef"] = {
      { t = "text", s = "¡No deberías meter las narices en" },
      { t = "nl" },
      { t = "text", s = "las cosas de los mayores, cotilla!" },
      { t = "eos" },
    },
  ["g3:0817b72d"] = {
      { t = "text", s = "Ni sé ni me importa si lo que hago" },
      { t = "nl" },
      { t = "text", s = "está bien o no..." },
      { t = "para" },
      { t = "text", s = "Yo confío en GIOVANNI y cumplo" },
