      { t = "eos" },
    },
  ["g3:08183560"] = {
      { t = "text", s = "¡Hola!" },
      { t = "nl" },
      { t = "text", s = "¡Me gustan los pantalones cortos!" },
      { t = "para" },
      { t = "text", s = "¡Son muy cómodos!" },
