    },
  ["g3:081835a0"] = {
      { t = "text", s = "¡No me lo puedo creer!" },
      { t = "eos" },
    },
  ["g3:081835b4"] = {
      { t = "text", s = "¿Estás guardando a tus POKéMON" },
      { t = "nl" },
      { t = "text", s = "en el PC?" },
      { t = "para" },
      { t = "text", s = "¡Cada CAJA puede tener 30" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:08183616"] = {
      { t = "text", s = "Estabas mirándome, ¿verdad?" },
      { t = "eos" },
    },
  ["g3:0818363f"] = {
      { t = "text", s = "¡Eres de lo que no hay!" },
      { t = "eos" },
    },
  ["g3:0818364c"] = {
