      { t = "text", s = "ganado!" },
      { t = "eos" },
    },
  ["g3:081836d9"] = {
      { t = "text", s = "¡Si una CAJA de POKéMON del PC" },
      { t = "nl" },
      { t = "text", s = "está llena, cambia a otra CAJA!" },
      { t = "eos" },
    },
  ["g3:0818371b"] = {
      { t = "text", s = "¡Esa mirada tuya fue de lo más" },
