      { t = "text", s = "misteriosa!" },
      { t = "eos" },
    },
  ["g3:08183746"] = {
      { t = "text", s = "¡Sé amable!" },
      { t = "eos" },
    },
  ["g3:0818374f"] = {
      { t = "text", s = "¡Para evitar luchar, procura que" },
      { t = "nl" },
      { t = "text", s = "no te vean!" },
      { t = "eos" },
    },
  ["g3:08183786"] = {
      { t = "text", s = "¡Oye!" },
      { t = "nl" },
      { t = "text", s = "¡No llevas pantalón corto!" },
      { t = "eos" },
    },
  ["g3:081837bd"] = {
      { t = "text", s = "¡He perdido!" },
      { t = "nl" },
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:081837cf"] = {
