      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:08183837"] = {
      { t = "text", s = "¡Estoy acabado!" },
      { t = "eos" },
    },
  ["g3:08183849"] = {
      { t = "text", s = "¡Los POKéMON entrenados son más" },
