      { t = "text", s = "fuertes que los salvajes!" },
      { t = "eos" },
    },
  ["g3:0818387a"] = {
      { t = "text", s = "¡Oye!" },
      { t = "nl" },
      { t = "text", s = "¿Por qué me has tocado?" },
      { t = "eos" },
    },
  ["g3:08183891"] = {
      { t = "text", s = "¿Eso es todo?" },
      { t = "eos" },
    },
  ["g3:0818389c"] = {
