    },
  ["g3:08183e3c"] = {
      { t = "text", s = "(Pues sí que...)" },
      { t = "eos" },
    },
  ["g3:08183e4e"] = {
      { t = "text", s = "¡Perdona!" },
      { t = "nl" },
      { t = "text", s = "¡Esta conversación es privada!" },
      { t = "eos" },
    },
  ["g3:08183e79"] = {
      { t = "text", s = "¡Odio perder!" },
