      { t = "text", s = "para protegerme." },
      { t = "eos" },
    },
  ["g3:08183f90"] = {
      { t = "text", s = "¿Yo?" },
      { t = "nl" },
      { t = "text", s = "Pues vale. ¡Jugaré!" },
      { t = "eos" },
    },
  ["g3:08183fab"] = {
      { t = "text", s = "¡No ha podido ser!" },
      { t = "eos" },
    },
  ["g3:08183fc4"] = {
      { t = "text", s = "¡Quiero ser más fuerte!" },
      { t = "nl" },
      { t = "text", s = "¿Cuál es tu secreto?" },
      { t = "eos" },
    },
  ["g3:08183ff0"] = {
