      { t = "text", s = "POKéMON, pero..." },
      { t = "scroll" },
      { t = "text", s = "¿Qué tal en química?" },
      { t = "eos" },
    },
  ["g3:08184100"] = {
      { t = "text", s = "¡Ah!" },
      { t = "nl" },
      { t = "text", s = "¡Fusión nuclear!" },
      { t = "eos" },
    },
  ["g3:0818410e"] = {
      { t = "text", s = "¡Se me da mejor en el cole!" },
      { t = "eos" },
    },
  ["g3:0818412f"] = {
      { t = "text", s = "¡Muy bien!" },
      { t = "nl" },
      { t = "text", s = "¡Echemos los dados!" },
      { t = "eos" },
    },
  ["g3:0818414d"] = {
      { t = "text", s = "¡Vaya!" },
      { t = "nl" },
      { t = "text", s = "¡Me he quedado corto!" },
      { t = "eos" },
    },
  ["g3:08184162"] = {
      { t = "text", s = "¡Hoy no es mi día de suerte!" },
