      { t = "nl" },
      { t = "text", s = "bloqueada..." },
      { t = "eos" },
    },
  ["g3:08184321"] = {
      { t = "text", s = "¡MEOWTH es muy mono, meow, meow!" },
      { t = "eos" },
    },
  ["g3:08184346"] = {
      { t = "text", s = "¡Meow!" },
      { t = "eos" },
    },
  ["g3:08184350"] = {
      { t = "text", s = "¡Creo que PIDGEY y RATTATA" },
      { t = "nl" },
      { t = "text", s = "también son muy monos!" },
      { t = "eos" },
    },
  ["g3:0818437a"] = {
