      { t = "nl" },
      { t = "text", s = "tonto!" },
      { t = "eos" },
    },
  ["g3:081843a6"] = {
      { t = "text", s = "¡Mira lo que has hecho!" },
      { t = "eos" },
    },
  ["g3:081843d2"] = {
      { t = "text", s = "El guardián de la entrada a" },
      { t = "nl" },
      { t = "text", s = "AZAFRÁN no nos dejará pasar." },
      { t = "para" },
      { t = "text", s = "¡Sé que hace su trabajo," },
      { t = "nl" },
      { t = "text", s = "pero es que es lo peor!" },
      { t = "eos" },
    },
  ["g3:08184432"] = {
      { t = "text", s = "¡Soy un jugón errante!" },
      { t = "eos" },
    },
  ["g3:0818444f"] = {
      { t = "text", s = "¡He perdido el gran premio!" },
      { t = "eos" },
    },
  ["g3:08184466"] = {
      { t = "text", s = "¡Cuando juego y entreno POKéMON" },
      { t = "nl" },
      { t = "text", s = "no puedo parar!" },
      { t = "eos" },
    },
  ["g3:081844ac"] = {
      { t = "text", s = "¿Qué POKéMON es mono, redondo" },
      { t = "nl" },
      { t = "text", s = "y blando?" },
      { t = "eos" },
    },
  ["g3:081844d6"] = {
      { t = "text", s = "¡Ya basta!" },
      { t = "para" },
      { t = "text", s = "¡No seas cruel con mis CLEFAIRY!" },
      { t = "eos" },
    },
  ["g3:081844fd"] = {
      { t = "text", s = "He leído que CLEFAIRY evoluciona" },
      { t = "nl" },
      { t = "text", s = "cuando es expuesto a una PIEDRA" },
      { t = "scroll" },
      { t = "text", s = "LUNAR." },
      { t = "para" },
      { t = "text", s = "Lo leí en el DIARIO POKéMON." },
      { t = "nl" },
      { t = "text", s = "¿Será verdad?" },
      { t = "eos" },
    },
  ["g3:08184576"] = {
      { t = "text", s = "VÍA SUBTERRÁNEA:" },
      { t = "nl" },
      { t = "text", s = "CIUDAD AZULONA - PUEBLO LAVANDA" },
      { t = "eos" },
    },
  ["g3:081845a4"] = {
