      { t = "nl" },
      { t = "text", s = "fuerzas..." },
      { t = "eos" },
    },
  ["g3:081845f2"] = {
      { t = "text", s = "TITA: Yo atrapé mi POKéMON" },
      { t = "nl" },
      { t = "text", s = "con LIN." },
      { t = "eos" },
    },
  ["g3:08184616"] = {
