      { t = "nl" },
      { t = "text", s = "por haber ganado." },
      { t = "eos" },
    },
  ["g3:081847b7"] = {
      { t = "text", s = "¡Tienes algunos POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¡En guardia!" },
      { t = "eos" },
    },
  ["g3:081847df"] = {
      { t = "text", s = "¡Me has dejado...!" },
      { t = "eos" },
    },
  ["g3:081847f0"] = {
