      { t = "text", s = "está muy oscuro." },
      { t = "para" },
      { t = "text", s = "Necesitarás DESTELLO para poder" },
      { t = "nl" },
      { t = "text", s = "cruzarlo sin problemas." },
      { t = "eos" },
    },
  ["g3:08184844"] = {
