      { t = "eos" },
    },
  ["g3:0818491c"] = {
      { t = "text", s = "¡Eres demasiado!" },
      { t = "eos" },
    },
  ["g3:08184931"] = {
      { t = "text", s = "¡Tienes madera!" },
      { t = "nl" },
      { t = "text", s = "¡Buena suerte!" },
      { t = "eos" },
    },
  ["g3:0818495e"] = {
      { t = "text", s = "¡Ja!" },
      { t = "nl" },
      { t = "text", s = "¡Qué bien! ¡Me estaba aburriendo!" },
      { t = "eos" },
    },
  ["g3:0818497f"] = {
