      { t = "eos" },
    },
  ["g3:081849df"] = {
      { t = "text", s = "¡Eh!" },
      { t = "nl" },
      { t = "text", s = "¿Me enseñas la fuerza que tienes?" },
      { t = "eos" },
    },
  ["g3:08184a04"] = {
      { t = "text", s = "¿Qué ha pasado?" },
