      { t = "eos" },
    },
  ["g3:08184ad5"] = {
      { t = "text", s = "¡Jajajaja!" },
      { t = "nl" },
      { t = "text", s = "¡Me has ganado!" },
      { t = "eos" },
    },
  ["g3:08184af1"] = {
