    },
  ["g3:08185114"] = {
      { t = "text", s = "¡Has tenido mucha suerte!" },
      { t = "eos" },
    },
  ["g3:08185135"] = {
      { t = "text", s = "Nunca he ganado..." },
      { t = "eos" },
    },
  ["g3:0818514e"] = {
      { t = "text", s = "Lo veía venir..." },
