      { t = "text", s = "¡Bien!" },
      { t = "nl" },
      { t = "text", s = "¡Ha picado algo!" },
      { t = "eos" },
    },
  ["g3:0818541b"] = {
      { t = "text", s = "¡Bah!" },
      { t = "nl" },
      { t = "text", s = "¡Era muy pequeñajo!" },
      { t = "eos" },
    },
  ["g3:08185432"] = {
      { t = "text", s = "¡Alto!" },
      { t = "nl" },
      { t = "text", s = "¡Mi sedal está enganchado!" },
      { t = "eos" },
    },
  ["g3:0818544e"] = {
      { t = "text", s = "¡Ten paciencia!" },
      { t = "nl" },
      { t = "text", s = "¡Pescar requiere tiempo!" },
      { t = "eos" },
    },
  ["g3:08185475"] = {
      { t = "text", s = "¡Ése se escapó!" },
      { t = "eos" },
    },
  ["g3:08185488"] = {
      { t = "text", s = "¡Con una CAÑA mejor podría pescar" },
      { t = "nl" },
      { t = "text", s = "mejores POKéMON!" },
      { t = "eos" },
    },
  ["g3:081854b9"] = {
      { t = "text", s = "¿Has encontrado una PIEDRA LUNAR?" },
      { t = "eos" },
    },
  ["g3:081854ed"] = {
      { t = "text", s = "¡Auuuu!" },
      { t = "eos" },
    },
  ["g3:081854f2"] = {
      { t = "text", s = "¡Podría haber transformado a mis" },
      { t = "nl" },
      { t = "text", s = "POKéMON con una PIEDRA LUNAR!" },
      { t = "para" },
      { t = "text", s = "¡Y podría haber ganado!" },
      { t = "eos" },
    },
  ["g3:08185547"] = {
      { t = "text", s = "¡Soy un experto en electricidad!" },
      { t = "para" },
      { t = "text", s = "Pero no sé nada sobre los POKéMON" },
      { t = "nl" },
      { t = "text", s = "de mar." },
      { t = "eos" },
    },
  ["g3:0818559b"] = {
      { t = "text", s = "¡Se acabó!" },
      { t = "eos" },
    },
  ["g3:081855a6"] = {
      { t = "text", s = "El agua conduce la electricidad." },
      { t = "nl" },
      { t = "text", s = "¡Deberías poder atrapar a los" },
      { t = "scroll" },
      { t = "text", s = "POKéMON de mar!" },
      { t = "eos" },
    },
  ["g3:081855e1"] = {
      { t = "text", s = "¡El PESCADOR LOCO contra alguien" },
      { t = "nl" },
      { t = "text", s = "que no tiene idea sobre POKéMON!" },
      { t = "eos" },
    },
  ["g3:08185606"] = {
      { t = "text", s = "¡Te has pasado!" },
      { t = "eos" },
    },
  ["g3:08185616"] = {
      { t = "text", s = "¡Me has ganado con los POKéMON," },
      { t = "nl" },
      { t = "text", s = "pero yo soy muy bueno pescando!" },
      { t = "para" },
      { t = "text", s = "Supongo que hay que hacer lo que" },
      { t = "nl" },
      { t = "text", s = "mejor se le da a cada uno..." },
      { t = "eos" },
    },
  ["g3:08185682"] = {
      { t = "text", s = "A mí me encanta pescar, ¡pero" },
      { t = "nl" },
      { t = "text", s = "es que no pican ni a la de tres!" },
      { t = "eos" },
    },
  ["g3:081856d0"] = {
      { t = "text", s = "No es fácil..." },
      { t = "eos" },
    },
  ["g3:081856df"] = {
      { t = "text", s = "Está bien." },
      { t = "nl" },
      { t = "text", s = "Perder ya no me importa." },
      { t = "eos" },
    },
  ["g3:0818570e"] = {
      { t = "text", s = "¡Nunca se sabe lo que puedes" },
      { t = "nl" },
      { t = "text", s = "pescar!" },
      { t = "eos" },
    },
  ["g3:08185744"] = {
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:0818574d"] = {
      { t = "text", s = "Es fácil pescar MAGIKARP," },
      { t = "nl" },
      { t = "text", s = "¡son tan débiles!" },
      { t = "eos" },
    },
  ["g3:08185797"] = {
      { t = "text", s = "RUTA 12:" },
      { t = "nl" },
      { t = "text", s = "LAVANDA, al norte" },
      { t = "eos" },
    },
  ["g3:081857b3"] = {
      { t = "text", s = "ZONA DE PESCA" },
      { t = "eos" },
    },
  ["g3:081857c5"] = {
      { t = "text", s = "ARE: Si gano, le pediré a AGA" },
      { t = "nl" },
      { t = "text", s = "que se case conmigo." },
      { t = "eos" },
    },
  ["g3:081857f1"] = {
      { t = "text", s = "ARE: ¿Puedes dejarnos ganar," },
      { t = "nl" },
      { t = "text", s = "por favor?" },
      { t = "eos" },
    },
  ["g3:0818581f"] = {
      { t = "text", s = "ARE: AGA, ¡lo siento, cariño!" },
      { t = "eos" },
    },
  ["g3:08185842"] = {
      { t = "text", s = "ARE: AGA y yo vamos a estar juntos" },
      { t = "nl" },
      { t = "text", s = "toda la vida." },
      { t = "para" },
      { t = "text", s = "¡Y no lucharemos hasta que no" },
      { t = "nl" },
      { t = "text", s = "tengas dos POKéMON!" },
      { t = "eos" },
    },
  ["g3:081858a6"] = {
      { t = "text", s = "AGA: Oye, ARE..." },
      { t = "para" },
      { t = "text", s = "Si ganamos, ¡me caso contigo!" },
      { t = "eos" },
    },
  ["g3:081858d0"] = {
      { t = "text", s = "AGA: Oh... ¿Por qué?" },
      { t = "eos" },
    },
  ["g3:081858e2"] = {
      { t = "text", s = "AGA: ¡ARE, eres medio lelo! ¡Todo" },
      { t = "nl" },
      { t = "text", s = "se ha fastidiado por tu culpa!" },
      { t = "eos" },
    },
  ["g3:08185908"] = {
      { t = "text", s = "AGA: ¡No pienso luchar sin mi ARE!" },
      { t = "para" },
      { t = "text", s = "¿No tienes dos POKéMON?" },
      { t = "eos" },
    },
  ["g3:08185955"] = {
      { t = "text", s = "¡Mis pájaros POKéMON quieren" },
      { t = "nl" },
      { t = "text", s = "pelear!" },
      { t = "eos" },
    },
  ["g3:0818597e"] = {
      { t = "text", s = "¿Perdió mi combinación de pájaros?" },
      { t = "eos" },
    },
  ["g3:081859a2"] = {
      { t = "text", s = "Mis POKéMON parecen felices" },
      { t = "nl" },
      { t = "text", s = "aunque hayan perdido." },
      { t = "eos" },
    },
  ["g3:081859cf"] = {
      { t = "text", s = "¡Dicen que soy muy buena" },
      { t = "nl" },
      { t = "text", s = "para ser tan pequeña!" },
      { t = "eos" },
    },
  ["g3:081859ec"] = {
      { t = "text", s = "¡Oh!" },
      { t = "nl" },
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:081859f9"] = {
      { t = "text", s = "Quiero ser una gran ENTRENADORA." },
      { t = "nl" },
      { t = "text", s = "Voy a entrenarme mucho." },
      { t = "eos" },
    },
  ["g3:08185a37"] = {
      { t = "text", s = "¡Qué chulas son tus MEDALLAS!" },
      { t = "eos" },
    },
  ["g3:08185a56"] = {
      { t = "text", s = "¡No he estado a la altura!" },
      { t = "eos" },
    },
  ["g3:08185a62"] = {
      { t = "text", s = "¡Sé que lograste esas MEDALLAS" },
      { t = "nl" },
      { t = "text", s = "de los LÍDERES del GIMNASIO!" },
      { t = "eos" },
    },
  ["g3:08185a91"] = {
      { t = "text", s = "Mis simpáticos POKéMON quieren" },
      { t = "nl" },
      { t = "text", s = "conocerte." },
      { t = "eos" },
    },
  ["g3:08185ac1"] = {
      { t = "text", s = "¡Uauu!" },
      { t = "nl" },
      { t = "text", s = "¡Me has machacado!" },
      { t = "eos" },
    },
  ["g3:08185ade"] = {
      { t = "text", s = "¡Tienes que hacer luchar a tus" },
      { t = "nl" },
      { t = "text", s = "POKéMON para fortalecerlos!" },
      { t = "eos" },
    },
  ["g3:08185b12"] = {
      { t = "text", s = "¡Una vez encontré CARBURANTE" },
      { t = "nl" },
      { t = "text", s = "en una cueva!" },
      { t = "eos" },
    },
  ["g3:08185b48"] = {
      { t = "text", s = "¡Lo he hecho fatal!" },
      { t = "eos" },
    },
  ["g3:08185b67"] = {
      { t = "text", s = "El CARBURANTE aumentó la" },
      { t = "nl" },
      { t = "text", s = "VELOCIDAD de mis POKéMON." },
      { t = "eos" },
    },
  ["g3:08185b8f"] = {
      { t = "text", s = "No voy a perder." },
      { t = "nl" },
      { t = "text", s = "¡El viento sopla en mi dirección!" },
      { t = "eos" },
    },
  ["g3:08185bca"] = {
      { t = "text", s = "¡El viento ha cambiado!" },
      { t = "eos" },
    },
  ["g3:08185bdb"] = {
      { t = "text", s = "He perdido. Creo que usaré" },
      { t = "nl" },
      { t = "text", s = "VOLAR para ir a casa." },
      { t = "eos" },
    },
  ["g3:08185bfc"] = {
      { t = "text", s = "¡Claro que jugaré contigo!" },
      { t = "eos" },
    },
  ["g3:08185c1f"] = {
      { t = "text", s = "¡Oh!" },
      { t = "nl" },
      { t = "text", s = "¡Qué salvaje eres!" },
      { t = "eos" },
    },
  ["g3:08185c35"] = {
      { t = "text", s = "¿Cuál es más fuerte, un POKéMON" },
      { t = "nl" },
      { t = "text", s = "macho o hembra?" },
      { t = "eos" },
    },
  ["g3:08185c69"] = {
      { t = "text", s = "¿Quieres jugar conmigo" },
      { t = "nl" },
      { t = "text", s = "a POKéMON?" },
      { t = "eos" },
    },
  ["g3:08185c95"] = {
      { t = "text", s = "¿Ya se ha terminado?" },
      { t = "eos" },
    },
  ["g3:08185ca8"] = {
      { t = "text", s = "¡No sé nada sobre los POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¡Me gustan los más chulos!" },
      { t = "eos" },
    },
  ["g3:08185d05"] = {
      { t = "text", s = "¿Y tú qué miras?" },
      { t = "eos" },
    },
  ["g3:08185d1d"] = {
      { t = "text", s = "¡Vaya!" },
      { t = "nl" },
      { t = "text", s = "¡Qué patinazo!" },
      { t = "eos" },
    },
  ["g3:08185d33"] = {
      { t = "text", s = "¡Olvídame!" },
      { t = "eos" },
    },
  ["g3:08185d3d"] = {
      { t = "text", s = "¡Me encantan los pájaros POKéMON!" },
      { t = "eos" },
    },
  ["g3:08185d7b"] = {
      { t = "text", s = "¡Me he quedado sin energía!" },
      { t = "eos" },
    },
  ["g3:08185d89"] = {
      { t = "text", s = "Ojalá pudiera volar como PIDGEY" },
      { t = "nl" },
      { t = "text", s = "y PIDGEOTTO..." },
      { t = "eos" },
    },
  ["g3:08185db7"] = {
      { t = "text", s = "PISTAS ENTRENADOR" },
      { t = "para" },
      { t = "text", s = "¡Mira a la izquierda de ese poste!" },
      { t = "eos" },
    },
  ["g3:08185def"] = {
      { t = "text", s = "PISTAS ENTRENADOR" },
      { t = "para" },
      { t = "text", s = "¡Usa SELECT para cambiar objetos" },
      { t = "nl" },
      { t = "text", s = "en la ventana OBJETOS!" },
      { t = "eos" },
    },
  ["g3:08185e2c"] = {
      { t = "text", s = "RUTA 13:" },
      { t = "nl" },
      { t = "text", s = "PUENTE SILENCIO, al norte" },
      { t = "eos" },
    },
  ["g3:08185e4d"] = {
      { t = "text", s = "¡Usa las MT para enseñar a tus" },
      { t = "nl" },
      { t = "text", s = "POKéMON buenos movimientos!" },
      { t = "eos" },
    },
  ["g3:08185e81"] = {
      { t = "text", s = "¡No lo he hecho muy bien!" },
      { t = "eos" },
    },
  ["g3:08185e9c"] = {
      { t = "text", s = "Tienes MO, ¿no? Los POKéMON" },
      { t = "nl" },
      { t = "text", s = "jamás olvidarán esos movimientos." },
      { t = "eos" },
    },
  ["g3:08185edf"] = {
      { t = "text", s = "Mis pájaros POKéMON deberían" },
      { t = "nl" },
      { t = "text", s = "poder luchar." },
      { t = "eos" },
    },
  ["g3:08185f0b"] = {
      { t = "text", s = "¡No estoy listo!" },
      { t = "eos" },
    },
  ["g3:08185f1a"] = {
      { t = "text", s = "Necesitan saber mejores ataques." },
      { t = "eos" },
    },
  ["g3:08185f46"] = {
      { t = "text", s = "¡Se venden MT en AZULONA!" },
      { t = "nl" },
      { t = "text", s = "¡Pero pocas personas tienen MO!" },
      { t = "eos" },
    },
  ["g3:08185fae"] = {
      { t = "text", s = "¡Ayy! ¡Qué mal!" },
      { t = "eos" },
    },
  ["g3:08185fbb"] = {
      { t = "text", s = "Enseña a tus POKéMON ataques" },
      { t = "nl" },
      { t = "text", s = "de sus mismos tipos para conseguir" },
      { t = "scroll" },
      { t = "text", s = "más potencia." },
      { t = "eos" },
    },
  ["g3:08186021"] = {
      { t = "text", s = "¿Has enseñado a VOLAR a tus" },
      { t = "nl" },
      { t = "text", s = "pájaros POKéMON?" },
      { t = "para" },
      { t = "text", s = "¡Es genial para ir por el cielo!" },
      { t = "eos" },
    },
  ["g3:0818607c"] = {
      { t = "text", s = "¡Qué forma de perder!" },
      { t = "eos" },
    },
  ["g3:08186091"] = {
      { t = "text", s = "¡Adoro a los pájaros POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¡Son los que me gusta criar!" },
      { t = "eos" },
    },
  ["g3:081860d9"] = {
      { t = "text", s = "¿Has oído hablar de los" },
      { t = "nl" },
      { t = "text", s = "misteriosos seres alados?" },
      { t = "eos" },
    },
  ["g3:0818610a"] = {
      { t = "text", s = "¿Qué?" },
      { t = "nl" },
      { t = "text", s = "¿Cómo he podido perder?" },
      { t = "eos" },
    },
  ["g3:0818611d"] = {
      { t = "text", s = "Los misteriosos seres alados son" },
      { t = "nl" },
      { t = "text", s = "legendarios pájaros POKéMON." },
      { t = "para" },
      { t = "text", s = "Hay tres: ARTICUNO, ZAPDOS" },
      { t = "nl" },
      { t = "text", s = "y MOLTRES." },
      { t = "eos" },
    },
  ["g3:0818618e"] = {
      { t = "text", s = "¡No me apetece!" },
      { t = "nl" },
      { t = "text", s = "Pero vale." },
      { t = "eos" },
    },
  ["g3:081861b3"] = {
      { t = "text", s = "¡Lo sabía!" },
      { t = "eos" },
    },
  ["g3:081861be"] = {
      { t = "text", s = "¡No es que sea tan importante" },
      { t = "nl" },
      { t = "text", s = "ganar o perder!" },
      { t = "eos" },
    },
  ["g3:081861f7"] = {
      { t = "text", s = "¡Venga, venga!" },
      { t = "nl" },
      { t = "text", s = "¡Vamos, vamos! ¡Adelante!" },
      { t = "eos" },
    },
  ["g3:08186223"] = {
      { t = "text", s = "¡Arg!" },
      { t = "nl" },
      { t = "text", s = "¡He perdido! ¡Lárgate!" },
      { t = "eos" },
    },
  ["g3:08186239"] = {
      { t = "text", s = "¿Qué, qué, qué?" },
      { t = "nl" },
      { t = "text", s = "¿Qué quieres?" },
      { t = "eos" },
    },
  ["g3:08186263"] = {
      { t = "text", s = "¡Perfecto!" },
      { t = "nl" },
      { t = "text", s = "¡Así pasaré el rato!" },
      { t = "eos" },
    },
  ["g3:08186291"] = {
      { t = "text", s = "¿Qué?" },
      { t = "nl" },
      { t = "text", s = "¿¡Tú!?" },
      { t = "eos" },
    },
  ["g3:0818629d"] = {
      { t = "text", s = "¡Entrenar POKéMON es un rollo!" },
      { t = "eos" },
    },
  ["g3:081862bd"] = {
      { t = "text", s = "¡Salimos por aquí porque hay" },
      { t = "nl" },
      { t = "text", s = "más espacio!" },
      { t = "eos" },
    },
  ["g3:081862ef"] = {
      { t = "text", s = "¡Descalificado!" },
      { t = "eos" },
    },
  ["g3:081862f8"] = {
      { t = "text", s = "¡Muy bien!" },
      { t = "nl" },
      { t = "text", s = "¡Tus POKéMON son superfuertes!" },
      { t = "para" },
      { t = "text", s = "¡La fuerza mola!" },
      { t = "nl" },
      { t = "text", s = "¡Y tú lo sabes!" },
      { t = "eos" },
    },
  ["g3:08186344"] = {
      { t = "text", s = "¿Quieres pelear con tus POKéMON?" },
      { t = "nl" },
      { t = "text", s = "¡Pues vale!" },
      { t = "eos" },
    },
  ["g3:08186362"] = {
      { t = "text", s = "¡Pulverizado!" },
      { t = "eos" },
    },
  ["g3:0818636e"] = {
      { t = "text", s = "¡Ya sabes quién ganaría" },
      { t = "nl" },
      { t = "text", s = "si peleáramos tú y yo!" },
      { t = "eos" },
    },
  ["g3:08186399"] = {
      { t = "text", s = "RUTA 14:" },
      { t = "nl" },
      { t = "text", s = "CIUDAD FUCSIA, al oeste" },
      { t = "eos" },
    },
  ["g3:081863b7"] = {
      { t = "text", s = "LENA: TEA, vamos a poner todo" },
      { t = "nl" },
      { t = "text", s = "de nuestra parte." },
      { t = "eos" },
    },
  ["g3:081863ea"] = {
      { t = "text", s = "LENA: Vaya, snif, snif..." },
      { t = "nl" },
      { t = "text", s = "Hemos perdido, ¿verdad?" },
      { t = "eos" },
    },
  ["g3:0818640d"] = {
      { t = "text", s = "LENA: ¿Hemos perdido por mi culpa?" },
      { t = "eos" },
    },
  ["g3:0818642e"] = {
      { t = "text", s = "LENA: Lucharemos cuando tengas" },
      { t = "nl" },
      { t = "text", s = "dos POKéMON." },
      { t = "eos" },
    },
  ["g3:0818645b"] = {
      { t = "text", s = "TEA: LENA, ¡vamos allá!" },
      { t = "nl" },
      { t = "text", s = "¡A por todas!" },
      { t = "eos" },
    },
  ["g3:08186487"] = {
      { t = "text", s = "TEA: ¡Eeeh! ¡No es justo!" },
      { t = "eos" },
    },
  ["g3:0818649c"] = {
      { t = "text", s = "TEA: ¡LENA, no llores! ¡Ya lo" },
      { t = "nl" },
      { t = "text", s = "haremos mejor la próxima vez!" },
      { t = "eos" },
    },
  ["g3:081864d3"] = {
      { t = "text", s = "TEA: ¿Quieres luchar?" },
      { t = "nl" },
      { t = "text", s = "¡Te hacen falta dos POKéMON!" },
      { t = "eos" },
    },
  ["g3:0818650b"] = {
      { t = "text", s = "¡Déjame probar los POKéMON" },
      { t = "nl" },
      { t = "text", s = "que acabo de cambiar!" },
      { t = "eos" },
    },
  ["g3:08186549"] = {
      { t = "text", s = "¡No ha sido suficiente!" },
      { t = "eos" },
    },
  ["g3:0818655a"] = {
      { t = "text", s = "No puedes variar el mote de ningún" },
      { t = "nl" },
      { t = "text", s = "POKéMON que hayas cambiado." },
      { t = "para" },
      { t = "text", s = "¡El ENTRENADOR original es el" },
      { t = "nl" },
      { t = "text", s = "único que puede!" },
      { t = "eos" },
    },
  ["g3:081865d3"] = {
      { t = "text", s = "¡Pareces manejable!" },
      { t = "nl" },
      { t = "text", s = "¡Creo que podría vencerte!" },
      { t = "para" },
      { t = "text", s = "¡Voy a intentarlo!" },
      { t = "eos" },
    },
  ["g3:08186612"] = {
      { t = "text", s = "No, ¡muy mal!" },
      { t = "eos" },
    },
  ["g3:0818661d"] = {
      { t = "text", s = "¡Me dan miedo los MOTORISTAS," },
      { t = "nl" },
      { t = "text", s = "son gamberros, horribles!" },
      { t = "eos" },
    },
  ["g3:0818664f"] = {
      { t = "text", s = "¡Silbando puedo llamar a los" },
      { t = "nl" },
      { t = "text", s = "pájaros POKéMON!" },
      { t = "eos" },
    },
  ["g3:0818667a"] = {
      { t = "text", s = "¡Ooh!" },
      { t = "nl" },
      { t = "text", s = "¡Qué tragedia!" },
      { t = "eos" },
    },
  ["g3:0818668d"] = {
      { t = "text", s = "Puede que no esté hecho para" },
      { t = "nl" },
      { t = "text", s = "luchar contra otros." },
      { t = "eos" },
    },
  ["g3:081866d1"] = {
      { t = "text", s = "Mis pájaros están temblando." },
      { t = "nl" },
      { t = "text", s = "Eres muy fuerte, ¿no?" },
      { t = "eos" },
    },
  ["g3:08186707"] = {
      { t = "text", s = "¡Lo que pensaba!" },
      { t = "eos" },
    },
  ["g3:0818671a"] = {
      { t = "text", s = "No sé si decirte esto, supongo" },
      { t = "nl" },
      { t = "text", s = "que ya lo sabes..." },
      { t = "para" },
      { t = "text", s = "¿Sabías que los movimientos" },
      { t = "nl" },
      { t = "text", s = "como TERREMOTO o FISURA" },
      { t = "scroll" },
      { t = "text", s = "no afectan a los pájaros?" },
      { t = "eos" },
    },
  ["g3:0818678b"] = {
      { t = "text", s = "¡Oh!" },
      { t = "nl" },
      { t = "text", s = "¡Mira qué encanto!" },
      { t = "eos" },
    },
  ["g3:081867c1"] = {
      { t = "text", s = "¡Pensaba que eras un encanto!" },
      { t = "eos" },
    },
  ["g3:081867da"] = {
      { t = "text", s = "¡Te perdono!" },
      { t = "nl" },
      { t = "text", s = "¡Eres adorable!" },
      { t = "eos" },
    },
  ["g3:0818680c"] = {
      { t = "text", s = "¡Cuido POKéMON porque vivo sola" },
      { t = "nl" },
      { t = "text", s = "y hacen que me sienta segura!" },
      { t = "eos" },
    },
  ["g3:08186841"] = {
      { t = "text", s = "¡Yo no quería un final así!" },
      { t = "eos" },
    },
  ["g3:0818686f"] = {
      { t = "text", s = "¡Me gusta ir a casa para estar" },
      { t = "nl" },
      { t = "text", s = "con mis POKéMON!" },
      { t = "para" },
      { t = "text", s = "Es una tranquilidad..." },
      { t = "eos" },
    },
  ["g3:081868b6"] = {
      { t = "text", s = "¡Oye! ¡Ven aquí!" },
      { t = "nl" },
      { t = "text", s = "¡Mira esto!" },
      { t = "eos" },
    },
  ["g3:081868e8"] = {
      { t = "text", s = "¡No sé qué decir!" },
      { t = "eos" },
    },
  ["g3:081868f1"] = {
      { t = "text", s = "¡Sólo se vive una vez, y yo vivo" },
      { t = "nl" },
      { t = "text", s = "como un forajido!" },
      { t = "scroll" },
      { t = "text", s = "¡NORMAS del TEAM ROCKET!" },
      { t = "eos" },
    },
  ["g3:08186936"] = {
      { t = "text", s = "¡Mira, colega, si pierdes contra" },
      { t = "nl" },
      { t = "text", s = "mí, todo tu dinero será mío!" },
      { t = "eos" },
    },
  ["g3:08186968"] = {
      { t = "text", s = "¡No puede ser!" },
      { t = "eos" },
    },
  ["g3:0818697c"] = {
      { t = "text", s = "¡Oye, que lo del dinero era broma!" },
      { t = "nl" },
      { t = "text", s = "¡No me hagas caso!" },
      { t = "eos" },
    },
  ["g3:081869ba"] = {
      { t = "text", s = "¿Qué mola?" },
      { t = "nl" },
      { t = "text", s = "¡Cambiar POKéMON!" },
      { t = "eos" },
    },
  ["g3:081869e6"] = {
      { t = "text", s = "¡He dicho cambiar!" },
      { t = "eos" },
    },
  ["g3:081869f4"] = {
      { t = "text", s = "¡Cambio POKéMON con mis amigos!" },
      { t = "eos" },
    },
  ["g3:08186a22"] = {
      { t = "text", s = "¿Quieres jugar con mis POKéMON?" },
      { t = "eos" },
    },
  ["g3:08186a40"] = {
      { t = "text", s = "¡Estaba demasiado impaciente!" },
      { t = "eos" },
    },
  ["g3:08186a55"] = {
      { t = "text", s = "¡Me entrenaré con gente más débil!" },
      { t = "eos" },
    },
  ["g3:08186a77"] = {
      { t = "text", s = "RUTA 15:" },
      { t = "nl" },
      { t = "text", s = "CIUDAD FUCSIA, al oeste" },
      { t = "eos" },
    },
  ["g3:08186a95"] = {
      { t = "text", s = "TINA: Eres genial. ¿Luchamos para" },
      { t = "nl" },
      { t = "text", s = "que aprenda mi hermano?" },
      { t = "eos" },
    },
  ["g3:08186acb"] = {
      { t = "text", s = "TINA: ¡TIN, concéntrate! ¡Hay que" },
      { t = "nl" },
      { t = "text", s = "concentrarse en lo que se hace!" },
      { t = "eos" },
    },
  ["g3:08186b0a"] = {
      { t = "text", s = "TINA: Tenemos que hacer algo," },
      { t = "nl" },
      { t = "text", s = "¡debemos entrenarnos más!" },
      { t = "eos" },
    },
  ["g3:08186b46"] = {
      { t = "text", s = "TINA: ¿Quieres desafiarnos?" },
      { t = "nl" },
      { t = "text", s = "¡Pues necesitas dos POKéMON!" },
      { t = "eos" },
    },
  ["g3:08186b89"] = {
      { t = "text", s = "TIN: Mi hermana se asusta cuando" },
      { t = "nl" },
      { t = "text", s = "perdemos." },
      { t = "eos" },
    },
  ["g3:08186bb1"] = {
      { t = "text", s = "TIN: Vaya, hermanita, lo siento..." },
      { t = "eos" },
    },
  ["g3:08186bd2"] = {
      { t = "text", s = "TIN: Mi hermana se pone un poco" },
      { t = "nl" },
      { t = "text", s = "pesada..." },
      { t = "eos" },
    },
  ["g3:08186bfe"] = {
      { t = "text", s = "TIN: ¿Te gustaría luchar" },
      { t = "nl" },
      { t = "text", s = "con nosotros?" },
      { t = "para" },
      { t = "text", s = "¡Pues vente con dos POKéMON!" },
      { t = "eos" },
    },
  ["g3:08186c4d"] = {
      { t = "text", s = "¿Qué quieres?" },
      { t = "eos" },
    },
  ["g3:08186c5f"] = {
      { t = "text", s = "¡No te atrevas a reírte!" },
      { t = "eos" },
    },
  ["g3:08186c75"] = {
      { t = "text", s = "Nos gusta correr por aquí." },
      { t = "nl" },
      { t = "text", s = "¿Y a ti?" },
      { t = "eos" },
    },
  ["g3:08186ca2"] = {
      { t = "text", s = "¡Bonita BICI!" },
      { t = "nl" },
      { t = "text", s = "¡Dámela!" },
      { t = "eos" },
    },
  ["g3:08186cbb"] = {
      { t = "text", s = "¡Fuera de combate!" },
      { t = "eos" },
    },
  ["g3:08186cc5"] = {
      { t = "text", s = "¡Olvídalo, nadie necesita tu BICI!" },
      { t = "eos" },
    },
  ["g3:08186ce5"] = {
      { t = "text", s = "¡Baja de ahí y lucha, enclenque!" },
      { t = "eos" },
    },
  ["g3:08186d06"] = {
      { t = "text", s = "¡Eres lo peor!" },
      { t = "eos" },
    },
  ["g3:08186d16"] = {
      { t = "text", s = "¡Odio perder!" },
      { t = "nl" },
      { t = "text", s = "¡No te acerques a mí!" },
      { t = "eos" },
    },
  ["g3:08186d39"] = {
      { t = "text", s = "¡Oye! ¡Me has dado!" },
      { t = "eos" },
    },
  ["g3:08186d52"] = {
      { t = "text", s = "¡Qué golpe!" },
      { t = "eos" },
    },
  ["g3:08186d5a"] = {
      { t = "text", s = "Te guste o no, de aquí no nos" },
      { t = "nl" },
      { t = "text", s = "va a echar nadie." },
      { t = "para" },
      { t = "text", s = "A FUCSIA puedes llegar también" },
      { t = "nl" },
      { t = "text", s = "desde CARMÍN, por la costa." },
      { t = "eos" },
    },
  ["g3:08186dd9"] = {
      { t = "text", s = "¡Tengo hambre y no estoy" },
      { t = "nl" },
      { t = "text", s = "de humor!" },
      { t = "eos" },
    },
  ["g3:08186e0d"] = {
      { t = "text", s = "¡Mal, mal, muy mal!" },
      { t = "eos" },
    },
  ["g3:08186e1c"] = {
      { t = "text", s = "¡Me gustan mis fuertes POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¡Son tremendos contra mis enemigos!" },
      { t = "eos" },
    },
  ["g3:08186e86"] = {
      { t = "text", s = "¡Eh, vamos a echar el rato!" },
      { t = "eos" },
    },
  ["g3:08186eb4"] = {
      { t = "text", s = "¡No me fastidies!" },
      { t = "eos" },
    },
  ["g3:08186ec7"] = {
      { t = "text", s = "Yo me parto tomándole el pelo" },
      { t = "nl" },
      { t = "text", s = "a la gente con mis POKéMON." },
      { t = "para" },
      { t = "text", s = "¡Son los mejores para asustar" },
      { t = "nl" },
      { t = "text", s = "a la gente y, además, muerden!" },
      { t = "eos" },
    },
  ["g3:08186f3d"] = {
      { t = "text", s = "¡Un POKéMON dormido bloquea" },
      { t = "nl" },
      { t = "text", s = "el camino!" },
      { t = "eos" },
    },
  ["g3:08186f7a"] = {
      { t = "text", s = "CAMINO DE BICIS" },
      { t = "nl" },
      { t = "text", s = "¡Buen descenso!" },
      { t = "eos" },
    },
  ["g3:08186f98"] = {
      { t = "text", s = "RUTA 16:" },
      { t = "nl" },
      { t = "text", s = "CIUDAD AZULONA - CIUDAD FUCSIA" },
      { t = "eos" },
    },
  ["g3:08186fbd"] = {
      { t = "text", s = "JOEL: Nuestro amor no conoce" },
      { t = "nl" },
      { t = "text", s = "límites." },
      { t = "para" },
      { t = "text", s = "Estamos enamorados y no lo" },
      { t = "nl" },
      { t = "text", s = "ocultamos." },
      { t = "eos" },
    },
  ["g3:08186ffa"] = {
      { t = "text", s = "JOEL: ¡He perdido, pero no" },
      { t = "nl" },
      { t = "text", s = "en el amor!" },
      { t = "eos" },
    },
  ["g3:08187027"] = {
      { t = "text", s = "JOEL: ¡Oye, LIZ, no te quedes" },
      { t = "nl" },
      { t = "text", s = "embobada conmigo!" },
      { t = "eos" },
    },
  ["g3:08187057"] = {
      { t = "text", s = "JOEL: ¿Sólo tienes un POKéMON?" },
      { t = "nl" },
      { t = "text", s = "¿Y no te da pena?" },
      { t = "eos" },
    },
  ["g3:08187097"] = {
      { t = "text", s = "LIZ: ¡A veces, pienso en todo" },
      { t = "nl" },
      { t = "text", s = "lo que nos queremos y se me pone" },
      { t = "scroll" },
      { t = "text", s = "la carne de gallina!" },
      { t = "eos" },
    },
  ["g3:081870cc"] = {
      { t = "text", s = "LIZ: ¡JOEL me gusta hasta cuando" },
      { t = "nl" },
      { t = "text", s = "pierde!" },
      { t = "eos" },
    },
  ["g3:081870f9"] = {
      { t = "text", s = "LIZ: Lo siento, pero no hay nadie" },
      { t = "nl" },
      { t = "text", s = "como JOEL." },
      { t = "eos" },
    },
  ["g3:08187120"] = {
      { t = "text", s = "LIZ: ¿No tienes dos POKéMON?" },
      { t = "para" },
      { t = "text", s = "¿Y no os sentís solos?" },
      { t = "eos" },
    },
  ["g3:0818717e"] = {
      { t = "text", s = "¡No compensa luchar con niños!" },
      { t = "eos" },
    },
  ["g3:081871ae"] = {
      { t = "text", s = "¡Qué chasco!" },
      { t = "eos" },
    },
  ["g3:081871ba"] = {
      { t = "text", s = "¡Por el CAMINO de BICIS" },
      { t = "nl" },
      { t = "text", s = "hay cosas estupendas!" },
      { t = "para" },
      { t = "text", s = "¡Se puede ganar mucha pasta" },
      { t = "nl" },
      { t = "text", s = "vendiendo lo que se encuentra!" },
      { t = "eos" },
    },
  ["g3:08187228"] = {
      { t = "text", s = "¿Y tú qué quieres?" },
      { t = "eos" },
    },
  ["g3:08187254"] = {
      { t = "text", s = "¡Uuuu!" },
      { t = "eos" },
    },
  ["g3:0818725a"] = {
      { t = "text", s = "¡Podría echarte de aquí de" },
      { t = "nl" },
      { t = "text", s = "un barrigazo!" },
      { t = "eos" },
    },
  ["g3:0818727d"] = {
      { t = "text", s = "¿Te diriges a CIUDAD FUCSIA?" },
      { t = "eos" },
    },
  ["g3:08187295"] = {
      { t = "text", s = "¡Destrozado y vencido!" },
      { t = "eos" },
    },
  ["g3:081872a5"] = {
      { t = "text", s = "Me gusta pedalear cuesta abajo." },
      { t = "eos" },
    },
  ["g3:081872bd"] = {
      { t = "text", s = "¡Somos los MOTORISTAS!" },
      { t = "nl" },
      { t = "text", s = "¡Las estrellas de la autopista!" },
      { t = "eos" },
    },
  ["g3:081872e3"] = {
      { t = "text", s = "¡Qué trompazo!" },
      { t = "eos" },
    },
  ["g3:081872eb"] = {
      { t = "text", s = "¿Vas en busca de aventuras?" },
      { t = "eos" },
    },
  ["g3:0818730a"] = {
      { t = "text", s = "¡Deja que VOLTORB te dé un poco" },
      { t = "nl" },
      { t = "text", s = "de su energía!" },
      { t = "eos" },
    },
  ["g3:08187325"] = {
      { t = "text", s = "¡Qué bajón!" },
      { t = "eos" },
    },
  ["g3:08187333"] = {
      { t = "text", s = "¡Atrapé mis VOLTORB en la" },
      { t = "nl" },
      { t = "text", s = "CENTRAL de ENERGÍA abandonada!" },
      { t = "eos" },
    },
  ["g3:08187362"] = {
      { t = "text", s = "¡Mi POKéMON no evoluciona!" },
      { t = "nl" },
      { t = "text", s = "¿Por qué será?" },
      { t = "eos" },
    },
  ["g3:08187395"] = {
      { t = "text", s = "¡Tú tienes la culpa!" },
      { t = "eos" },
    },
  ["g3:0818739f"] = {
      { t = "text", s = "Puede que ciertos POKéMON" },
      { t = "nl" },
      { t = "text", s = "necesiten PIEDRAS para" },
      { t = "scroll" },
      { t = "text", s = "evolucionar." },
      { t = "eos" },
    },
  ["g3:081873d1"] = {
      { t = "text", s = "¡Necesito un poco de ejercicio!" },
      { t = "eos" },
    },
  ["g3:081873eb"] = {
      { t = "text", s = "¡Ufff!" },
      { t = "nl" },
      { t = "text", s = "¡Qué buen entrenamiento!" },
      { t = "eos" },
    },
  ["g3:081873ff"] = {
      { t = "text", s = "¡Seguro que he perdido peso!" },
      { t = "eos" },
    },
  ["g3:0818741d"] = {
      { t = "text", s = "¡Sé rebelde!" },
      { t = "eos" },
    },
  ["g3:08187429"] = {
      { t = "text", s = "¡Aaaargh!" },
      { t = "eos" },
    },
  ["g3:08187432"] = {
      { t = "text", s = "¡Prepárate para luchar" },
      { t = "nl" },
      { t = "text", s = "por tus ideas!" },
      { t = "eos" },
    },
  ["g3:08187456"] = {
      { t = "text", s = "¡Bonita BICI!" },
      { t = "nl" },
      { t = "text", s = "¿Cómo se conduce?" },
      { t = "eos" },
    },
  ["g3:08187472"] = {
      { t = "text", s = "¡Estoy acabado!" },
      { t = "eos" },
    },
  ["g3:08187479"] = {
      { t = "text", s = "¡La pendiente dificulta" },
      { t = "nl" },
      { t = "text", s = "la conducción!" },
      { t = "eos" },
    },
  ["g3:0818749b"] = {
      { t = "text", s = "¡Lárgate!" },
      { t = "nl" },
      { t = "text", s = "¡Estoy agotado!" },
      { t = "eos" },
    },
  ["g3:081874b6"] = {
      { t = "text", s = "¿Te has quedado a gusto?" },
      { t = "eos" },
    },
  ["g3:081874c9"] = {
      { t = "text", s = "¡Tengo que recuperar sueño" },
      { t = "nl" },
      { t = "text", s = "atrasado!" },
      { t = "eos" },
    },
  ["g3:081874e4"] = {
      { t = "text", s = "¡Aviso!" },
      { t = "para" },
      { t = "text", s = "¡Ojo con las cosas que hay" },
      { t = "nl" },
      { t = "text", s = "por el suelo!" },
      { t = "eos" },
    },
  ["g3:08187512"] = {
      { t = "text", s = "PISTAS ENTRENADOR" },
      { t = "para" },
      { t = "text", s = "Todo POKéMON es único." },
      { t = "para" },
      { t = "text", s = "Hasta los POKéMON del mismo tipo" },
      { t = "nl" },
      { t = "text", s = "y nivel crecen a diferente ritmo." },
      { t = "eos" },
    },
  ["g3:0818757b"] = {
      { t = "text", s = "PISTAS ENTRENADOR" },
      { t = "para" },
      { t = "text", s = "Pulsa el Botón B para no moverte" },
      { t = "nl" },
      { t = "text", s = "sobre una pendiente." },
      { t = "eos" },
    },
  ["g3:081875be"] = {
      { t = "text", s = "RUTA 17:" },
      { t = "nl" },
      { t = "text", s = "CIUDAD AZULONA - CIUDAD FUCSIA" },
      { t = "eos" },
    },
  ["g3:081875e3"] = {
      { t = "text", s = "¡Aviso!" },
      { t = "para" },
      { t = "text", s = "¡No tires el juego, mejor tira" },
      { t = "nl" },
      { t = "text", s = "POKé BALLS!" },
      { t = "eos" },
    },
  ["g3:08187622"] = {
      { t = "text", s = "CAMINO DE BICIS" },
      { t = "nl" },
      { t = "text", s = "¡La pendiente termina aquí!" },
      { t = "eos" },
    },
  ["g3:08187640"] = {
      { t = "text", s = "Compruebo siempre las zonas de" },
      { t = "nl" },
      { t = "text", s = "hierba en busca de nuevos POKéMON." },
      { t = "eos" },
    },
  ["g3:08187672"] = {
      { t = "text", s = "¡Tch!" },
      { t = "eos" },
    },
  ["g3:08187677"] = {
      { t = "text", s = "¡Ojalá tuviera una BICICLETA!" },
      { t = "eos" },
    },
  ["g3:0818768c"] = {
      { t = "text", s = "¡Cucu, cucu!" },
      { t = "nl" },
      { t = "text", s = "¿Te gusta el reclamo de mi pájaro?" },
      { t = "eos" },
    },
  ["g3:081876b3"] = {
