      { t = "nl" },
      { t = "text", s = "los fines de semana!" },
      { t = "eos" },
    },
  ["g3:08187704"] = {
      { t = "text", s = "¡Es mi césped!" },
      { t = "nl" },
      { t = "text", s = "¡Fuera de aquí!" },
      { t = "eos" },
    },
  ["g3:08187726"] = {
      { t = "text", s = "¡Qué rabia!" },
      { t = "eos" },
    },
  ["g3:0818772c"] = {
      { t = "text", s = "¡Es mi zona preferida para atrapar" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:08187757"] = {
