      { t = "nl" },
      { t = "text", s = "de nadar!" },
      { t = "eos" },
    },
  ["g3:081877df"] = {
      { t = "text", s = "¡Ahora es cuando me encuentro" },
      { t = "nl" },
      { t = "text", s = "en forma!" },
      { t = "eos" },
    },
  ["g3:081877ee"] = {
      { t = "text", s = "¡Gracias!" },
      { t = "nl" },
      { t = "text", s = "¡Ya puedo nadar!" },
      { t = "eos" },
    },
  ["g3:08187811"] = {
      { t = "text", s = "¡Alto!" },
      { t = "nl" },
      { t = "text", s = "¡Te va a dar algo!" },
      { t = "eos" },
    },
  ["g3:0818783e"] = {
      { t = "text", s = "¡¡Auuu!!" },
      { t = "nl" },
      { t = "text", s = "¡Cómo me has dejado!" },
      { t = "eos" },
    },
  ["g3:08187852"] = {
      { t = "text", s = "¡Cuidado con TENTACOOL!" },
      { t = "nl" },
      { t = "text", s = "¡Como te pique, no veas!" },
      { t = "eos" },
    },
  ["g3:08187884"] = {
      { t = "text", s = "¡Me gusta nadar!" },
      { t = "nl" },
      { t = "text", s = "¿Y a ti?" },
      { t = "eos" },
    },
  ["g3:081878a5"] = {
      { t = "text", s = "¡Vaya planchazo!" },
      { t = "eos" },
    },
  ["g3:081878b1"] = {
      { t = "text", s = "¡Puedo ganar a los POKéMON" },
      { t = "nl" },
      { t = "text", s = "nadando!" },
      { t = "eos" },
    },
  ["g3:081878dd"] = {
      { t = "text", s = "¿Qué habrá más allá del horizonte?" },
      { t = "eos" },
    },
  ["g3:081878f8"] = {
      { t = "text", s = "¡Glup!" },
      { t = "eos" },
    },
  ["g3:081878fe"] = {
      { t = "text", s = "¡Veo un par de islas!" },
      { t = "eos" },
    },
  ["g3:08187925"] = {
      { t = "text", s = "¡He buceado en busca de POKéMON," },
      { t = "nl" },
      { t = "text", s = "pero no he visto nada!" },
      { t = "eos" },
    },
  ["g3:08187955"] = {
      { t = "text", s = "¡Socorro!" },
      { t = "eos" },
    },
  ["g3:0818795b"] = {
      { t = "text", s = "¡Tienes que pescar a los POKéMON" },
      { t = "nl" },
      { t = "text", s = "del mar!" },
      { t = "eos" },
    },
  ["g3:08187985"] = {
      { t = "text", s = "¡Miro al mar para olvidar!" },
      { t = "eos" },
    },
  ["g3:081879c3"] = {
      { t = "text", s = "¡Oooooh!" },
      { t = "nl" },
      { t = "text", s = "¡Qué humillación!" },
      { t = "eos" },
    },
  ["g3:081879d3"] = {
      { t = "text", s = "¡Miro al mar para olvidar!" },
      { t = "eos" },
    },
  ["g3:08187a11"] = {
      { t = "text", s = "¡Qué POKéMON tan guay!" },
      { t = "nl" },
      { t = "text", s = "¿Me lo darás si gano?" },
      { t = "eos" },
    },
  ["g3:08187a44"] = {
      { t = "text", s = "¡Oh! ¡He perdido!" },
      { t = "eos" },
    },
  ["g3:08187a50"] = {
      { t = "text", s = "Queda un largo camino hasta" },
      { t = "nl" },
      { t = "text", s = "las ISLAS ESPUMA..." },
      { t = "para" },
      { t = "text", s = "Yo quiero volver a FUCSIA..." },
      { t = "eos" },
    },
  ["g3:08187a9e"] = {
      { t = "text", s = "¡Nadar es genial! ¡Pero no me" },
      { t = "nl" },
      { t = "text", s = "gusta quemarme al sol!" },
      { t = "eos" },
    },
  ["g3:08187ac1"] = {
      { t = "text", s = "¡Qué horror!" },
      { t = "eos" },
    },
  ["g3:08187aca"] = {
      { t = "text", s = "Mi novio quería nadar hasta" },
      { t = "nl" },
      { t = "text", s = "las ISLAS ESPUMA." },
      { t = "eos" },
    },
  ["g3:08187afa"] = {
      { t = "text", s = "¡Estas aguas son traicioneras!" },
      { t = "eos" },
    },
  ["g3:08187b25"] = {
      { t = "text", s = "¡Qué peligro!" },
      { t = "eos" },
    },
  ["g3:08187b35"] = {
      { t = "text", s = "¡Me ha dado un calambre! ¡Glup!" },
      { t = "eos" },
    },
  ["g3:08187b5d"] = {
      { t = "text", s = "He venido nadando hasta aquí," },
      { t = "nl" },
      { t = "text", s = "pero ya me he cansado." },
      { t = "eos" },
    },
  ["g3:08187b85"] = {
      { t = "text", s = "Estoy agotada..." },
      { t = "eos" },
    },
  ["g3:08187b94"] = {
      { t = "text", s = "Si tuviera que montarme en un" },
      { t = "nl" },
      { t = "text", s = "POKéMON para surcar el mar," },
      { t = "scroll" },
      { t = "text", s = "elegiría a LAPRAS." },
      { t = "para" },
      { t = "text", s = "LAPRAS es enorme, si te subes" },
      { t = "nl" },
      { t = "text", s = "encima, seguro que no te mojas." },
      { t = "eos" },
    },
  ["g3:08187c06"] = {
      { t = "text", s = "RUTA MARINA 19:" },
      { t = "nl" },
      { t = "text", s = "CIUDAD FUCSIA - ISLAS ESPUMA" },
      { t = "eos" },
    },
  ["g3:08187c32"] = {
      { t = "text", s = "CATI: Yo cuido de mi hermano." },
      { t = "nl" },
      { t = "text", s = "Acaba de hacerse ENTRENADOR." },
      { t = "eos" },
    },
  ["g3:08187c6f"] = {
      { t = "text", s = "CATI: ¡Ésa no es forma de tratar" },
      { t = "nl" },
      { t = "text", s = "a mi hermanito!" },
      { t = "eos" },
    },
  ["g3:08187c9e"] = {
      { t = "text", s = "CATI: ¿Tienes un hermano pequeño?" },
      { t = "para" },
      { t = "text", s = "Espero que le enseñes cosas." },
      { t = "eos" },
    },
  ["g3:08187cf2"] = {
      { t = "text", s = "CATI: A mi hermano y a mí nos" },
      { t = "nl" },
      { t = "text", s = "gustaría luchar contigo." },
      { t = "para" },
      { t = "text", s = "¿Tienes dos POKéMON?" },
      { t = "eos" },
    },
  ["g3:08187d45"] = {
      { t = "text", s = "TEC: Mi hermana mayor me ha" },
      { t = "nl" },
      { t = "text", s = "enseñado a nadar y a entrenar" },
      { t = "scroll" },
      { t = "text", s = "POKéMON." },
      { t = "eos" },
    },
  ["g3:08187d7e"] = {
      { t = "text", s = "TEC: ¡Hala, alguien más fuerte" },
      { t = "nl" },
      { t = "text", s = "que mi hermana!" },
      { t = "eos" },
    },
  ["g3:08187dad"] = {
      { t = "text", s = "TEC: ¡Mi hermana mayor es muy" },
      { t = "nl" },
      { t = "text", s = "fuerte y simpática! ¡Es guay!" },
      { t = "eos" },
    },
  ["g3:08187de8"] = {
      { t = "text", s = "TEC: Si no es con mi hermana," },
      { t = "nl" },
      { t = "text", s = "no lucharé contigo." },
      { t = "para" },
      { t = "text", s = "Además, necesitas dos POKéMON." },
      { t = "eos" },
    },
  ["g3:08187e40"] = {
      { t = "text", s = "El agua es poco profunda aquí." },
      { t = "nl" },
      { t = "text", s = "Hay mucha gente nadando." },
      { t = "eos" },
    },
  ["g3:08187e7b"] = {
      { t = "text", s = "¡Splash!" },
      { t = "eos" },
    },
  ["g3:08187e83"] = {
      { t = "text", s = "¡Ojalá pudiera subirme a mi" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:08187ebb"] = {
      { t = "text", s = "¡Las ISLAS ESPUMA son una fácil" },
      { t = "nl" },
      { t = "text", s = "salida!" },
      { t = "eos" },
    },
  ["g3:08187eed"] = {
      { t = "text", s = "¡Déjalo ya!" },
      { t = "eos" },
    },
  ["g3:08187ef6"] = {
      { t = "text", s = "Hay una enorme caverna debajo" },
      { t = "nl" },
      { t = "text", s = "de esta isla." },
      { t = "eos" },
    },
  ["g3:08187f24"] = {
      { t = "text", s = "¡Me gusta flotar en el agua" },
      { t = "nl" },
      { t = "text", s = "rodeada de peces!" },
      { t = "eos" },
    },
  ["g3:08187f5a"] = {
      { t = "text", s = "¡Auchh!" },
      { t = "eos" },
    },
  ["g3:08187f61"] = {
      { t = "text", s = "¿Quieres flotar conmigo?" },
      { t = "eos" },
    },
  ["g3:08187f78"] = {
      { t = "text", s = "¿También estás de vacaciones?" },
      { t = "eos" },
    },
  ["g3:08187f92"] = {
      { t = "text", s = "¡Qué insensible eres!" },
      { t = "eos" },
    },
  ["g3:08187fa3"] = {
      { t = "text", s = "¡Las ISLAS ESPUMA eran antes" },
      { t = "nl" },
      { t = "text", s = "una sola isla!" },
      { t = "eos" },
    },
  ["g3:08187fdb"] = {
      { t = "text", s = "¡Mira que cuerpazo tengo!" },
      { t = "eos" },
    },
  ["g3:08187ff7"] = {
      { t = "text", s = "¡Qué ridículo!" },
      { t = "eos" },
    },
  ["g3:08187ffe"] = {
      { t = "text", s = "¡No debería haber presumido tanto!" },
      { t = "eos" },
    },
  ["g3:0818802e"] = {
      { t = "text", s = "¿Por qué te has subido a un" },
      { t = "nl" },
      { t = "text", s = "POKéMON? ¿No sabes nadar?" },
      { t = "eos" },
    },
  ["g3:0818805c"] = {
      { t = "text", s = "¡Auch!" },
      { t = "nl" },
      { t = "text", s = "¡Qué fracaso!" },
      { t = "eos" },
    },
  ["g3:0818806d"] = {
      { t = "text", s = "¡Subirse a un POKéMON es muy" },
      { t = "nl" },
      { t = "text", s = "divertido!" },
      { t = "eos" },
    },
  ["g3:0818808e"] = {
      { t = "text", s = "¡He venido sobre uno de mis" },
      { t = "nl" },
      { t = "text", s = "pájaros POKéMON!" },
      { t = "eos" },
    },
  ["g3:081880ab"] = {
      { t = "text", s = "¡Oh, no!" },
      { t = "eos" },
    },
  ["g3:081880c8"] = {
      { t = "text", s = "¡Mis pájaros están hechos polvo" },
      { t = "nl" },
      { t = "text", s = "para VOLAR de nuevo!" },
      { t = "eos" },
    },
  ["g3:081880f8"] = {
      { t = "text", s = "¡Mi novio me dio unas perlas" },
      { t = "nl" },
      { t = "text", s = "muy grandes!" },
      { t = "eos" },
    },
  ["g3:08188119"] = {
      { t = "text", s = "¡Ni te acerques a mis perlas!" },
      { t = "eos" },
    },
  ["g3:08188139"] = {
      { t = "text", s = "¿Crecerán más mis perlas dentro" },
      { t = "nl" },
      { t = "text", s = "de un CLOYSTER?" },
      { t = "eos" },
    },
  ["g3:08188165"] = {
      { t = "text", s = "¡Vengo nadando desde ISLA" },
      { t = "nl" },
      { t = "text", s = "CANELA! ¡Qué paliza!" },
      { t = "eos" },
    },
  ["g3:081881a3"] = {
      { t = "text", s = "¡Estoy tan decepcionada!" },
      { t = "eos" },
    },
  ["g3:081881b8"] = {
      { t = "text", s = "¡Los POKéMON invadieron una casa" },
      { t = "nl" },
      { t = "text", s = "abandonada en ISLA CANELA!" },
      { t = "para" },
      { t = "text", s = "Es la que llaman MANSIÓN" },
      { t = "nl" },
      { t = "text", s = "POKéMON." },
      { t = "eos" },
    },
  ["g3:08188218"] = {
      { t = "text", s = "En ISLA CANELA, al oeste, hay" },
      { t = "nl" },
      { t = "text", s = "un LABORATORIO POKéMON." },
      { t = "para" },
      { t = "text", s = "Mi papi trabaja allí." },
      { t = "eos" },
    },
  ["g3:0818825c"] = {
      { t = "text", s = "¡Espera!" },
      { t = "nl" },
      { t = "text", s = "¡Vas demasiado deprisa!" },
      { t = "eos" },
    },
  ["g3:0818827b"] = {
      { t = "text", s = "¡ISLA CANELA es volcánica!" },
      { t = "para" },
      { t = "text", s = "Dicen que surgió tras la erupción" },
      { t = "nl" },
      { t = "text", s = "de un volcán." },
      { t = "eos" },
    },
  ["g3:081882d1"] = {
      { t = "text", s = "ISLAS ESPUMA" },
      { t = "eos" },
    },
  ["g3:081882e1"] = {
      { t = "text", s = "Por aquí hay muchos ENTRENADORES" },
      { t = "nl" },
      { t = "text", s = "fuertes y POKéMON del tipo AGUA." },
      { t = "para" },
      { t = "text", s = "Dicen que MISTY, del GIMNASIO" },
      { t = "nl" },
      { t = "text", s = "de CELESTE, se entrena por aquí." },
      { t = "eos" },
    },
  ["g3:0818835a"] = {
      { t = "text", s = "¿Quieres saber si los peces pican?" },
      { t = "eos" },
    },
  ["g3:08188383"] = {
      { t = "text", s = "¡Vale, vale!" },
      { t = "eos" },
    },
  ["g3:08188389"] = {
      { t = "text", s = "¡No puedo pescar nada bueno!" },
      { t = "nl" },
      { t = "text", s = "¡No hay ni un POKéMON bueno!" },
      { t = "eos" },
    },
  ["g3:081883c6"] = {
      { t = "text", s = "¡Tengo una gran red!" },
      { t = "nl" },
      { t = "text", s = "¿Quieres probarla?" },
      { t = "eos" },
    },
  ["g3:081883e9"] = {
      { t = "text", s = "¡MAGIKARP, qué bochorno!" },
      { t = "eos" },
    },
  ["g3:0818841d"] = {
      { t = "text", s = "¡Se ve que sólo pesco MAGIKARP!" },
      { t = "eos" },
    },
  ["g3:0818843c"] = {
      { t = "text", s = "¡El mar limpia mi cuerpo y mi" },
      { t = "nl" },
      { t = "text", s = "alma!" },
      { t = "eos" },
    },
  ["g3:0818845f"] = {
      { t = "text", s = "¡Ayah!" },
      { t = "eos" },
    },
  ["g3:08188465"] = {
      { t = "text", s = "¡A mí también me gusta la montaña!" },
      { t = "eos" },
    },
  ["g3:081884d4"] = {
      { t = "text", s = "¡He conseguido a mi POKéMON" },
      { t = "nl" },
      { t = "text", s = "en el mar, y aquí lo entreno!" },
      { t = "eos" },
    },
  ["g3:081884f0"] = {
      { t = "text", s = "¡Splash!" },
      { t = "eos" },
    },
  ["g3:081884ff"] = {
      { t = "text", s = "¿Dónde atrapaste tus POKéMON?" },
      { t = "eos" },
    },
  ["g3:0818851f"] = {
      { t = "text", s = "¡Ahora estoy en un encuentro" },
      { t = "nl" },
      { t = "text", s = "de triatlón!" },
      { t = "eos" },
    },
  ["g3:08188543"] = {
      { t = "text", s = "Ufff..." },
      { t = "nl" },
      { t = "text", s = "Ufff... Ufff..." },
      { t = "eos" },
    },
  ["g3:08188555"] = {
      { t = "text", s = "¡Me has ganado! ¡Pero aún falta" },
      { t = "nl" },
      { t = "text", s = "el ciclismo y la maratón!" },
      { t = "eos" },
    },
  ["g3:08188592"] = {
      { t = "text", s = "¡Ah!" },
      { t = "nl" },
      { t = "text", s = "¡Siente el sol y el viento!" },
      { t = "eos" },
    },
  ["g3:081885b2"] = {
      { t = "text", s = "¡Auuu!" },
      { t = "nl" },
      { t = "text", s = "¡He perdido!" },
      { t = "eos" },
    },
  ["g3:081885bf"] = {
      { t = "text", s = "¡Estoy totalmente quemado!" },
      { t = "eos" },
    },
  ["g3:081885d8"] = {
      { t = "text", s = "¡Eh!" },
      { t = "nl" },
      { t = "text", s = "¡No asustes a los peces!" },
      { t = "eos" },
    },
  ["g3:081885f8"] = {
      { t = "text", s = "¡Perdona!" },
      { t = "nl" },
      { t = "text", s = "¡No lo hice adrede!" },
      { t = "eos" },
    },
  ["g3:08188632"] = {
      { t = "text", s = "¡Estaba enfadado porque no" },
      { t = "nl" },
      { t = "text", s = "había pescado nada!" },
      { t = "eos" },
    },
  ["g3:0818868c"] = {
      { t = "text", s = "¡Quédate conmigo hasta que lo" },
      { t = "nl" },
      { t = "text", s = "consiga!" },
      { t = "eos" },
    },
  ["g3:081886ae"] = {
      { t = "text", s = "Qué forma de matar el tiempo..." },
      { t = "eos" },
    },
  ["g3:081886c5"] = {
      { t = "text", s = "¡Eh!" },
      { t = "nl" },
      { t = "text", s = "¡Algo ha picado! ¡Sí!" },
      { t = "eos" },
    },
  ["g3:081886e2"] = {
      { t = "text", s = "ÍA: ¿Cómo, que quieres luchar?" },
      { t = "nl" },
      { t = "text", s = "IGOR, ¿cómo lo ves?" },
      { t = "eos" },
    },
  ["g3:08188712"] = {
      { t = "text", s = "ÍA: ¿Eso es lo que querías," },
      { t = "nl" },
      { t = "text", s = "que perdiéramos?" },
      { t = "eos" },
    },
  ["g3:08188734"] = {
      { t = "text", s = "ÍA: Estoy cansada, ¿nos vamos ya" },
      { t = "nl" },
      { t = "text", s = "a casa?" },
      { t = "eos" },
    },
  ["g3:0818875e"] = {
      { t = "text", s = "ÍA: ¿Luchar? Con sólo un POKéMON" },
      { t = "nl" },
      { t = "text", s = "no nos vamos a tomar la molestia." },
      { t = "eos" },
    },
  ["g3:081887b4"] = {
      { t = "text", s = "IGOR: Mi hermana no se cansa" },
      { t = "nl" },
      { t = "text", s = "de hacer ejercicio, por eso viene." },
