      { t = "text", s = "PÁJARO." },
      { t = "para" },
      { t = "text", s = "Lo mejor que tienen los pájaros" },
      { t = "nl" },
      { t = "text", s = "deben de ser las plumas." },
      { t = "eos" },
    },
  ["g3:0818afcc"] = {
