      { t = "para" },
      { t = "text", s = "“Aquí yace TECTONIX”, pone" },
      { t = "nl" },
      { t = "text", s = "en una piedra." },
      { t = "eos" },
    },
  ["g3:0818b35a"] = {
      { t = "text", s = "Por aquí no hay ni un sólo" },
      { t = "nl" },
      { t = "text", s = "POKéMON raro. ¡Ni uno!" },
      { t = "para" },
      { t = "text", s = "¡Estoy hasta el gorro de buscar!" },
