      { t = "text", s = "¡Te ha tocado pagar el mosqueo," },
      { t = "scroll" },
      { t = "text", s = "lo siento!" },
      { t = "eos" },
    },
  ["g3:0818b3c2"] = {
      { t = "text", s = "¡¿Qué?!" },
      { t = "eos" },
    },
  ["g3:0818b3c8"] = {
