      { t = "text", s = "¡Igual la cosa cambia si luchamos!" },
      { t = "eos" },
    },
  ["g3:0818b43b"] = {
      { t = "text", s = "Nada, hoy no es mi día." },
      { t = "eos" },
    },
  ["g3:0818b451"] = {
      { t = "text", s = "¡Pero es que no puedo volver" },
      { t = "nl" },
      { t = "text", s = "a casa con las manos vacías!" },
      { t = "eos" },
    },
  ["g3:0818b48f"] = {
      { t = "text", s = "Ufff... Ufff..." },
      { t = "para" },
      { t = "text", s = "Vengo nadando desde el PUERTO" },
      { t = "nl" },
      { t = "text", s = "de ISLA EXTA sin parar." },
      { t = "eos" },
    },
  ["g3:0818b4c5"] = {
      { t = "text", s = "Agggg..." },
