      { t = "text", s = "no me vea nadie." },
      { t = "eos" },
    },
  ["g3:0818b988"] = {
      { t = "text", s = "No me habrá visto nadie, ¿no?" },
      { t = "eos" },
    },
  ["g3:0818b9a5"] = {
      { t = "text", s = "Como artista, no me gusta" },
      { t = "nl" },
      { t = "text", s = "que nadie me vea cuando ensayo." },
      { t = "eos" },
    },
  ["g3:0818b9ec"] = {
