      { t = "text", s = "la gente que hace natación" },
      { t = "scroll" },
      { t = "text", s = "como yo?" },
      { t = "para" },
      { t = "text", s = "¡No fastidies!" },
      { t = "eos" },
    },
  ["g3:0818ba47"] = {
      { t = "text", s = "¡Vale, me queda claro!" },
      { t = "eos" },
    },
  ["g3:0818ba57"] = {
