      { t = "nl" },
      { t = "text", s = "Nos encanta luchar juntas." },
      { t = "eos" },
    },
  ["g3:0818bc5a"] = {
      { t = "text", s = "MÍA: ¡Queridos POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¡Vamos a luchar!" },
      { t = "eos" },
    },
  ["g3:0818bc84"] = {
      { t = "text", s = "MÍA: ¡Hay que ver cómo eres!" },
      { t = "nl" },
      { t = "text", s = "¡No está bien que ganes!" },
      { t = "eos" },
    },
  ["g3:0818bcae"] = {
