      { t = "text", s = "¿Y no te da pena?" },
      { t = "eos" },
    },
  ["g3:0818bd0c"] = {
      { t = "text", s = "Se busca el cuerno perdido." },
      { t = "eos" },
    },
  ["g3:0818bd27"] = {
