      { t = "nl" },
      { t = "text", s = "¿Quieres examinarla un poco?" },
      { t = "eos" },
    },
  ["g3:0818bdf9"] = {
      { t = "player" },
      { t = "text", s = " dejó tranquila la puerta." },
