      { t = "text", s = "tengo reflejos..." },
      { t = "eos" },
    },
  ["g3:0818bf6c"] = {
      { t = "text", s = "Hay varias ruinas en ARCHI7." },
      { t = "para" },
      { t = "text", s = "La mayoría datan de tiempos" },
      { t = "nl" },
      { t = "text", s = "inmemoriales." },
      { t = "eos" },
    },
  ["g3:0818bfc5"] = {
      { t = "text", s = "Dicen que hay misteriosas piedras" },
      { t = "nl" },
      { t = "text", s = "en esta isla." },
      { t = "para" },
      { t = "text", s = "Supongo que tendrán algo que ver" },
      { t = "nl" },
      { t = "text", s = "con las ruinas de aquí." },
      { t = "eos" },
    },
  ["g3:0818c03b"] = {
      { t = "text", s = "Eh... muy interesante." },
      { t = "eos" },
    },
  ["g3:0818c04c"] = {
      { t = "text", s = "Las ruinas de ahí..." },
      { t = "para" },
      { t = "text", s = "Son rarísimas, yo no he conseguido" },
      { t = "nl" },
      { t = "text", s = "entrar todavía." },
      { t = "eos" },
    },
  ["g3:0818c09c"] = {
      { t = "text", s = "¿Luchar contigo?" },
      { t = "nl" },
      { t = "text", s = "¡Ahora mismo!" },
      { t = "eos" },
    },
  ["g3:0818c0bb"] = {
      { t = "text", s = "No soporto el sabor de la derrota" },
      { t = "nl" },
      { t = "text", s = "ante ti..." },
      { t = "eos" },
    },
  ["g3:0818c0ea"] = {
      { t = "text", s = "Deberías hacer escalada." },
      { t = "eos" },
    },
  ["g3:0818c10a"] = {
      { t = "text", s = "Yo me conozco bien toda esta" },
      { t = "nl" },
      { t = "text", s = "zona." },
      { t = "eos" },
    },
  ["g3:0818c140"] = {
      { t = "text", s = "Tampoco es para ponerse así." },
      { t = "nl" },
      { t = "text", s = "Puedes preguntarme lo que quieras." },
      { t = "eos" },
    },
  ["g3:0818c17a"] = {
      { t = "text", s = "La entrada a las ruinas..." },
      { t = "nl" },
      { t = "text", s = "Tiene unos dibujos extrañísimos" },
      { t = "scroll" },
      { t = "text", s = "grabados." },
      { t = "para" },
      { t = "text", s = "Y no tengo ni idea de lo que" },
      { t = "nl" },
      { t = "text", s = "significan." },
      { t = "eos" },
    },
  ["g3:0818c1ed"] = {
      { t = "text", s = "He notado que te acercabas." },
      { t = "eos" },
    },
  ["g3:0818c205"] = {
      { t = "text", s = "Me rindo..." },
      { t = "eos" },
    },
  ["g3:0818c20e"] = {
      { t = "text", s = "Siento que te vas a encontrar" },
      { t = "nl" },
      { t = "text", s = "con mucha gente." },
      { t = "para" },
      { t = "text", s = "Establecerás cierta conexión" },
      { t = "nl" },
      { t = "text", s = "mediante una extraña fuerza." },
      { t = "eos" },
    },
  ["g3:0818c283"] = {
      { t = "text", s = "En alguna parte de esta isla," },
      { t = "nl" },
      { t = "text", s = "hay extraños POKéMON durmiendo." },
      { t = "eos" },
    },
  ["g3:0818c2bc"] = {
      { t = "text", s = "¡Tú sí que sabes entrenar POKéMON!" },
      { t = "eos" },
    },
  ["g3:0818c2d5"] = {
      { t = "text", s = "En alguna parte de esta isla," },
