      { t = "text", s = "hay extraños POKéMON durmiendo." },
      { t = "para" },
      { t = "text", s = "¿Te estarán esperando?" },
      { t = "eos" },
    },
  ["g3:0818c338"] = {
      { t = "text", s = "ENTRADA A LA TORRE DESAFÍO" },
      { t = "nl" },
      { t = "text", s = "¡A por todas, ENTRENADORES!" },
      { t = "eos" },
    },
  ["g3:0818c370"] = {
      { t = "text", s = "HACIA LA TORRE DESAFÍO" },
      { t = "eos" },
    },
  ["g3:0818c3bc"] = {
      { t = "text", s = "¡Voy a acabar contigo en un abrir" },
      { t = "nl" },
      { t = "text", s = "y cerrar de ojos!" },
      { t = "eos" },
    },
  ["g3:0818c3e7"] = {
      { t = "text", s = "¡Ufff... demasiado para mí!" },
      { t = "eos" },
    },
  ["g3:0818c3ff"] = {
      { t = "text", s = "¿Cómo? ¿Que las apariencias" },
      { t = "nl" },
      { t = "text", s = "engañan?" },
      { t = "para" },
      { t = "text", s = "¡Eh, es parte de mi estrategia!" },
      { t = "eos" },
    },
  ["g3:0818c44b"] = {
      { t = "text", s = "¡Hola, cara de bola!" },
      { t = "nl" },
      { t = "text", s = "¿Eres de mi club de fans?" },
      { t = "eos" },
    },
  ["g3:0818c473"] = {
      { t = "text", s = "O sea, que de fan nada..." },
      { t = "para" },
      { t = "text", s = "Pues ¿qué le vamos a hacer?" },
      { t = "nl" },
      { t = "text", s = "¿Y si te canto un poco?" },
      { t = "eos" },
    },
  ["g3:0818c4ba"] = {
      { t = "text", s = "Oye el boom, boom..." },
      { t = "para" },
      { t = "text", s = "Oye el boom, boom, boom, de mis" },
      { t = "nl" },
      { t = "text", s = "POKéMON, ven y dime tú, no me" },
      { t = "scroll" },
      { t = "text", s = "digas no..." },
      { t = "eos" },
    },
  ["g3:0818c500"] = {
      { t = "text", s = "Esta isla tiene una extensión muy" },
      { t = "nl" },
      { t = "text", s = "particular, no es fácil patrullar." },
      { t = "eos" },
    },
  ["g3:0818c543"] = {
      { t = "text", s = "Vaya..." },
      { t = "eos" },
    },
  ["g3:0818c54b"] = {
      { t = "text", s = "Los ENTRENADORES de ciudad," },
      { t = "nl" },
      { t = "text", s = "como tú, deben de ser fuertes." },
      { t = "para" },
      { t = "text", s = "Tú irás a la TORRE, ¿no?" },
      { t = "eos" },
    },
  ["g3:0818c5aa"] = {
      { t = "text", s = "¡La gente que se pasa con los" },
      { t = "nl" },
      { t = "text", s = "POKéMON se las ve conmigo!" },
      { t = "eos" },
    },
  ["g3:0818c5cd"] = {
      { t = "text", s = "¡Tú te portas como debe ser!" },
      { t = "eos" },
    },
  ["g3:0818c5f5"] = {
      { t = "text", s = "Si tratas a los POKéMON con" },
      { t = "nl" },
      { t = "text", s = "amabilidad, reaccionarán bien." },
      { t = "eos" },
    },
  ["g3:0818c632"] = {
      { t = "text", s = "ELE: Yo formo equipo con RUS" },
      { t = "nl" },
      { t = "text", s = "para luchar." },
      { t = "eos" },
    },
  ["g3:0818c662"] = {
      { t = "text", s = "ELE: Pues hemos perdido RUS" },
      { t = "nl" },
      { t = "text", s = "y yo, je." },
      { t = "eos" },
    },
  ["g3:0818c683"] = {
      { t = "text", s = "ELE: Tengo que entrenarme más con" },
      { t = "nl" },
      { t = "text", s = "RUS." },
      { t = "eos" },
    },
  ["g3:0818c6ab"] = {
      { t = "text", s = "ELE: Junto a RUS, me gustaría" },
      { t = "nl" },
      { t = "text", s = "luchar contra ti." },
      { t = "para" },
      { t = "text", s = "¡Pero necesitas al menos dos" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:0818c700"] = {
      { t = "text", s = "RUS: Cuando estoy con ELE," },
      { t = "nl" },
      { t = "text", s = "creo que no voy a perder nunca." },
      { t = "eos" },
    },
  ["g3:0818c73b"] = {
      { t = "text", s = "RUS: Cuando estoy con ELE," },
      { t = "nl" },
      { t = "text", s = "no tengo sensación de derrota." },
      { t = "eos" },
    },
  ["g3:0818c773"] = {
      { t = "text", s = "RUS: Cuando estoy con ELE," },
      { t = "nl" },
      { t = "text", s = "me da igual ganar o perder." },
      { t = "para" },
      { t = "text", s = "¡Es una sensación inexplicable!" },
      { t = "eos" },
    },
  ["g3:0818c7bd"] = {
      { t = "text", s = "RUS: Si es junto a ELE," },
      { t = "nl" },
      { t = "text", s = "me encantará luchar contra ti." },
      { t = "para" },
      { t = "text", s = "¡Pero para eso, tendrás que tener" },
      { t = "nl" },
      { t = "text", s = "al menos dos POKéMON!" },
      { t = "eos" },
    },
  ["g3:0818c82d"] = {
      { t = "text", s = "ENTRADA AL CAÑÓN SÉTANO" },
      { t = "para" },
      { t = "text", s = "Se ruega a los ENTRENADORES" },
      { t = "nl" },
      { t = "text", s = "respetar la vegetación del CAÑÓN." },
      { t = "eos" },
    },
  ["g3:0818c887"] = {
      { t = "text", s = "¡Estoy realmente en forma!" },
      { t = "eos" },
    },
  ["g3:0818c8a6"] = {
      { t = "text", s = "¿Mmm?" },
      { t = "nl" },
      { t = "text", s = "Aquí hay algo que falla..." },
      { t = "eos" },
    },
  ["g3:0818c8c2"] = {
      { t = "text", s = "Así no puedo presentarme a la" },
      { t = "nl" },
      { t = "text", s = "TORRE DESAFÍO..." },
      { t = "eos" },
    },
  ["g3:0818c8fd"] = {
      { t = "text", s = "Da igual que tengas los POKéMON" },
      { t = "nl" },
      { t = "text", s = "más fuertes..." },
      { t = "para" },
      { t = "text", s = "¡Lo importante es saber cómo" },
      { t = "nl" },
      { t = "text", s = "tratarlos!" },
      { t = "eos" },
    },
  ["g3:0818c980"] = {
      { t = "text", s = "Sabes bien lo que haces..." },
      { t = "eos" },
    },
  ["g3:0818c999"] = {
      { t = "text", s = "Hay mucho ENTRENADOR por ahí" },
      { t = "nl" },
      { t = "text", s = "suelto con POKéMON increíbles y sin" },
      { t = "scroll" },
      { t = "text", s = "idea de cómo hay que tratarlos." },
      { t = "para" },
      { t = "text", s = "Antes de entrenar POKéMON," },
      { t = "nl" },
      { t = "text", s = "son los propios ENTRENADORES los" },
      { t = "scroll" },
      { t = "text", s = "que deben crecer como personas." },
      { t = "eos" },
    },
  ["g3:0818ca2f"] = {
      { t = "text", s = "Yo protejo el medio ambiente" },
      { t = "nl" },
      { t = "text", s = "y él me protege a mí." },
      { t = "eos" },
    },
  ["g3:0818ca6f"] = {
      { t = "text", s = "¡Buah, eres fuerte!" },
      { t = "nl" },
      { t = "text", s = "¿Y a mí quién me protege ahora?" },
      { t = "eos" },
    },
  ["g3:0818ca9c"] = {
      { t = "text", s = "Visto desde las estrellas, nuestro" },
      { t = "nl" },
      { t = "text", s = "planeta es un granito de arena." },
      { t = "para" },
      { t = "text", s = "Y debemos proteger ese granito" },
      { t = "nl" },
      { t = "text", s = "de arena por el bien de todos." },
      { t = "eos" },
    },
  ["g3:0818cb16"] = {
      { t = "text", s = "Tienes unos zapatos muy llamativos." },
      { t = "eos" },
    },
  ["g3:0818cb3e"] = {
      { t = "text", s = "¡Cualquiera diría que eres tan" },
      { t = "nl" },
      { t = "text", s = "fuerte! ¡No lo aparentas!" },
      { t = "eos" },
    },
  ["g3:0818cb6c"] = {
      { t = "text", s = "¿Te ha comprado tu mamá esas" },
      { t = "nl" },
      { t = "text", s = "DEPORTIVAS tan chulas?" },
      { t = "para" },
      { t = "text", s = "¡Debe de adorarte!" },
      { t = "eos" },
    },
  ["g3:0818cbb4"] = {
      { t = "text", s = "¡Pareces fuerte!" },
      { t = "nl" },
      { t = "text", s = "¡Vamos a luchar, anda!" },
      { t = "eos" },
    },
  ["g3:0818cbe0"] = {
      { t = "text", s = "¡Lo sabía!" },
      { t = "nl" },
      { t = "text", s = "¡Sabía que eras increíble!" },
      { t = "eos" },
    },
  ["g3:0818cc09"] = {
      { t = "text", s = "La forma de luchar que tienes" },
      { t = "nl" },
      { t = "text", s = "dice mucho de ti." },
      { t = "para" },
      { t = "text", s = "¡Gracias!" },
      { t = "eos" },
    },
  ["g3:0818cc4f"] = {
      { t = "text", s = "He recibido la mejor educación" },
      { t = "nl" },
      { t = "text", s = "para tener la fuerza que tengo." },
      { t = "para" },
      { t = "text", s = "¡No pienso perder ante nadie!" },
      { t = "eos" },
    },
  ["g3:0818ccae"] = {
      { t = "text", s = "Gracias, ya no tengo la presión" },
      { t = "nl" },
      { t = "text", s = "de antes." },
      { t = "eos" },
    },
  ["g3:0818ccea"] = {
      { t = "text", s = "La cosa más mínima, me ponía" },
      { t = "nl" },
      { t = "text", s = "de mal humor." },
      { t = "para" },
      { t = "text", s = "Ahora, con respirar hondo," },
      { t = "nl" },
      { t = "text", s = "se me pasa." },
      { t = "eos" },
    },
  ["g3:0818cd49"] = {
      { t = "text", s = "LINO: Mi adorada ABA, ¡no hay" },
      { t = "nl" },
      { t = "text", s = "nadie que pueda con nosotros!" },
      { t = "eos" },
    },
  ["g3:0818cd75"] = {
      { t = "text", s = "LINO: Me parece que he bajado" },
      { t = "nl" },
      { t = "text", s = "la guardia..." },
      { t = "eos" },
    },
  ["g3:0818cd9c"] = {
      { t = "text", s = "LINO: Creo que ha sido una buena" },
      { t = "nl" },
      { t = "text", s = "experiencia para ABA. Gracias." },
      { t = "eos" },
    },
  ["g3:0818cde2"] = {
      { t = "text", s = "LINO: ¿Podrías luchar con los dos" },
      { t = "nl" },
      { t = "text", s = "a la vez?" },
      { t = "eos" },
    },
  ["g3:0818ce20"] = {
      { t = "text", s = "ABA: Me esforzaré mucho para no" },
      { t = "nl" },
      { t = "text", s = "defraudar a mi maestro LINO." },
      { t = "eos" },
    },
  ["g3:0818ce5a"] = {
      { t = "text", s = "ABA: Oooh... Lo siento..." },
      { t = "eos" },
    },
  ["g3:0818ce78"] = {
      { t = "text", s = "ABA: Creo que voy a necesitar que" },
      { t = "nl" },
      { t = "text", s = "LINO me tutele y me oriente más..." },
      { t = "para" },
      { t = "text", s = "LINO, ¿te parece bien?..." },
      { t = "eos" },
    },
  ["g3:0818cef4"] = {
      { t = "text", s = "ABA: Lo siento, pero queremos" },
      { t = "nl" },
      { t = "text", s = "luchar dos contra dos." },
      { t = "eos" },
    },
  ["g3:0818cf2b"] = {
      { t = "text", s = "CAÑÓN SÉTANO" },
      { t = "nl" },
      { t = "text", s = "HACIA LAS RUINAS SETE" },
      { t = "eos" },
    },
  ["g3:0818cf4d"] = {
      { t = "text", s = "Entrenarse uno mismo no está mal." },
      { t = "para" },
      { t = "text", s = "Pero tampoco está mal buscar" },
      { t = "nl" },
      { t = "text", s = "una buena pareja de combate." },
      { t = "para" },
      { t = "text", s = "Fíjate en BRUNO..." },
      { t = "nl" },
      { t = "text", s = "Él se entrenó con un tal MARCIAL." },
      { t = "eos" },
    },
  ["g3:0818cffb"] = {
      { t = "text", s = "¿Sabes algo de esta cámara" },
      { t = "nl" },
      { t = "text", s = "de piedra?" },
      { t = "eos" },
    },
  ["g3:0818d02a"] = {
      { t = "text", s = "Oye, tampoco había que recurrir" },
      { t = "nl" },
      { t = "text", s = "a la fuerza." },
      { t = "eos" },
    },
  ["g3:0818d061"] = {
      { t = "text", s = "Las RUINAS SETE tienen unos" },
