      { t = "text", s = "1.500 años." },
      { t = "para" },
      { t = "text", s = "Pero nadie ha conseguido averiguar" },
      { t = "nl" },
      { t = "text", s = "cuál es su razón de ser." },
      { t = "eos" },
    },
  ["g3:0818d0d9"] = {
      { t = "text", s = "Dicen que aquí dentro duerme" },
      { t = "nl" },
      { t = "text", s = "un mítico POKéMON." },
      { t = "eos" },
    },
  ["g3:0818d108"] = {
      { t = "text", s = "A mí lo de los combates no se me" },
      { t = "nl" },
      { t = "text", s = "da bien." },
      { t = "eos" },
    },
  ["g3:0818d125"] = {
      { t = "text", s = "Yo he oído que hay otras ruinas" },
      { t = "nl" },
      { t = "text", s = "como éstas." },
      { t = "para" },
      { t = "text", s = "¿Serán lugares de descanso de" },
      { t = "nl" },
      { t = "text", s = "otros míticos POKéMON?" },
      { t = "eos" },
    },
  ["g3:0818d18f"] = {
      { t = "text", s = "CLEN está enseñándome a pintar." },
      { t = "eos" },
    },
  ["g3:0818d1b5"] = {
      { t = "text", s = "Igual nos llaman la atención" },
      { t = "nl" },
      { t = "text", s = "por haber hecho tanto ruido." },
      { t = "eos" },
    },
  ["g3:0818d1e3"] = {
      { t = "text", s = "Yo quería pintar un edificio" },
      { t = "nl" },
      { t = "text", s = "antiguo." },
      { t = "para" },
      { t = "text", s = "Por eso me trajo CLEN hasta aquí." },
      { t = "eos" },
    },
  ["g3:0818d22f"] = {
      { t = "text", s = "Hoy, como complemento a la clase," },
      { t = "nl" },
      { t = "text", s = "hemos venido a visitar la cámara." },
      { t = "eos" },
    },
  ["g3:0818d26d"] = {
      { t = "text", s = "Qué barbaridad..." },
      { t = "eos" },
    },
  ["g3:0818d284"] = {
      { t = "text", s = "Así que tú estudias a los POKéMON" },
      { t = "nl" },
      { t = "text", s = "por tu cuenta..." },
      { t = "para" },
      { t = "text", s = "La verdad es que es digno" },
      { t = "nl" },
      { t = "text", s = "de admiración..." },
      { t = "eos" },
    },
  ["g3:0818d2f0"] = {
      { t = "text", s = "MAMÁ: En fin..." },
      { t = "nl" },
      { t = "text", s = "Todos los niños se van de casa" },
      { t = "scroll" },
      { t = "text", s = "algún día. ¡Así es la vida!" },
      { t = "para" },
      { t = "text", s = "Ah, nuestro vecino, el PROF. OAK," },
      { t = "nl" },
      { t = "text", s = "quería verte." },
      { t = "eos" },
    },
  ["g3:0818d360"] = {
      { t = "text", s = "MAMÁ: En fin..." },
      { t = "nl" },
      { t = "text", s = "Todos los niños se van de casa" },
      { t = "scroll" },
      { t = "text", s = "algún día. ¡Así es la vida!" },
      { t = "para" },
      { t = "text", s = "Ah, nuestro vecino, el PROF. OAK," },
      { t = "nl" },
      { t = "text", s = "quería verte." },
      { t = "eos" },
    },
  ["g3:0818d3d1"] = {
      { t = "text", s = "MAMÁ: ¡" },
      { t = "player" },
      { t = "text", s = "!" },
      { t = "nl" },
      { t = "text", s = "Deberías tomarte un descanso." },
      { t = "eos" },
    },
  ["g3:0818d3f8"] = {
