      { t = "text", s = "son ARTICUNO, ZAPDOS y MOLTRES." },
      { t = "para" },
      { t = "text", s = "Desconocemos sus guaridas." },
      { t = "para" },
      { t = "text", s = "Pensamos explorar la cueva" },
      { t = "nl" },
      { t = "text", s = "que hay cerca de la CELESTE." },
      { t = "para" },
      { t = "text", s = "De: EQUIPO de INVESTIGACIÓN" },
      { t = "nl" },
      { t = "text", s = "POKéMON..." },
      { t = "eos" },
    },
  ["g3:0819a128"] = {
      { t = "text", s = "¡Un bote de ámbar!" },
      { t = "eos" },
    },
  ["g3:0819a137"] = {
      { t = "text", s = "¡Tac-tac-tac! Voy a enseñarte" },
      { t = "nl" },
      { t = "text", s = "un movimiento estupendo." },
      { t = "para" },
      { t = "text", s = "Enséñaselo a un POKéMON," },
      { t = "nl" },
      { t = "text", s = "verás qué guay es." },
      { t = "para" },
      { t = "text", s = "Se llama METRÓNOMO, no me" },
      { t = "nl" },
      { t = "text", s = "digas que no suena bien..." },
      { t = "eos" },
    },
  ["g3:0819a1cb"] = {
      { t = "text", s = "Te lo digo, es el no va más." },
      { t = "eos" },
    },
  ["g3:0819a1ea"] = {
