      { t = "nl" },
      { t = "text", s = "le enseñe METRÓNOMO?" },
      { t = "eos" },
    },
  ["g3:0819a20e"] = {
      { t = "text", s = "¡Tac-tac-tac!" },
      { t = "nl" },
      { t = "text", s = "¡Ése es el sonido de un METRÓNOMO!" },
      { t = "para" },
      { t = "text", s = "¡Lleva al POKéMON a usar ataques" },
      { t = "nl" },
      { t = "text", s = "que no conoce!" },
      { t = "eos" },
    },
  ["g3:0819a282"] = {
      { t = "text", s = "¡Hola!" },
      { t = "para" },
      { t = "text", s = "¡Soy un científico muy importante!" },
      { t = "nl" },
      { t = "text", s = "Mucho, sí, sí." },
      { t = "para" },
      { t = "text", s = "¡Y me dedico a estudiar fósiles" },
      { t = "nl" },
      { t = "text", s = "de POKéMON raros!" },
      { t = "para" },
      { t = "text", s = "¿Tienes algún fósil para mí?" },
      { t = "eos" },
    },
  ["g3:0819a314"] = {
      { t = "text", s = "¡No!" },
      { t = "nl" },
      { t = "text", s = "¡Qué pena!" },
      { t = "eos" },
    },
  ["g3:0819a34f"] = {
      { t = "text", s = "¿Dónde estabas?" },
      { t = "para" },
      { t = "text", s = "¡Tu fósil ha revivido!" },
      { t = "nl" },
      { t = "text", s = "¡Sabía que era un " },
      { t = "strvar", n = 1 },
      { t = "text", s = "!" },
      { t = "eos" },
    },
  ["g3:0819a39e"] = {
      { t = "text", s = "¡" },
      { t = "player" },
      { t = "text", s = " recibió " },
      { t = "strvar", n = 1 },
      { t = "nl" },
      { t = "text", s = "de manos del científico!" },
      { t = "eos" },
    },
  ["g3:0819a3d4"] = {
      { t = "text", s = "¡Oh! ¡Es un " },
      { t = "strvar", n = 2 },
      { t = "text", s = "!" },
      { t = "para" },
      { t = "text", s = "¡Es un fósil de " },
      { t = "strvar", n = 1 },
      { t = "text", s = "," },
      { t = "nl" },
      { t = "text", s = "un POKéMON ya extinto!" },
      { t = "para" },
      { t = "text", s = "¡Mi máquina recuperadora" },
      { t = "nl" },
      { t = "text", s = "hará que este POKéMON reviva!" },
      { t = "eos" },
    },
  ["g3:0819a4ab"] = {
      { t = "text", s = "¡Tardaré un poco!" },
      { t = "para" },
      { t = "text", s = "¡Date un paseo mientras tanto!" },
      { t = "eos" },
    },
  ["g3:0819a4e1"] = {
      { t = "text", s = "¡Eh!" },
      { t = "nl" },
      { t = "text", s = "¡Has venido a molestarme!" },
      { t = "eos" },
    },
  ["g3:0819a4f8"] = {
      { t = "text", s = "Quería entrar en el GIMNASIO" },
      { t = "nl" },
      { t = "text", s = "de CANELA, pero la puerta" },
      { t = "scroll" },
      { t = "text", s = "está cerrada a cal y canto." },
      { t = "para" },
      { t = "text", s = "Debe de haber una llave por" },
      { t = "nl" },
      { t = "text", s = "algún sitio." },
      { t = "para" },
      { t = "text", s = "¿Estará en la mansión quemada" },
      { t = "nl" },
      { t = "text", s = "esa?" },
      { t = "para" },
      { t = "text", s = "Dicen que está habitada por un" },
      { t = "nl" },
      { t = "text", s = "amigo del LÍDER del GIMNASIO." },
      { t = "eos" },
    },
  ["g3:0819a5be"] = {
      { t = "text", s = "¿Tienes muchos amigos?" },
      { t = "para" },
      { t = "text", s = "Está muy bien que te conectes" },
      { t = "nl" },
      { t = "text", s = "con ellos, por supuesto." },
      { t = "para" },
      { t = "text", s = "Pero si visitas la SALA UNIÓN" },
      { t = "nl" },
      { t = "text", s = "de vez en cuando, puede que" },
      { t = "scroll" },
      { t = "text", s = "hagas nuevos amigos." },
      { t = "para" },
      { t = "text", s = "Creo que merecería la pena que" },
      { t = "nl" },
      { t = "text", s = "fueras a la SALA UNIÓN." },
      { t = "eos" },
    },
  ["g3:0819a6b1"] = {
      { t = "text", s = "Los POKéMON pueden seguir" },
      { t = "nl" },
      { t = "text", s = "aprendiendo técnicas aunque hayas" },
      { t = "scroll" },
      { t = "text", s = "cancelado su evolución." },
      { t = "para" },
      { t = "text", s = "La evolución puede esperar hasta" },
      { t = "nl" },
      { t = "text", s = "que hayan aprendido nuevos" },
      { t = "scroll" },
      { t = "text", s = "movimientos." },
      { t = "eos" },
    },
  ["g3:0819a725"] = {
      { t = "text", s = "BILL: ¡Eh, llevo la tira" },
      { t = "nl" },
      { t = "text", s = "esperando!" },
      { t = "scroll" },
      { t = "text", s = "¿Nos vamos a ISLA PRIMA?" },
      { t = "eos" },
    },
  ["g3:0819a766"] = {
      { t = "text", s = "¿Todavía no?" },
      { t = "eos" },
    },
  ["g3:0819a785"] = {
      { t = "text", s = "Venga, pues vamos." },
      { t = "eos" },
    },
  ["g3:0819a7a0"] = {
      { t = "text", s = "¿No tienes ATAQUE X?" },
      { t = "para" },
      { t = "text", s = "¡Es estupendo para luchar!" },
      { t = "eos" },
    },
  ["g3:0819a7f1"] = {
      { t = "text", s = "¡Está bien tener más objetos!" },
      { t = "eos" },
    },
  ["g3:0819a837"] = {
      { t = "text", s = "¡Hola, aspirante al título!" },
      { t = "para" },
      { t = "text", s = "En la LIGA POKéMON tendrás que" },
      { t = "nl" },
      { t = "text", s = "luchar contra todos los miembros" },
      { t = "scroll" },
      { t = "text", s = "del ALTO MANDO, uno tras otro." },
      { t = "para" },
      { t = "text", s = "¡Si pierdes, tendrás que volver" },
      { t = "nl" },
      { t = "text", s = "a empezar!" },
      { t = "para" },
      { t = "text", s = "¡Eso es todo!" },
      { t = "nl" },
      { t = "text", s = "¡A por ellos!" },
      { t = "eos" },
    },
  ["g3:0819a8d8"] = {
      { t = "text", s = "¡Ahora lucharás contra todos los" },
      { t = "nl" },
      { t = "text", s = "del ALTO MANDO, sin excepción!" },
      { t = "para" },
      { t = "text", s = "¡Si ganas, se abrirá una puerta" },
      { t = "nl" },
      { t = "text", s = "y pasarás al siguiente ENTRENADOR!" },
      { t = "scroll" },
      { t = "text", s = "¡Buena suerte!" },
      { t = "eos" },
    },
  ["g3:0819a943"] = {
      { t = "text", s = "Lo siento, pero has perdido" },
      { t = "nl" },
      { t = "text", s = "el tiempo viniendo hasta aquí." },
      { t = "para" },
      { t = "text", s = "LORELEI, del ALTO MANDO," },
      { t = "nl" },
      { t = "text", s = "no está, como puedes comprobar." },
      { t = "para" },
      { t = "text", s = "Así que la LIGA POKéMON está" },
      { t = "nl" },
      { t = "text", s = "cerrada de momento." },
      { t = "eos" },
    },
  ["g3:0819a9e7"] = {
      { t = "text", s = "Los POKéMON de tipo FANTASMA" },
      { t = "nl" },
      { t = "text", s = "de AGATHA son escalofriantemente" },
      { t = "scroll" },
      { t = "text", s = "fuertes." },
      { t = "para" },
      { t = "text", s = "Yo me puse a criar a mis POKéMON" },
      { t = "nl" },
      { t = "text", s = "del tipo LUCHA con todas las ganas" },
      { t = "scroll" },
      { t = "text", s = "del mundo..." },
      { t = "para" },
      { t = "text", s = "Y me planté ante AGATHA convencido" },
      { t = "nl" },
      { t = "text", s = "de que podría ganar... y no quiero" },
      { t = "scroll" },
      { t = "text", s = "ni contarte la paliza que me dio." },
      { t = "para" },
      { t = "text", s = "Además, ¡no sabes el genio que" },
      { t = "nl" },
      { t = "text", s = "tiene la señora!" },
      { t = "para" },
      { t = "text", s = "¡Como empiece a gritar, lo llevas" },
      { t = "nl" },
      { t = "text", s = "claro!" },
      { t = "eos" },
    },
  ["g3:0819ab16"] = {
      { t = "text", s = "Yo creo que lo de ser del ALTO" },
      { t = "nl" },
      { t = "text", s = "MANDO se lleva en la sangre." },
      { t = "para" },
      { t = "text", s = "Por lo que sé, un primo de LANCE" },
