      { t = "para" },
      { t = "text", s = "¡Me he emocionado y todo!" },
      { t = "para" },
      { t = "text", s = "¡Qué manera de usar las técnicas," },
      { t = "nl" },
      { t = "text", s = "con qué seguridad y destreza!" },
      { t = "para" },
      { t = "text", s = "¡Qué pulso!" },
      { t = "nl" },
      { t = "text", s = "¡Fuerza contra fuerza!" },
      { t = "para" },
      { t = "text", s = "¡Sí, señor!" },
      { t = "nl" },
      { t = "text", s = "¡Magnífico, colosal, apoteósico!" },
      { t = "eos" },
    },
  ["g3:081a0971"] = {
