      { t = "text", s = "en ella para seguir adelante!" },
      { t = "para" },
      { t = "text", s = "¡No te olvides de esta derrota" },
      { t = "nl" },
      { t = "text", s = "y entrénate el doble!" },
      { t = "eos" },
    },
  ["g3:081a0a4f"] = {
      { t = "text", s = "Los POKéMON tienen su propia" },
