      { t = "text", s = "no para." },
      { t = "eos" },
    },
  ["g3:081a0acc"] = {
      { t = "text", s = "Bueno, ya lo tengo todo para" },
      { t = "nl" },
      { t = "text", s = "explorar las RUINAS." },
      { t = "eos" },
    },
  ["g3:081a0b09"] = {
