      { t = "eos" },
    },
  ["g3:081a437a"] = {
      { t = "text", s = "CONSU: Estoy hasta el gorro." },
      { t = "nl" },
      { t = "text", s = "¡Llevo esperándote un montón!" },
      { t = "para" },
