      { t = "nl" },
      { t = "text", s = "el sistema de comunicación" },
      { t = "scroll" },
      { t = "text", s = "inalámbrica." },
      { t = "para" },
      { t = "text", s = "Primero, te enseñaré esta planta" },
      { t = "nl" },
      { t = "text", s = "de nuestro CENTRO POKéMON." },
      { t = "para" },
      { t = "text", s = "Por aquí, por favor." },
      { t = "eos" },
    },
  ["g3:081bd966"] = {
