      { t = "para" },
      { t = "text", s = "En ella puedes conectarte con los" },
      { t = "nl" },
      { t = "text", s = "ENTRENADORES que también" },
      { t = "para" },
      { t = "text", s = "hayan entrado en la SALA UNIÓN" },
      { t = "nl" },
      { t = "text", s = "y estén cerca de ti." },
      { t = "para" },
      { t = "text", s = "Con ellos, podrás chatear, luchar" },
      { t = "nl" },
      { t = "text", s = "y realizar intercambios." },
      { t = "para" },
      { t = "text", s = "Ahora, la sala de la derecha:" },
      { t = "nl" },
      { t = "text", s = "la ZONA DIRECTA." },
      { t = "para" },
