      { t = "text", s = "conectarte a tus amigos con un" },
      { t = "nl" },
      { t = "text", s = "cable Game Link de Game Boy" },
      { t = "scroll" },
      { t = "text", s = "Advance." },
      { t = "para" },
      { t = "text", s = "Para ello hay que ir a la ZONA" },
      { t = "nl" },
      { t = "text", s = "DIRECTA." },
      { t = "para" },
      { t = "text", s = "Espero que disfrutes del sistema" },
