    },
  ["g3:081bef88"] = {
      { t = "text", s = "Hola, me alegro de verte." },
      { t = "para" },
      { t = "text", s = "Eh, he dicho hola..." },
      { t = "nl" },
      { t = "text", s = "Qué borde... ya podrías" },
      { t = "scroll" },
      { t = "text", s = "contestar." },
      { t = "para" },
      { t = "text", s = "Venga, cuéntame algo, anda." },
      { t = "para" },
      { t = "text", s = "¡Dime al menos cuál es tu perfil!" },
      { t = "eos" },
    },
  ["g3:081bf017"] = {
      { t = "text", s = "Cuéntame alguna cosa sobre ti." },
      { t = "nl" },
      { t = "text", s = "Dime cuál es tu perfil." },
      { t = "eos" },
    },
  ["g3:081bf053"] = {
      { t = "text", s = "El perfil puede hacerse con" },
