      { t = "para" },
      { t = "text", s = "Hay muchas palabras y frases" },
      { t = "nl" },
      { t = "text", s = "para elegir, y están divididas" },
      { t = "scroll" },
      { t = "text", s = "por grupos." },
      { t = "para" },
      { t = "text", s = "Selecciona primero un grupo" },
      { t = "nl" },
      { t = "text", s = "y después el elemento que quieras." },
      { t = "para" },
      { t = "text", s = "Es mucho más fácil de lo que" },
      { t = "nl" },
      { t = "text", s = "parece. Inténtalo, anda." },
      { t = "eos" },
    },
  ["g3:081bf166"] = {
      { t = "text", s = "¿Cuál es tu perfil?" },
      { t = "eos" },
    },
  ["g3:081bf17b"] = {
      { t = "text", s = "Venga, anda, enséñame tu perfil..." },
      { t = "eos" },
    },
  ["g3:081bf1b2"] = {
