      { t = "text", s = "¡Pues hay que ver cómo eres!" },
      { t = "eos" },
    },
  ["g3:081bf1e8"] = {
      { t = "text", s = "¡Hola otra vez!" },
      { t = "eos" },
    },
  ["g3:081bf1fb"] = {
      { t = "text", s = "¿Quieres cambiar tu perfil?" },
      { t = "eos" },
    },
  ["g3:081bf222"] = {
