      { t = "para" },
      { t = "text", s = "¡Ahora nos conocemos mejor!" },
      { t = "nl" },
      { t = "text", s = "¡Vamos a llevarnos bien siempre!" },
      { t = "eos" },
    },
  ["g3:081bf30d"] = {
      { t = "text", s = "Eso ya lo he oído antes..." },
