    },
  ["g3:081c155d"] = {
      { t = "text", s = "¡Esa mirada tuya fue de lo más" },
      { t = "nl" },
      { t = "text", s = "misteriosa!" },
      { t = "eos" },
    },
  ["g3:081c1588"] = {
      { t = "text", s = "¡Oye!" },
      { t = "nl" },
      { t = "text", s = "¡No llevas pantalón corto!" },
      { t = "eos" },
    },
  ["g3:081c15c5"] = {
      { t = "text", s = "Lucharé contigo junto a los" },
      { t = "nl" },
      { t = "text", s = "POKéMON que yo mismo he criado." },
      { t = "eos" },
    },
  ["g3:081c15f9"] = {
      { t = "text", s = "¡Eh!" },
      { t = "nl" },
      { t = "text", s = "¡Me has empujado!" },
      { t = "eos" },
    },
  ["g3:081c160f"] = {
      { t = "text", s = "A mí me encanta buscar POKéMON" },
      { t = "nl" },
      { t = "text", s = "hongo en el MT. MOON." },
      { t = "eos" },
    },
  ["g3:081c163c"] = {
      { t = "text", s = "¡Tu eres la pesadilla que nos" },
      { t = "nl" },
      { t = "text", s = "dio la paliza!" },
      { t = "eos" },
    },
  ["g3:081c166d"] = {
      { t = "text", s = "Perdona, ¿no ves que es una" },
      { t = "nl" },
      { t = "text", s = "conversación privada?" },
      { t = "para" },
      { t = "text", s = "Pues ¿qué haces con la antena" },
      { t = "nl" },
      { t = "text", s = "puesta?" },
      { t = "eos" },
    },
  ["g3:081c16e2"] = {
      { t = "text", s = "Estoy intentando encontrar un buen" },
      { t = "nl" },
      { t = "text", s = "ejemplar, que no sea un POKéMON" },
      { t = "scroll" },
      { t = "text", s = "BICHO, pero..." },
      { t = "eos" },
    },
  ["g3:081c1723"] = {
      { t = "text", s = "¿Qué? ¿Qué quieres, luchar" },
      { t = "nl" },
      { t = "text", s = "conmigo de nuevo?" },
      { t = "eos" },
    },
  ["g3:081c1746"] = {
      { t = "text", s = "¿Yo?" },
      { t = "nl" },
      { t = "text", s = "Pues vale. ¡Vamos!" },
      { t = "eos" },
    },
  ["g3:081c176b"] = {
      { t = "text", s = "Eh, ¡qué de tiempo!" },
      { t = "nl" },
      { t = "text", s = "¿Eres más fuerte?" },
      { t = "eos" },
    },
  ["g3:081c1793"] = {
      { t = "text", s = "Se te dan bien los POKéMON, pero" },
      { t = "nl" },
      { t = "text", s = "¿qué tal en química?" },
      { t = "eos" },
    },
  ["g3:081c17cd"] = {
      { t = "text", s = "¡Muy bien!" },
      { t = "nl" },
      { t = "text", s = "¡Luchemos otra vez!" },
      { t = "eos" },
    },
  ["g3:081c17f1"] = {
      { t = "text", s = "¡Necesitas una buena estrategia!" },
      { t = "para" },
      { t = "text", s = "¿Te queda claro?" },
      { t = "eos" },
    },
  ["g3:081c1834"] = {
      { t = "text", s = "Tengo muchos NIDORAN." },
      { t = "nl" },
      { t = "text", s = "No quiero que evolucionen, pero..." },
      { t = "eos" },
    },
  ["g3:081c1873"] = {
      { t = "text", s = "¡Me gusta el colegio y los" },
      { t = "nl" },
      { t = "text", s = "POKéMON!" },
      { t = "eos" },
    },
  ["g3:081c18aa"] = {
      { t = "text", s = "¡MEOWTH y PERSIAN son ideales," },
      { t = "nl" },
      { t = "text", s = "ideales totales, meow, meow, meow!" },
      { t = "eos" },
    },
  ["g3:081c18dc"] = {
      { t = "text", s = "Debemos de dar una imagen algo" },
      { t = "nl" },
      { t = "text", s = "tonta, pero ¡lo importante es que" },
      { t = "scroll" },
      { t = "text", s = "yo quiero luchar!" },
      { t = "eos" },
    },
  ["g3:081c191f"] = {
      { t = "text", s = "¡Soy un jugador errante!" },
      { t = "nl" },
      { t = "text", s = "¡Y voy a ganar!" },
      { t = "eos" },
    },
  ["g3:081c1955"] = {
      { t = "text", s = "¿Qué POKéMON es mono, redondo" },
      { t = "nl" },
      { t = "text", s = "y blando?" },
      { t = "para" },
      { t = "text", s = "Lo sabes, ¿no?" },
      { t = "eos" },
    },
  ["g3:081c199c"] = {
      { t = "text", s = "¡Mi bici sigue yendo como" },
      { t = "nl" },
      { t = "text", s = "una moto!" },
      { t = "eos" },
    },
  ["g3:081c19bc"] = {
      { t = "text", s = "Bueno, esta vez no me voy" },
      { t = "nl" },
      { t = "text", s = "a andar con tonterías." },
      { t = "eos" },
    },
  ["g3:081c19e5"] = {
      { t = "text", s = "TITA: ¡Ahora somos más fuertes!" },
      { t = "eos" },
    },
  ["g3:081c1a0d"] = {
      { t = "text", s = "LIN: ¡Ya somos mucho más fuertes!" },
      { t = "eos" },
    },
  ["g3:081c1a2e"] = {
      { t = "text", s = "¿Vamos a luchar de nuevo?" },
      { t = "nl" },
      { t = "text", s = "¡Pues esta vez, olvídate!" },
      { t = "eos" },
    },
  ["g3:081c1a5d"] = {
      { t = "text", s = "Tú eras quien tenía esos POKéMON" },
      { t = "nl" },
      { t = "text", s = "tan bonitos..." },
      { t = "eos" },
    },
  ["g3:081c1a9b"] = {
      { t = "text", s = "Quiero tomar el TÚNEL ROCA" },
      { t = "nl" },
      { t = "text", s = "para ir a LAVANDA." },
      { t = "para" },
      { t = "text", s = "¡Pero cada dos por tres se cruza" },
      { t = "nl" },
      { t = "text", s = "alguien en mi camino!..." },
      { t = "eos" },
    },
  ["g3:081c1afb"] = {
      { t = "text", s = "¡No te andes con contemplaciones!" },
      { t = "nl" },
      { t = "text", s = "¡Hay que ir a por todas!" },
      { t = "eos" },
    },
  ["g3:081c1b37"] = {
      { t = "text", s = "¡Qué bien! ¡Me estaba aburriendo" },
      { t = "nl" },
      { t = "text", s = "otra vez!" },
      { t = "eos" },
    },
  ["g3:081c1b5e"] = {
      { t = "text", s = "¡Jaja! ¡A ver lo fuerte que estás!" },
      { t = "eos" },
    },
  ["g3:081c1b83"] = {
      { t = "text", s = "Cada día me levanto temprano para" },
      { t = "nl" },
      { t = "text", s = "entrenar a mis POKéMON capullo." },
      { t = "eos" },
    },
  ["g3:081c1bbe"] = {
      { t = "text", s = "¡Esta vez gano yo!" },
      { t = "eos" },
    },
  ["g3:081c1bdc"] = {
      { t = "text", s = "¡Adelante de nuevo, mis geniales" },
      { t = "nl" },
      { t = "text", s = "POKéMON BICHO!" },
      { t = "eos" },
    },
  ["g3:081c1bfa"] = {
      { t = "text", s = "Aquí estás otra vez..." },
      { t = "nl" },
      { t = "text", s = "¿Eres como los POKéMANÍACOS?" },
      { t = "scroll" },
      { t = "text", s = "¿Quieres ver mi colección?" },
      { t = "eos" },
    },
  ["g3:081c1c4f"] = {
      { t = "text", s = "¡A-a-a-achís!" },
      { t = "nl" },
      { t = "text", s = "¡No puedo dejar de estornudar!" },
      { t = "eos" },
    },
  ["g3:081c1c76"] = {
      { t = "text", s = "¡Hola!" },
      { t = "nl" },
      { t = "text", s = "¿Te llegué a enseñar mis POKéMON?" },
      { t = "eos" },
    },
  ["g3:081c1c9a"] = {
      { t = "text", s = "He vuelto a ir al GIMNASIO" },
      { t = "nl" },
      { t = "text", s = "POKéMON." },
      { t = "para" },
      { t = "text", s = "Pero he perdido, como siempre..." },
      { t = "eos" },
    },
  ["g3:081c1cd3"] = {
      { t = "text", s = "¡Me encanta el aire de montaña!" },
      { t = "nl" },
      { t = "text", s = "¡Es tan bueno! ¡Me encanta!" },
      { t = "eos" },
    },
  ["g3:081c1d14"] = {
      { t = "text", s = "Me está empezando a dar vueltas la" },
      { t = "nl" },
      { t = "text", s = "cabeza. Llevo mucho escalando..." },
      { t = "eos" },
    },
  ["g3:081c1d50"] = {
      { t = "text", s = "¡Gana, pierde o empata!" },
      { t = "nl" },
      { t = "text", s = "¡Pero lucha de nuevo!" },
      { t = "eos" },
    },
  ["g3:081c1d79"] = {
      { t = "text", s = "¡Competir es lo más!" },
      { t = "nl" },
      { t = "text", s = "¡Yo no me canso de competir!" },
      { t = "eos" },
    },
  ["g3:081c1db5"] = {
      { t = "text", s = "¿Luchamos otra vez?" },
      { t = "nl" },
      { t = "text", s = "¡Vamos allá, pero no hagas" },
      { t = "scroll" },
      { t = "text", s = "trampas!" },
      { t = "eos" },
    },
  ["g3:081c1de1"] = {
      { t = "text", s = "¡Eh, tú!" },
      { t = "para" },
      { t = "text", s = "¡Cuidado!" },
      { t = "nl" },
      { t = "text", s = "¡Estoy colocando unos cables!" },
      { t = "eos" },
    },
  ["g3:081c1e1f"] = {
      { t = "text", s = "¡Soy un nuevo ENTRENADOR!" },
      { t = "nl" },
      { t = "text", s = "¡Pero creo que no tengo problema" },
      { t = "scroll" },
      { t = "text", s = "para ganar!" },
      { t = "eos" },
    },
  ["g3:081c1e57"] = {
      { t = "text", s = "¡Ja, ja, ja!" },
      { t = "nl" },
      { t = "text", s = "¡No he perdido nunca!" },
      { t = "para" },
      { t = "text", s = "¡Y si he perdido alguna vez," },
      { t = "nl" },
      { t = "text", s = "no me acuerdo!" },
      { t = "eos" },
    },
  ["g3:081c1e9f"] = {
      { t = "text", s = "Nunca he ganado..." },
      { t = "para" },
      { t = "text", s = "¿Será mi destino?" },
      { t = "eos" },
    },
  ["g3:081c1ee2"] = {
      { t = "text", s = "¡Soy el mejor de mi clase!" },
      { t = "nl" },
      { t = "text", s = "¡Me entreno día y noche!" },
      { t = "eos" },
    },
  ["g3:081c1f1d"] = {
      { t = "text", s = "¡Cuidado con esos cables!" },
      { t = "eos" },
    },
  ["g3:081c1f40"] = {
      { t = "text", s = "¡Mis POKéMON ya deberían estar" },
      { t = "nl" },
      { t = "text", s = "listos! ¡Esta vez hay que ganar!" },
      { t = "eos" },
    },
  ["g3:081c1f9d"] = {
      { t = "text", s = "¡Bien!" },
      { t = "nl" },
      { t = "text", s = "¡Ha picado algo!" },
      { t = "scroll" },
      { t = "text", s = "¡Esta vez seguro que es bueno!" },
      { t = "eos" },
    },
  ["g3:081c1fd8"] = {
      { t = "text", s = "¡Aquí estás otra vez!" },
      { t = "nl" },
      { t = "text", s = "¡Pescar requiere tiempo!" },
      { t = "eos" },
    },
  ["g3:081c2008"] = {
      { t = "text", s = "Sigo sin PIEDRA LUNAR..." },
      { t = "nl" },
      { t = "text", s = "¿Tienes tú una?" },
      { t = "eos" },
    },
  ["g3:081c203b"] = {
      { t = "text", s = "¡Soy un experto en electricidad!" },
      { t = "para" },
      { t = "text", s = "Pero de los POKéMON de agua" },
      { t = "nl" },
      { t = "text", s = "sé poca cosa..." },
      { t = "eos" },
    },
  ["g3:081c209c"] = {
      { t = "text", s = "¡El PESCADOR LOCO contra alguien" },
      { t = "nl" },
      { t = "text", s = "que no tiene idea sobre POKéMON!" },
      { t = "scroll" },
      { t = "text", s = "¡Lucha, venga!" },
      { t = "eos" },
    },
  ["g3:081c20d4"] = {
      { t = "text", s = "A mí me encanta pescar, pero no" },
      { t = "nl" },
      { t = "text", s = "es nada fácil que piquen, ¿sabes?" },
      { t = "eos" },
    },
  ["g3:081c2134"] = {
      { t = "text", s = "¿No sabes cómo pescar?" },
      { t = "para" },
      { t = "text", s = "¡Te lo explicaré cuando acabe" },
      { t = "nl" },
      { t = "text", s = "contigo!" },
      { t = "eos" },
    },
  ["g3:081c216b"] = {
      { t = "text", s = "ARE: Voy a ganar y a pedirle a" },
      { t = "nl" },
      { t = "text", s = "AGA que se case conmigo." },
      { t = "eos" },
    },
  ["g3:081c219b"] = {
      { t = "text", s = "AGA: Oye, ARE, estoy aburrida" },
      { t = "nl" },
      { t = "text", s = "de esperar..." },
      { t = "para" },
      { t = "text", s = "Si ganamos, ¡me caso contigo!" },
      { t = "eos" },
    },
  ["g3:081c21ee"] = {
      { t = "text", s = "¡Mis pájaros POKéMON se acuerdan" },
      { t = "nl" },
      { t = "text", s = "de ti!" },
      { t = "eos" },
    },
  ["g3:081c220c"] = {
      { t = "text", s = "Quiero ser la mejor ENTRENADORA" },
      { t = "nl" },
      { t = "text", s = "siendo todavía pequeña." },
      { t = "eos" },
    },
  ["g3:081c223c"] = {
      { t = "text", s = "¡Guau!" },
      { t = "nl" },
      { t = "text", s = "¡Qué chulas son tus MEDALLAS!" },
      { t = "eos" },
    },
  ["g3:081c225b"] = {
      { t = "text", s = "Mis simpáticos POKéMON quieren" },
      { t = "nl" },
      { t = "text", s = "volver a verte." },
      { t = "eos" },
    },
  ["g3:081c2299"] = {
      { t = "text", s = "Me he gastado mis ahorros" },
      { t = "nl" },
      { t = "text", s = "comprando más CARBURANTE." },
      { t = "eos" },
    },
  ["g3:081c22ca"] = {
      { t = "text", s = "¡Esta vez no pienso perder!" },
      { t = "nl" },
      { t = "text", s = "¡El viento sopla en mi dirección!" },
      { t = "eos" },
    },
  ["g3:081c2306"] = {
      { t = "text", s = "Has vuelto..." },
      { t = "para" },
      { t = "text", s = "Por supuesto que lucharé" },
      { t = "nl" },
      { t = "text", s = "otra vez contigo." },
      { t = "eos" },
    },
  ["g3:081c2340"] = {
      { t = "text", s = "¿No te acuerdas de que luchamos" },
      { t = "nl" },
      { t = "text", s = "en otra ocasión?" },
      { t = "eos" },
    },
  ["g3:081c236b"] = {
      { t = "text", s = "¿Qué miras?" },
      { t = "eos" },
    },
  ["g3:081c2383"] = {
      { t = "text", s = "¡Me encantan los pájaros POKéMON!" },
      { t = "eos" },
    },
  ["g3:081c23c1"] = {
      { t = "text", s = "He usado mis MT para enseñarles" },
      { t = "nl" },
      { t = "text", s = "buenos movimientos a mis POKéMON." },
      { t = "eos" },
    },
  ["g3:081c23ef"] = {
      { t = "text", s = "Mis pájaros POKéMON deberían" },
      { t = "nl" },
      { t = "text", s = "luchar bien esta vez." },
      { t = "eos" },
    },
  ["g3:081c2425"] = {
      { t = "text", s = "¿Usas MT con tus POKéMON?" },
      { t = "nl" },
      { t = "text", s = "Tenerlas en la MOCHILA sin más" },
      { t = "scroll" },
      { t = "text", s = "no sirve para nada." },
      { t = "eos" },
    },
  ["g3:081c2461"] = {
      { t = "text", s = "¿Has enseñado a VOLAR a tus" },
      { t = "nl" },
      { t = "text", s = "pájaros POKéMON?" },
      { t = "para" },
      { t = "text", s = "Deberías hacerlo y disfrutar de" },
      { t = "nl" },
      { t = "text", s = "la maravillosa vista." },
      { t = "eos" },
    },
  ["g3:081c24cb"] = {
      { t = "text", s = "¿Llegaste a oír hablar de los" },
      { t = "nl" },
      { t = "text", s = "misteriosos seres alados?" },
      { t = "eos" },
    },
  ["g3:081c2505"] = {
      { t = "text", s = "¡No me apetece luchar," },
      { t = "nl" },
      { t = "text", s = "pero lo haré!" },
      { t = "eos" },
    },
  ["g3:081c2531"] = {
      { t = "text", s = "¡Eh, me acuerdo de ti!" },
      { t = "para" },
      { t = "text", s = "¡Venga, venga!" },
      { t = "nl" },
      { t = "text", s = "¡Vamos, vamos! ¡Adelante!" },
      { t = "eos" },
    },
  ["g3:081c2572"] = {
      { t = "text", s = "Aquí estás otra vez, ¿eh?" },
      { t = "nl" },
      { t = "text", s = "¡Bueno, así pasaré el rato!" },
      { t = "eos" },
    },
  ["g3:081c259e"] = {
      { t = "text", s = "¡Nos gusta pedalear por aquí" },
      { t = "nl" },
      { t = "text", s = "porque hay mucho espacio!" },
      { t = "eos" },
    },
  ["g3:081c25d6"] = {
      { t = "text", s = "¿Quieres pelear con tus POKéMON?" },
      { t = "nl" },
      { t = "text", s = "¡Pues vale, vamos allá!" },
      { t = "eos" },
    },
  ["g3:081c25fb"] = {
      { t = "text", s = "LENA: TEA, a ver si ganamos." },
      { t = "eos" },
    },
  ["g3:081c261b"] = {
      { t = "text", s = "TEA: LENA, ¡vamos allá!" },
      { t = "nl" },
      { t = "text", s = "¡Tenemos que ganar!" },
      { t = "eos" },
    },
  ["g3:081c2650"] = {
      { t = "text", s = "¡Déjame probar los POKéMON" },
      { t = "nl" },
      { t = "text", s = "que me han enviado!" },
      { t = "eos" },
    },
  ["g3:081c268d"] = {
      { t = "text", s = "¡Creo que puedo contigo!" },
      { t = "nl" },
      { t = "text", s = "¡Voy a intentar vencerte!" },
      { t = "eos" },
    },
  ["g3:081c26d3"] = {
      { t = "text", s = "Cuando silbo, acuden varios" },
      { t = "nl" },
      { t = "text", s = "pájaros POKéMON." },
      { t = "para" },
      { t = "text", s = "¡Son monísimos!" },
      { t = "eos" },
    },
  ["g3:081c2717"] = {
      { t = "text", s = "Mis pájaros están temblando." },
      { t = "nl" },
      { t = "text", s = "¡Ya te conocen!" },
      { t = "eos" },
    },
  ["g3:081c2753"] = {
      { t = "text", s = "¡Oh!" },
      { t = "nl" },
      { t = "text", s = "¡Mira qué encanto!" },
      { t = "scroll" },
      { t = "text", s = "¡Anda, yo a ti te conozco!" },
      { t = "eos" },
    },
  ["g3:081c279d"] = {
      { t = "text", s = "¡Cuido POKéMON porque sigo" },
      { t = "nl" },
      { t = "text", s = "viviendo sola!" },
      { t = "eos" },
    },
  ["g3:081c27e7"] = {
      { t = "text", s = "¡Oye! ¡Ven aquí!" },
      { t = "nl" },
      { t = "text", s = "¡Mira esto!" },
      { t = "eos" },
    },
  ["g3:081c2814"] = {
      { t = "text", s = "¡Mira, colega, si pierdes contra" },
      { t = "nl" },
      { t = "text", s = "mí, todo tu dinero será mío!" },
      { t = "eos" },
    },
  ["g3:081c2846"] = {
      { t = "text", s = "¿Qué mola?" },
      { t = "nl" },
      { t = "text", s = "¡Cambiar POKéMON, claro!" },
      { t = "eos" },
    },
  ["g3:081c287d"] = {
      { t = "text", s = "¿Quieres jugar con mis POKéMON" },
      { t = "nl" },
      { t = "text", s = "otra vez?" },
      { t = "eos" },
    },
  ["g3:081c28a1"] = {
      { t = "text", s = "TINA: ¡Volvemos a vernos!" },
      { t = "para" },
      { t = "text", s = "¿Luchamos para que aprenda" },
      { t = "nl" },
      { t = "text", s = "mi hermano?" },
      { t = "eos" },
    },
  ["g3:081c28ec"] = {
      { t = "text", s = "TIN: Mi hermana es la más fuerte." },
      { t = "eos" },
    },
  ["g3:081c2913"] = {
      { t = "text", s = "¿Qué quieres?" },
      { t = "eos" },
    },
  ["g3:081c2925"] = {
      { t = "text", s = "¡Bonita BICI!" },
      { t = "nl" },
      { t = "text", s = "¡Dámela ahora mismo!" },
      { t = "eos" },
    },
  ["g3:081c2944"] = {
      { t = "text", s = "¡Baja de ahí y lucha, enclenque!" },
      { t = "nl" },
      { t = "text", s = "¡Te vas a enterar!" },
      { t = "eos" },
    },
  ["g3:081c297b"] = {
      { t = "text", s = "¡Oye! ¡Me has golpeado!" },
      { t = "nl" },
      { t = "text", s = "¡Ahora tendrás que luchar conmigo!" },
      { t = "eos" },
    },
  ["g3:081c29b0"] = {
      { t = "text", s = "¡Tengo hambre y sigo sin estar" },
      { t = "nl" },
      { t = "text", s = "de humor!" },
      { t = "eos" },
    },
  ["g3:081c29eb"] = {
      { t = "text", s = "¡Eh, vamos a echar otro rato!" },
      { t = "eos" },
    },
  ["g3:081c2a19"] = {
      { t = "text", s = "JOEL: ¿Vienes para comprobar que" },
      { t = "nl" },
      { t = "text", s = "nuestro amor no conoce límites?" },
      { t = "eos" },
    },
  ["g3:081c2a53"] = {
      { t = "text", s = "LIZ: ¡A veces, pienso en todo" },
      { t = "nl" },
      { t = "text", s = "lo que nos queremos y se me pone" },
      { t = "scroll" },
      { t = "text", s = "la carne de gallina!" },
      { t = "eos" },
    },
  ["g3:081c2a88"] = {
      { t = "text", s = "¡Ya te dije que no compensaba" },
      { t = "nl" },
      { t = "text", s = "luchar con niños!" },
      { t = "eos" },
    },
  ["g3:081c2ac4"] = {
      { t = "text", s = "¿Y tú qué quieres?" },
      { t = "eos" },
    },
  ["g3:081c2af0"] = {
      { t = "text", s = "¿Qué vas, de paseo?" },
      { t = "eos" },
    },
  ["g3:081c2b06"] = {
      { t = "text", s = "¡Somos los MOTORISTAS!" },
      { t = "nl" },
      { t = "text", s = "¡Las estrellas de la autopista!" },
      { t = "eos" },
    },
  ["g3:081c2b2c"] = {
      { t = "text", s = "Mis VOLTORB van a darte" },
      { t = "nl" },
      { t = "text", s = "un calambrazo." },
      { t = "eos" },
    },
  ["g3:081c2b5e"] = {
      { t = "text", s = "¡Mi POKéMON no evoluciona!" },
      { t = "nl" },
      { t = "text", s = "No acabo de entender por qué." },
      { t = "eos" },
    },
  ["g3:081c2b9c"] = {
      { t = "text", s = "¡Necesito un poco de ejercicio" },
      { t = "nl" },
      { t = "text", s = "y bajar peso!" },
      { t = "eos" },
    },
  ["g3:081c2bda"] = {
      { t = "text", s = "¡Sé rebelde!" },
      { t = "eos" },
    },
  ["g3:081c2be6"] = {
      { t = "text", s = "¡Tienes una BICI muy guay!" },
      { t = "nl" },
      { t = "text", s = "¿Cómo se conduce?" },
      { t = "eos" },
    },
  ["g3:081c2c10"] = {
      { t = "text", s = "¡Lárgate!" },
      { t = "nl" },
      { t = "text", s = "¡Estoy agotado!" },
      { t = "eos" },
    },
  ["g3:081c2c2b"] = {
      { t = "text", s = "Compruebo siempre las zonas de" },
      { t = "nl" },
      { t = "text", s = "hierba en busca de nuevos POKéMON." },
      { t = "para" },
      { t = "text", s = "Pero no siempre encuentro..." },
      { t = "eos" },
    },
  ["g3:081c2c7b"] = {
      { t = "text", s = "¡Cucu, cucu! ¿Ha mejorado" },
      { t = "nl" },
      { t = "text", s = "el reclamo de mi pájaro?" },
      { t = "eos" },
    },
  ["g3:081c2ca8"] = {
      { t = "text", s = "¡Es mi césped!" },
      { t = "nl" },
      { t = "text", s = "¡Fuera de aquí!" },
      { t = "para" },
      { t = "text", s = "¡No quiero volver a verte por" },
      { t = "nl" },
      { t = "text", s = "aquí!" },
      { t = "eos" },
    },
  ["g3:081c2cee"] = {
      { t = "text", s = "Estaba a punto de darme un baño." },
      { t = "eos" },
    },
  ["g3:081c2d19"] = {
      { t = "text", s = "¡Alto!" },
      { t = "nl" },
      { t = "text", s = "¡Oye, que te va a dar algo!" },
      { t = "eos" },
    },
  ["g3:081c2d4b"] = {
      { t = "text", s = "¡Me gusta nadar!" },
      { t = "nl" },
      { t = "text", s = "Seguro que a ti también." },
      { t = "eos" },
    },
  ["g3:081c2d7d"] = {
      { t = "text", s = "¿Qué hay más allá del horizonte?" },
      { t = "nl" },
      { t = "text", s = "¿Lo sabes?" },
      { t = "eos" },
    },
  ["g3:081c2da7"] = {
      { t = "text", s = "¡He buceado en busca de POKéMON," },
      { t = "nl" },
      { t = "text", s = "pero sigo sin ver nada!" },
      { t = "eos" },
    },
  ["g3:081c2de9"] = {
      { t = "text", s = "¡Miro al mar para olvidar!" },
      { t = "para" },
      { t = "text", s = "Quiero olvidarme de cuando perdí" },
      { t = "nl" },
      { t = "text", s = "contigo." },
      { t = "eos" },
    },
  ["g3:081c2e4a"] = {
      { t = "text", s = "¡Me encanta el POKéMON con" },
      { t = "nl" },
      { t = "text", s = "el que estás haciendo SURF." },
      { t = "para" },
      { t = "text", s = "¿Me lo darás si gano?" },
      { t = "eos" },
    },
  ["g3:081c2e9d"] = {
      { t = "text", s = "¡Nadar es genial! ¡Pero no me" },
      { t = "nl" },
      { t = "text", s = "gusta quemarme al sol!" },
      { t = "eos" },
    },
  ["g3:081c2ec0"] = {
      { t = "text", s = "¡Estas aguas son traicioneras!" },
      { t = "nl" },
      { t = "text", s = "¡No deberías volver por aquí!" },
      { t = "eos" },
    },
  ["g3:081c2efc"] = {
      { t = "text", s = "He venido nadando hasta aquí," },
      { t = "nl" },
      { t = "text", s = "pero ya me he cansado." },
      { t = "para" },
      { t = "text", s = "¿De verdad tenemos que luchar" },
      { t = "nl" },
      { t = "text", s = "otra vez?" },
      { t = "eos" },
    },
  ["g3:081c2f41"] = {
      { t = "text", s = "CATI: Ya sabes que mi hermano" },
      { t = "nl" },
      { t = "text", s = "acaba de hacerse ENTRENADOR." },
      { t = "para" },
      { t = "text", s = "Vamos a luchar para que mejore" },
      { t = "nl" },
      { t = "text", s = "su técnica, ¿vale?" },
      { t = "eos" },
    },
  ["g3:081c2fae"] = {
      { t = "text", s = "TEC: Mi hermana mayor me ha" },
      { t = "nl" },
      { t = "text", s = "enseñado mucho sobre POKéMON." },
      { t = "para" },
      { t = "text", s = "¿Soy mejor ahora?" },
      { t = "eos" },
    },
  ["g3:081c2ff3"] = {
      { t = "text", s = "El agua es poco profunda aquí." },
      { t = "nl" },
      { t = "text", s = "Hay mucha gente nadando." },
      { t = "eos" },
    },
  ["g3:081c302e"] = {
      { t = "text", s = "¿Te da envidia que esté de" },
      { t = "nl" },
      { t = "text", s = "vacaciones en las ISLAS ESPUMA?" },
      { t = "eos" },
    },
  ["g3:081c305f"] = {
      { t = "text", s = "¡Me gusta flotar en el agua" },
      { t = "nl" },
      { t = "text", s = "rodeada de peces!" },
      { t = "eos" },
    },
  ["g3:081c3095"] = {
      { t = "text", s = "¿Tú también estabas de vacaciones?" },
      { t = "eos" },
    },
  ["g3:081c30b0"] = {
      { t = "text", s = "¡Mira que cuerpazo tengo!" },
      { t = "para" },
      { t = "text", s = "¡Estoy mejor que antes!" },
      { t = "eos" },
    },
  ["g3:081c30ed"] = {
      { t = "text", s = "¿Por qué te has subido a un" },
      { t = "nl" },
      { t = "text", s = "POKéMON? ¿Aún no sabes nadar?" },
      { t = "eos" },
    },
  ["g3:081c312c"] = {
      { t = "text", s = "¡He venido sobre uno de mis" },
      { t = "nl" },
      { t = "text", s = "pájaros POKéMON!" },
      { t = "eos" },
    },
  ["g3:081c3149"] = {
      { t = "text", s = "¡Mi novio me dio unas perlas" },
      { t = "nl" },
      { t = "text", s = "muy grandes!" },
      { t = "para" },
      { t = "text", s = "¡Y ahora están más grandes aún!" },
      { t = "eos" },
    },
  ["g3:081c3185"] = {
      { t = "text", s = "Vine nadando desde ISLA" },
      { t = "nl" },
      { t = "text", s = "CANELA. Fue agotador." },
      { t = "eos" },
    },
  ["g3:081c31c4"] = {
      { t = "text", s = "En ISLA CANELA, al oeste, hay" },
      { t = "nl" },
      { t = "text", s = "un LABORATORIO POKéMON." },
      { t = "para" },
      { t = "text", s = "Mi papi trabaja allí." },
      { t = "eos" },
    },
  ["g3:081c3208"] = {
      { t = "text", s = "¿Quieres saber si los peces pican?" },
      { t = "eos" },
    },
  ["g3:081c3231"] = {
      { t = "text", s = "¡Tengo una gran red!" },
      { t = "nl" },
      { t = "text", s = "¿Quieres probarla otra vez?" },
      { t = "eos" },
    },
  ["g3:081c3264"] = {
      { t = "text", s = "¡El mar limpia mi cuerpo y mi" },
      { t = "nl" },
      { t = "text", s = "alma!" },
      { t = "eos" },
    },
  ["g3:081c3298"] = {
      { t = "text", s = "¡He conseguido a mi POKéMON" },
      { t = "nl" },
      { t = "text", s = "en el mar, y aquí lo entreno!" },
      { t = "eos" },
    },
  ["g3:081c32d3"] = {
      { t = "text", s = "¡Ahora estoy en otro encuentro" },
      { t = "nl" },
      { t = "text", s = "de triatlón!" },
      { t = "eos" },
    },
  ["g3:081c32fd"] = {
      { t = "text", s = "¡Ah!" },
      { t = "nl" },
      { t = "text", s = "¡Siente el sol y el viento!" },
      { t = "eos" },
    },
  ["g3:081c331d"] = {
      { t = "text", s = "¡Eh!" },
      { t = "nl" },
      { t = "text", s = "¡Siempre asustas a los peces!" },
      { t = "eos" },
    },
  ["g3:081c3356"] = {
      { t = "text", s = "¡Quédate conmigo hasta que lo" },
      { t = "nl" },
      { t = "text", s = "consiga!" },
      { t = "eos" },
    },
  ["g3:081c3378"] = {
      { t = "text", s = "ÍA: ¿Cómo, que quieres luchar otra" },
      { t = "nl" },
      { t = "text", s = "vez? IGOR, ¿cómo lo ves?" },
      { t = "eos" },
    },
  ["g3:081c33ae"] = {
      { t = "text", s = "IGOR: Mi hermana es un pelín vaga," },
      { t = "nl" },
      { t = "text", s = "¡pero si hay que luchar, hay que" },
      { t = "scroll" },
      { t = "text", s = "luchar!" },
      { t = "eos" },
    },
  ["g3:081c33e7"] = {
      { t = "text", s = "¡No pienso perder!" },
      { t = "eos" },
    },
  ["g3:081c3404"] = {
      { t = "text", s = "¡Mi padre me llevó a una gran" },
      { t = "nl" },
      { t = "text", s = "fiesta en el S.S. ANNE, en" },
      { t = "scroll" },
      { t = "text", s = "CIUDAD CARMÍN!" },
      { t = "eos" },
    },
  ["g3:081c3445"] = {
      { t = "text", s = "Soy un buen chico." },
      { t = "nl" },
      { t = "text", s = "¡Y tengo novia!" },
      { t = "para" },
      { t = "text", s = "¡Verás cómo se queda cuando" },
      { t = "nl" },
      { t = "text", s = "me vea luchar esta vez!" },
      { t = "eos" },
    },
  ["g3:081c349c"] = {
      { t = "text", s = "¡Hola!" },
      { t = "nl" },
      { t = "text", s = "¡Mi chico es genial!" },
      { t = "scroll" },
      { t = "text", s = "¡Y hoy me encuentro en forma!" },
      { t = "eos" },
    },
  ["g3:081c34d4"] = {
      { t = "text", s = "¡Sabía que tendría que luchar" },
      { t = "nl" },
      { t = "text", s = "contigo otra vez!" },
      { t = "eos" },
    },
  ["g3:081c350a"] = {
      { t = "text", s = "Mi amigo tiene unos POKéMON" },
      { t = "nl" },
      { t = "text", s = "muy monos. ¡Qué envidia!" },
      { t = "eos" },
    },
  ["g3:081c353b"] = {
      { t = "text", s = "¡Acabo de bajar del MT. MOON," },
      { t = "nl" },
      { t = "text", s = "pero estoy listo!" },
      { t = "eos" },
    },
  ["g3:081c357e"] = {
      { t = "text", s = "¡Hay un POKéMANÍACO viviendo" },
      { t = "nl" },
      { t = "text", s = "en el cabo!" },
      { t = "para" },
      { t = "text", s = "¿Has visto la colección que tiene?" },
      { t = "eos" },
    },
  ["g3:081c35bc"] = {
      { t = "text", s = "¿Vas a ver a BILL otra vez?" },
      { t = "nl" },
      { t = "text", s = "¡Pues luchemos primero!" },
      { t = "eos" },
    },
  ["g3:081c35ee"] = {
      { t = "text", s = "¡Vi tu hazaña desde la hierba!" },
      { t = "eos" },
    },
  ["g3:081c360e"] = {
      { t = "text", s = "¡Muy bien, voy a acabar contigo!" },
      { t = "eos" },
    },
  ["g3:081c3624"] = {
      { t = "text", s = "Siempre estás de aquí para allá..." },
      { t = "nl" },
      { t = "text", s = "¿No te cansas?" },
      { t = "eos" },
    },
  ["g3:081c3657"] = {
      { t = "text", s = "Se ve que te encanta venir" },
      { t = "nl" },
      { t = "text", s = "al PUENTE PEPITA." },
      { t = "eos" },
    },
  ["g3:081c3685"] = {
      { t = "text", s = "Aunque perdí cuando luchamos," },
      { t = "nl" },
      { t = "text", s = "estuvo guay, ¿verdad?" },
      { t = "eos" },
    },
  ["g3:081c36da"] = {
      { t = "text", s = "Éste es el PUENTE PEPITA." },
      { t = "para" },
      { t = "text", s = "Ya nos has machacado a todos," },
      { t = "nl" },
      { t = "text", s = "así que ya te puedes marchar..." },
      { t = "para" },
      { t = "text", s = "Aunque... no me importaría" },
      { t = "nl" },
      { t = "text", s = "volver a enfrentarme a ti." },
      { t = "eos" },
    },
  ["g3:081c3773"] = {
      { t = "text", s = "Se me pasa el tiempo volando" },
      { t = "nl" },
      { t = "text", s = "cuando estoy disfrutando del agua," },
      { t = "scroll" },
      { t = "text", s = "del vaivén de las olas..." },
      { t = "eos" },
    },
  ["g3:081c37b5"] = {
      { t = "text", s = "Hace un tiempo espléndido," },
      { t = "nl" },
      { t = "text", s = "no lo estropees." },
      { t = "eos" },
    },
  ["g3:081c37e7"] = {
      { t = "text", s = "Está empezando a dolerme la piel" },
      { t = "nl" },
      { t = "text", s = "por las quemaduras." },
      { t = "eos" },
    },
  ["g3:081c3807"] = {
      { t = "text", s = "El MT. ASCUAS hace una sombra" },
      { t = "nl" },
      { t = "text", s = "gigante." },
      { t = "eos" },
    },
  ["g3:081c3835"] = {
      { t = "text", s = "Tengo la sensación de que esta vez" },
      { t = "nl" },
      { t = "text", s = "te voy a ganar." },
      { t = "eos" },
    },
  ["g3:081c386a"] = {
      { t = "text", s = "¡Eh, eh, un momento!" },
      { t = "nl" },
      { t = "text", s = "¡Sé que he pescado algo grande!" },
      { t = "eos" },
    },
  ["g3:081c389f"] = {
      { t = "text", s = "¿Me ayudas a entrenarme otra vez?" },
      { t = "eos" },
    },
  ["g3:081c38ca"] = {
      { t = "text", s = "No me pierdo ni un día de" },
      { t = "nl" },
      { t = "text", s = "entrenamiento." },
      { t = "eos" },
    },
  ["g3:081c38fa"] = {
      { t = "text", s = "Cada mañana, antes de desayunar," },
      { t = "nl" },
      { t = "text", s = "rodeo a nado la isla." },
      { t = "scroll" },
      { t = "text", s = "¡Lo hago hasta tres veces!" },
      { t = "eos" },
    },
  ["g3:081c3943"] = {
      { t = "text", s = "¡Para luchar hay que llevar ropa" },
      { t = "nl" },
      { t = "text", s = "adecuada! ¡Vaya pintas tienes!" },
      { t = "eos" },
    },
  ["g3:081c3987"] = {
      { t = "text", s = "Cuando se está al aire libre," },
      { t = "nl" },
      { t = "text", s = "todo sabe mucho mejor." },
      { t = "eos" },
    },
  ["g3:081c39c6"] = {
      { t = "text", s = "He vuelto a comer demasiado," },
      { t = "nl" },
      { t = "text", s = "¿luchamos para hacer algo" },
      { t = "scroll" },
      { t = "text", s = "de ejercicio?" },
      { t = "eos" },
    },
  ["g3:081c3a05"] = {
      { t = "text", s = "PÍA: ¡Mi hermano mayor y yo" },
      { t = "nl" },
      { t = "text", s = "hacemos un equipo increíble!" },
      { t = "para" },
      { t = "text", s = "¡Esta vez no perderemos!" },
      { t = "eos" },
    },
  ["g3:081c3a55"] = {
      { t = "text", s = "FER: ¡Junto a PÍA no tengo miedo" },
      { t = "nl" },
      { t = "text", s = "de nada!" },
      { t = "para" },
      { t = "text", s = "¡Esta vez te vas a enterar!" },
      { t = "eos" },
    },
  ["g3:081c3aa7"] = {
      { t = "text", s = "¿Quieres que luchemos de nuevo?" },
      { t = "eos" },
    },
  ["g3:081c3abf"] = {
      { t = "text", s = "¿De dónde vienes y adónde vas?" },
      { t = "eos" },
    },
  ["g3:081c3af2"] = {
      { t = "text", s = "Estoy deseando nadar sin flotador." },
      { t = "eos" },
    },
  ["g3:081c3b1d"] = {
      { t = "text", s = "¡POKéMON, POKéMON!" },
      { t = "nl" },
      { t = "text", s = "¡A mí me gustan los POKéMON!" },
      { t = "eos" },
    },
  ["g3:081c3b30"] = {
      { t = "text", s = "¡No, no, te dije que me dejaras" },
      { t = "nl" },
      { t = "text", s = "en paz!" },
      { t = "eos" },
    },
  ["g3:081c3b6e"] = {
      { t = "text", s = "FELI: Ahora somos más fuertes." },
      { t = "nl" },
      { t = "text", s = "¡Mucho más!" },
      { t = "eos" },
    },
  ["g3:081c3b99"] = {
      { t = "text", s = "MATI: ¡Hoy no podrás con nosotras!" },
      { t = "eos" },
    },
  ["g3:081c3bb7"] = {
      { t = "text", s = "Hola, ¿estás criando tus POKéMON" },
      { t = "nl" },
      { t = "text", s = "en un buen sitio?" },
      { t = "eos" },
    },
  ["g3:081c3bf6"] = {
      { t = "text", s = "¡Voy a alcanzar la victoria con mis" },
